/**
 * dsh-worktree-sidebar 浏览器端入口（干净模块：只 apply/inject，外壳由构建链生成）。
 *
 * 这里只做适配：把 `ctx` 收窄成各模块认得的窄面，把每个会话的绑定状态接成「改写源 + 生效根读数」。
 * 判断本身都在 `takeover.ts` / `inject.ts` / `source.ts` / `bindings.ts` 里。
 *
 * **没有定时轮询**：请求只在三个用户可感知的时机发出——打开 Files 页签、点官方刷新按钮、
 * 窗口重新可见/获得焦点（三处都在 `inject.ts` 的播种面里）；cwd 的改写只在 Files 正文内生效。
 */
import type { BindingResponse } from "../shared/interface.ts";
import { ROUTES } from "../shared/interface.ts";
import { createBindingState } from "./bindings.ts";
import { createInjectWrapper, releaseAllSeedings } from "./inject.ts";
import type {
  ClientSlotsPort,
  ObservablePort,
  ReadBinding,
  SessionView,
  SessionsSnapshotLike,
  TabsPort,
  ViewFor,
} from "./shared/ports.ts";
import { createSessionsSource } from "./source.ts";
import { installTakeover } from "./takeover.ts";

/**
 * 宿主端 `ROUTES` 经构建期 define 注入 `__DSH_ROUTES__`（bundle-host.ts）。
 *
 * 兜底必须写成 `typeof` 守卫：`declare const` 只活在类型层，非 bundle 环境（源码直接 import、
 * 单测、构建期收集）里这个标识符根本不存在，裸引用会当场 ReferenceError。所以契约常量留在
 * `src/shared/contract.ts` 根，注入缺失时用它——也是本包路由的单一事实源。
 */
declare const __DSH_ROUTES__: Record<string, string> | undefined;
const ROUTES_INJECTED = typeof __DSH_ROUTES__ !== "undefined" ? __DSH_ROUTES__ : ROUTES;
const BINDINGS_URL = ROUTES_INJECTED.bindings;

/** 读一次宿主绑定。任何失败都回 undefined，由调用方保持上次成功态（G6）。 */
const readBinding: ReadBinding = async (sessionId) => {
  try {
    const response = await fetch(BINDINGS_URL + "?session=" + encodeURIComponent(sessionId), {
      headers: { accept: "application/json" },
    });
    if (!response.ok) return undefined;
    // 响应形状来自根契约的单点定义：字段名在这里改不动，改了当场编译失败。
    const body = (await response.json()) as Partial<BindingResponse>;
    if (typeof body.revision !== "number") return undefined;
    return {
      revision: body.revision,
      worktreePath: typeof body.worktreePath === "string" ? body.worktreePath : null,
    };
  } catch {
    // 网络/解析失败与「没绑定」是两件事：这里回 undefined 而不是 null，
    // 调用方因此会保留上次成功态，而不是把根弹回 cwd。
    return undefined;
  }
};

/**
 * 浏览器端上下文的窄面。刻意不用 `any`：这几个面正是 `inject` 声明的那几个，
 * 写成结构类型之后，「多用一个服务却忘了声明」会在类型层先露出来。
 */
interface ClientContext {
  readonly slots: ClientSlotsPort;
  readonly sidebarRightTabs: TabsPort;
  /** 服务对象本身**不是**快照源：数据在 `ISessions.list` 上（真机实测见 ports.ts 的注释）。 */
  readonly sessions: { readonly list: ObservablePort<SessionsSnapshotLike> };
  readonly effect: (execute: () => () => void, label?: string) => unknown;
}

/**
 * 视图缓存上限。它是**内存**上限而不是会话上限：一个长期开着的窗口见过多少会话，就有多少套视图。
 * 淘汰最冷的那些是安全的——每套视图都是同一份宿主事实的独立读数（同一个端点、同一个 revision），
 * 被淘汰的视图若仍被渲染层持有，它读到的仍是宿主当前值，不会分叉。
 */
const VIEW_CACHE_MAX = 128;

export function apply(ctx: ClientContext): void {
  try {
    const views = new Map<string, SessionView>();

    /** 每个会话一套视图。同一 id 恒回同一对象：改写源与生效根读数都必须稳定。 */
    const viewFor: ViewFor = (sessionId) => {
      const cached = views.get(sessionId);
      if (cached !== undefined) {
        // 触碰即变新：淘汰的必须是**最冷**的会话，不能是当前正在渲染的那个。
        views.delete(sessionId);
        views.set(sessionId, cached);
        return cached;
      }
      const state = createBindingState(readBinding, sessionId);
      const source = createSessionsSource(ctx.sessions.list, sessionId, () => state.getSnapshot());
      // 绑定一变就通知渲染层重算快照：引用稳定的前提下，这是「树读到新 cwd」的唯一通道。
      // 订阅与视图同寿命（整包卸载时 views.clear() 一起丢掉），不另做存活性推断。
      state.subscribe(() => source.notify());
      const view: SessionView = { source, root: state };
      views.set(sessionId, view);
      if (views.size > VIEW_CACHE_MAX) {
        const coldest = views.keys().next().value;
        if (coldest !== undefined) views.delete(coldest);
      }
      return view;
    };

    // 接管块与 inject 改写块零互引：会话视图在这里绑进改写器，再交给接管块当依赖。
    const restore = installTakeover({
      slots: ctx.slots,
      tabs: ctx.sidebarRightTabs,
      logger: { warn: (message: string) => console.warn(message) },
      wrapInject: createInjectWrapper(viewFor),
    });

    ctx.effect(
      () => () => {
        restore();
        // 没有 signal 的播种面不会自己撤销（见 inject.ts），卸载时在这里统一收口。
        releaseAllSeedings();
        views.clear();
      },
      "dsh-worktree-sidebar: 会话视图与 files 页签接管",
    );
  } catch (error) {
    // 挂载失败一律降级：不注册任何东西，右栏保持官方行为。可感知地什么都不做，好过静默显示错的地方。
    console.warn("[dsh-worktree-sidebar] mount failed:", error);
  }
}

/**
 * 客户端契约。`slots` 是接管的落点（`sidebarRightTabs` 只用来读官方类型 id，我们从不写它），
 * `sessions.list` 是真实快照的来源，
 * `locale` 随官方组件的完整装配面一起被继承（本包不自带文案）。漏声明会在属性访问处抛
 * "without inject"；`sidebarRightTabs` 不存在时整体不激活——那说明官方包不在，我们无话可说。
 */
export const inject: string[] = ["slots", "sidebarRightTabs", "sessions", "locale"];

/**
 * 官方 entry inject 面的改写。本文件回答两件事：
 * 1. `hooks.sessions` 指向按会话的改写源（官方正文读到的 cwd）；
 * 2. **树根的播种时机**——覆盖 `start`/`load`，把「根 = 首帧读到的 cwd」改成「根 = 绑定解析后的生效根」。
 *
 * 为什么必须覆盖 `start`：官方只在 `state === undefined` 时用当帧的 cwd 播一次种
 * （dsh-client-ui-sidebar-files/lib/client.js:426-428），之后 cwd 再变也不会重设根；
 * 刷新按钮只走 `actions.reset` + 按已展开路径重新 `load`（同文件 :455-458、:659-661），
 * 同样不重设根。所以「读到新绑定但树还指着旧根」只能在这一层堵住。
 *
 * 请求只在用户可感知的时机发出：挂载页签（`start` 前读一次）、点刷新（`load` 命中已播种的根时读一次）、
 * 窗口重新可见/获得焦点（读一次）。**没有定时轮询**——轮询既改不了已挂载页签的根，也白花请求。
 *
 * 作用域仍是**本 entry**：只改我们注册的那条正文。探测官方 entries 与三步注册在 `takeover.ts`；
 * 两块零互引（ESLint 块间隔离），装配根把 `viewFor` 接进来、再把产出接到那边的 `wrapInject` 上。
 */
import type { SessionContribution, SessionView, ViewFor, WrapInject } from "./shared/ports.ts";

/**
 * 所有播种面的释放函数。存在的理由只有一条：**没有 signal 的调用者不会自己撤销**。
 * 官方界面包现在总是把页签的 signal 传进来（`FilesBody` 的 `start(tab.id, cwd, signal)`），
 * 但那是它的实现细节；一旦某条路径不带 signal，`watched` 与两条订阅就会一直留在单例座位注册表上。
 * 卸载时由 {@link releaseAllSeedings} 统一收口。
 */
const liveSeedings = new Set<() => void>();

/** 整体释放：装配根在卸载路径上调用。重复调用无害（释放函数自己会把自己摘掉）。 */
export function releaseAllSeedings(): void {
  for (const release of [...liveSeedings]) release();
}

/** 官方 files face 里被我们覆盖的两个方法（其余成员原样透传）。 */
type FaceStart = (tabId: string, root: string, signal?: AbortSignal) => void;
type FaceLoad = (tabId: string, path: string, signal?: AbortSignal) => void;

/** 一个已挂载页签：最近播种的根、回退根，以及它的存活信号。 */
interface WatchedTab {
  /** 最近一次播种进去的根；`load` 靠它认出「刷新按钮的根那一跳」。 */
  seeded: string;
  /** 官方正文递进来的 cwd：绑定不可用时回退到它。 */
  readonly fallback: string;
  readonly signal: AbortSignal | undefined;
}

/** 造一个改写器：外包官方工厂、保留它产出的一切，只改 hooks 与那两个播种方法。 */
export function createInjectWrapper(viewFor: ViewFor): WrapInject {
  return (official) => {
    return (...args: unknown[]): Record<string, unknown> => {
      const face: Record<string, unknown> = official === undefined ? {} : official(...args);
      // 渲染器把 binding.key 作为第一个参数传进来（runInject）；取不到会话 id 时宁可让树显示真实 cwd。
      const sessionId = args.find((arg): arg is string => typeof arg === "string");
      if (sessionId === undefined) return face;
      const view = viewFor(sessionId);
      const bound: Record<string, unknown> = { ...face, hooks: mergeSessions(face, view) };
      // 官方面不成形时不改写：没有 start 就没有可播种的树，改了只会让树进不了状态。
      return typeof face["start"] === "function" ? { ...bound, ...seeding(view, face) } : bound;
    };
  };
}

/** 官方 face 里已有的 hooks 源要保留：我们只覆盖 sessions 一项。 */
function mergeSessions(
  face: Record<string, unknown>,
  view: SessionView,
): SessionContribution["hooks"] {
  const existing = face["hooks"];
  const hooks =
    typeof existing === "object" && existing !== null
      ? (existing as SessionContribution["hooks"])
      : {};
  return { ...hooks, sessions: view.source };
}

/**
 * 以生效根播种的 `start`/`load`。
 *
 * 订阅只在**有页签挂载**期间存在（首个 `start` 建立、最后一个 abort 撤销）：
 * 只有开着 Files 页签的会话才有请求与订阅，关掉即回收——不需要另做"会话还在不在"的推断。
 */
function seeding(view: SessionView, face: Record<string, unknown>): Record<string, unknown> {
  const officialStart = face["start"] as FaceStart;
  const officialLoad = face["load"] as FaceLoad | undefined;
  const watched = new Map<string, WatchedTab>();
  let unsubscribe: (() => void) | undefined;
  let detachVisible: (() => void) | undefined;

  const refresh = (): void => {
    void view.root.refresh();
  };

  /** 生效根变了：把在挂页签重新播一次种（官方 `start` 会重设根并重新列目录）。 */
  const reseed = (): void => {
    const next = view.root.getSnapshot();
    for (const [tabId, tab] of [...watched]) {
      if (tab.signal?.aborted === true) continue;
      const root = next ?? tab.fallback;
      // 根没变就不重播：官方每次 `start` 都往同一个 signal 上再加一个 abort 监听并重列目录，
      // 而「绑定没变」恰恰是最常见的那次通知（订阅只在实际变化时触发，但 fallback 与绑定同值时也走这里）。
      if (root === tab.seeded) continue;
      tab.seeded = root;
      officialStart(tabId, root, tab.signal);
    }
  };

  const release = (): void => {
    // 迟到的绑定响应也走 watched 查找；清空后不得再给已卸载页签播种。
    watched.clear();
    liveSeedings.delete(release);
    unsubscribe?.();
    unsubscribe = undefined;
    detachVisible?.();
    detachVisible = undefined;
  };

  /** 页签 abort 时的清理：摘掉本页签，空表时释放订阅（attach 的 abort 分支外提以降复杂度）。 */
  const watchAbort = (tabId: string, signal: AbortSignal | undefined): void => {
    signal?.addEventListener(
      "abort",
      () => {
        watched.delete(tabId);
        if (watched.size === 0) release();
      },
      { once: true },
    );
  };

  const attach = (
    tabId: string,
    fallback: string,
    seeded: string,
    signal: AbortSignal | undefined,
  ): void => {
    liveSeedings.add(release);
    watched.set(tabId, { seeded, fallback, signal });
    unsubscribe ??= view.root.subscribe(reseed);
    detachVisible ??= refreshWhenVisible(refresh);
    watchAbort(tabId, signal);
  };

  const start: FaceStart = (tabId, root, signal) => {
    // 先按**官方 root 同步播种**，再用绑定纠正。反过来（等绑定读回来再播种）会把官方树的首帧
    // 挂在一次没有超时的 fetch 上：宿主端点一慢，官方正文的 `state` 就停在 undefined 而返回 null，
    // 于是**所有会话（含从未登记的）**的 Files 树一直空白，直到那次请求回来为止。
    attach(tabId, root, root, signal);
    officialStart(tabId, root, signal);
    void view.root.refresh().then(() => {
      if (signal?.aborted === true) return;
      const seeded = view.root.getSnapshot() ?? root;
      const tab = watched.get(tabId);
      if (tab === undefined || tab.seeded === seeded) return;
      tab.seeded = seeded;
      officialStart(tabId, seeded, tab.signal);
    });
  };

  const load: FaceLoad = (tabId, path, signal) => {
    // 官方刷新 = `actions.reset` + 对每个已展开路径调 load；根那一跳就是重读绑定的时机。
    // 展开子目录（路径更深）不触发，否则点开 20 个目录就是 20 次请求。
    if (watched.get(tabId)?.seeded === path) refresh();
    officialLoad?.(tabId, path, signal);
  };

  return officialLoad === undefined ? { start } : { start, load };
}

/**
 * 窗口重新可见或重新获得焦点时读一次：覆盖「切走一会儿再回来」——那时 agent 多半刚登记过。
 * 没有 DOM（单测/非浏览器环境）时退化为无触发，其余时机不受影响。
 */
function refreshWhenVisible(refresh: () => void): () => void {
  if (typeof document === "undefined" || typeof window === "undefined") return () => undefined;
  const onVisible = (): void => {
    if (!document.hidden) refresh();
  };
  document.addEventListener("visibilitychange", onVisible);
  window.addEventListener("focus", onVisible);
  return () => {
    document.removeEventListener("visibilitychange", onVisible);
    window.removeEventListener("focus", onVisible);
  };
}

/**
 * 接管 files 页签：把官方组件的**目录根**换掉，不重写树 UI。
 *
 * 接管只做一件事：以**官方 id** 为 key、**更低的 priority** 再登记一条正文，组件 / store /
 * locale 全部复用官方那条（inject 面由 `inject.ts` 包一层）。官方 ui-slots 的每个 cell 取
 * 「优先级最低的那条存活项」——它的注册表原话是 register at a different priority to shadow it
 * (lowest renders)（`@deepseek-ai/dsh-client-ui-slots` 的 `lib/index.js:77`；排序 `:130`；取当值项 `:187-200`）。
 *
 * **那个包不在 dsh 安装树里**：它在构建期被内联进 `dsh-web-frontend/dist/assets/index-*.js`，
 * 所以要照注释去读原文时，可读副本在同仓 catalog 锁版处
 * （`node_modules/.pnpm/@deepseek-ai+dsh-client-ui-slots@0.1.5-rc.1_...` 下的
 * `node_modules/@deepseek-ai/dsh-client-ui-slots/lib/index.js`）。
 * 树内可读的两处是类型面与运行时入口：`dsh-client-ui-renderer/lib/types/client/registry.d.ts:46/84/154/164`
 * （`class SlotRegistry`、`register`、`entries`、`entriesOfSlot`）与同一包 `lib/client.js:953/1191-1198/1388`。
 *
 * **为什么不再顶掉类型表**：顶掉就得把官方定义整份搬运（`guide` / `patterns` / `canOpen` 以及
 * 将来新增的字段），官方注册表 refresh 后还会用**在册定义**重算 guide 条目——搬丢 `guide` 的后果
 * 是所有会话的默认页签变成空的 Guide。遮蔽正文让类型表、标题、guide 全部保持原样，这份搬运消失。
 *
 * **当值判定**：登记之后座位上当值的那条必须带我们的 priority，否则说明遮蔽没生效（官方换了更低的
 * 优先级，或我们的条目已被退场）。判定失败当场撤掉自己那条并出声：可感知地什么都不做，好过静默
 * 显示错的地方。
 *
 * 本文件只经 `TakeoverDeps.wrapInject` 拿到改写器——接管块与改写块零互引，装配由 `index.ts` 完成。
 */
import type { ClientSlotsPort, StoredEntryLike, TabsPort, WrapInject } from "./shared/ports.ts";

/** 我们接管的 kind。 */
export const FILES_KIND = "files";
/** 正文座位。 */
export const BODY_SLOT = "sidebar.right.pane.tab";

/**
 * 我们那条正文的 priority：比官方那条**低一档**。
 *
 * 官方当前那条没声明 priority（它的 register options 只有 name/key/locale/store/inject，
 * 见界面包里那处注册），所以实际取值仍是 -1；但「官方是 0」不是契约，写死常量意味着
 * 官方哪天声明了 0 以下的 priority，我们就从遮蔽者变成被遮蔽者（自检会当场退位，接管静默失效）。
 * 取值的唯一约束是「比官方低且与官方不同」——同 key 同 priority 的登记会当场抛。
 */
export function shadowPriorityOf(official: StoredEntryLike): number {
  return (official.options.priority ?? 0) - 1;
}

/**
 * 登记本身抛错时的重试上限（含首次）。优先级冲突不在此列——那是终态，重试只会自旋。
 */
const TRANSIENT_ATTEMPTS = 2;

interface TakeoverDeps {
  readonly slots: ClientSlotsPort;
  readonly tabs: TabsPort;
  readonly logger: { warn(message: string): void };
  /** 官方 inject 面的改写器：由装配根从 `inject.ts` 接进来（块间零互引）。 */
  readonly wrapInject: WrapInject;
}

/** 接管入口。返回值是完整释放函数；调用方把它放进 `ctx.effect` 的 disposer。 */
export function installTakeover(deps: TakeoverDeps): () => void {
  /** 当前这次接管：我们的释放函数、被遮蔽的官方条目（HMR 后是另一个对象），以及我们用的 priority。 */
  let live: { dispose: () => void; shadowed: StoredEntryLike; priority: number } | null = null;
  /**
   * 我们用过的 priority 值。key 已经是官方 id，认自己**只能**认 priority，
   * 而 priority 现在是按官方那条算出来的，所以不能再拿一个常量当身份。
   */
  const ours = new Set<number>();
  /** 每条官方条目登记失败的次数：瞬时失败允许再来一次，连续失败才退成「这条不再试」。 */
  const attempts = new WeakMap<StoredEntryLike, number>();
  /**
   * 自检失败过的那条官方条目。
   *
   * 没有它就会**自旋**：登记与撤销各自会触发一次座位通知（官方是微任务批处理），我们于是
   * 「再试一次 → 再失败 → 再撤销」，把渲染层拖进永不停歇的微任务循环。同一条试过一次就不再试，
   * 直到官方那条换了对象（HMR 重新登记）或换了一条别人才重新评估。
   */
  let refused: StoredEntryLike | null = null;

  /**
   * 官方文件页签的类型 id。**每次重新读**：类型表我们从不改写，所以 `get` 恒回官方那份定义。
   */
  const officialId = (): string | undefined => deps.tabs.get(FILES_KIND)?.id;

  /**
   * 原始账里官方那条正文。
   *
   * 不能用 `entriesOfSlot`：遮蔽生效后它回的是我们自己那条，于是「官方组件换了没有」永远问的是我们，
   * 官方包 HMR 之后会一直渲染旧模块的组件（这是原实现必须把首次读到的 key 记下来的同一个坑）。
   */
  const isOurs = (entry: StoredEntryLike): boolean =>
    entry.options.priority !== undefined && ours.has(entry.options.priority);

  /**
   * 要遮蔽的那条官方正文。
   *
   * 取「不是我们的条目里 priority **最高**的那条」而不是「第一条」：遮蔽者的优先级总是低于它要遮蔽的
   * 那条，所以别人（另一个插件）留下的条目都排在官方之下——把官方的原条目认成「第一条不是我们的」
   * 会让我们的 priority 跟着别人一起往下走，变成一场谁更低的自旋。
   * 别人已经更具体时正确的行为是**退位并出声**（渲染层只画最低的那条，我们的包装不会生效），
   * 那一步由 `evaluate` 的当值复检负责。
   */
  const findOfficial = (id: string): StoredEntryLike | undefined => {
    let best: StoredEntryLike | undefined;
    for (const entry of deps.slots.entries(BODY_SLOT)) {
      if (entry.options.key !== id || isOurs(entry)) continue;
      if (best === undefined || (entry.options.priority ?? 0) > (best.options.priority ?? 0)) {
        best = entry;
      }
    }
    return best;
  };

  /** 座位上当值的那条是不是我们（官方对 keyed 座位的判定就是「同 cell 取首条存活项」）。 */
  const isWinner = (id: string, priority: number): boolean =>
    deps.slots
      .entriesOfSlot(BODY_SLOT)
      .some((entry) => entry.options.key === id && entry.options.priority === priority);

  const teardown = (): void => {
    const current = live;
    live = null;
    if (current === null) return;
    ours.delete(current.priority);
    try {
      current.dispose();
    } catch {
      // 释放失败不上报：卸载阶段出声只会掩盖首个异常。
    }
  };

  /** 自检失败：登记上了但当值项不是我们——优先级冲突，重试无意义。 */
  class ShadowRefused extends Error {}

  const tryTakeOver = (official: StoredEntryLike, id: string): void => {
    const priority = shadowPriorityOf(official);
    let dispose: (() => void) | undefined;
    try {
      dispose = deps.slots.register(
        {
          name: BODY_SLOT,
          key: id,
          priority,
          locale: official.locale,
          store: official.store,
          inject: deps.wrapInject(official.inject),
        },
        official.component,
      );
      // 自检：登记成功不等于当值（官方可能换了更低的优先级）。不当值就退位，不留一条死条目。
      if (!isWinner(id, priority)) {
        throw new ShadowRefused("遮蔽未生效：当值项不是我们这条（priority 更低者才渲染）");
      }
    } catch (cause) {
      try {
        dispose?.();
      } catch {
        // 同上。
      }
      const reason = cause instanceof Error ? cause.message : String(cause);
      deps.logger.warn(
        "dsh-worktree-sidebar: 接管 files 页签正文失败，已退位（保持官方行为）— " + reason,
      );
      if (cause instanceof ShadowRefused) {
        // 优先级冲突是终态：官方（或别人）占了更低的 priority，再试还是同一条。
        refused = official;
        return;
      }
      // 登记本身抛错可能只是这一刻的座位变更抖动。一次瞬时失败就永久放弃，会让接管静默失效，
      // 而恢复条件只剩官方包 HMR——所以允许再来一次，连续失败才退成「这条不再试」。
      const tries = (attempts.get(official) ?? 0) + 1;
      attempts.set(official, tries);
      if (tries >= TRANSIENT_ATTEMPTS) refused = official;
      return;
    }
    attempts.delete(official);
    refused = null;
    ours.add(priority);
    live = { dispose, shadowed: official, priority };
  };

  /**
   * 重新评估。正文座位的任何变化都会走到这里。
   *
   * 官方正文不在时不登记，但**不退订**——它可能只是 HMR 的中间态：
   * 退订会让「官方包确实还在、只是重载了一下」被误判成永久退场。
   */
  const evaluate = (): void => {
    const id = officialId();
    if (id === undefined) {
      teardown();
      return;
    }
    const official = findOfficial(id);
    if (official === undefined) {
      teardown();
      return;
    }
    if (live !== null) {
      if (live.shadowed === official) {
        // 官方组件没换：只有当值也还是我们时才算无事可做。别人登记了更低的 priority 之后，
        // 我们的条目还在座位上但已经不渲染了——那必须当场退位并出声，不能静默留一条死条目。
        if (isWinner(id, live.priority)) return;
        teardown();
        deps.logger.warn(
          "dsh-worktree-sidebar: 接管 files 页签正文失败，已退位（当值项被更低的 priority 夺走，" +
            "我们的包装不会渲染）",
        );
        refused = official;
        return;
      }
      teardown();
    } else if (official === refused) {
      // 这一条已经试过且不当值（官方/别人优先级更低）：不自旋，等它换人再说。
      return;
    } else if (!deps.slots.entriesOfSlot(BODY_SLOT).some((e) => e.options.key === id)) {
      // 还没接管，而该 cell 已经没有当值项（官方那条被 abdicate 退场）——不接管一个已退场的座位。
      return;
    }
    tryTakeOver(official, id);
  };

  const unsubscribeSlot = deps.slots.subscribe(BODY_SLOT, evaluate);
  let unsubscribeErrors: (() => void) | undefined;
  try {
    // 崩溃归因：静态组合下 owner 索引为空，我们自己 entry 的异常只会进 console。
    // 这条订阅是本包唯一能知道「ours 崩了」的地方；key 已经是官方 id，认自己只能认 priority。
    unsubscribeErrors = deps.slots.onEntryError((key, entry, error) => {
      if (key !== BODY_SLOT || !isOurs(entry)) return;
      deps.logger.warn(
        "dsh-worktree-sidebar: 接管入口出现异常（" +
          key +
          "）— " +
          (error instanceof Error ? error.message : String(error)),
      );
    });
    evaluate();
  } catch (cause) {
    // 两条订阅建立在 evaluate 之前。evaluate 抛错时如果不在这里撤销，订阅会留在单例座位注册表上
    // 永不释放——disposer 根本没生成，卸载时没人收（index.ts 的兜底 catch 只会吞掉这次异常）。
    try {
      unsubscribeErrors?.();
    } catch {
      // 同上。
    }
    try {
      unsubscribeSlot();
    } catch {
      // 同上。
    }
    throw cause;
  }

  return () => {
    teardown();
    try {
      unsubscribeSlot();
    } catch {
      // 同上。
    }
    try {
      unsubscribeErrors?.();
    } catch {
      // 同上。
    }
  };
}

