/**
 * api 域路由块：注册端点并给每条请求套围栏。
 *
 * 围栏用仓库共享层那一份（`guardLoopbackMethod`），不在这里重写判定：
 * 安全边界的修复必须传播到所有插件，复制一份就是让它不再传播（shared/loopback.js 的模块注释即此意）。
 * 顺序由共享层保证：非回环 403 先于方法错 405。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import { guardLoopbackMethod, writeJson } from "../../../../../../../shared/host-utils.js";
import type { LoggerPort } from "../../../shared/interface.ts";
import type { RegisterRoute } from "../../deps.ts";

/** 一个端点的处理器。 */
type RequestHandler = (req: IncomingMessage, res: ServerResponse) => void | Promise<void>;

/** 一条路由：路径 + 方法白名单（方法名 → 处理器）。 */
export interface Endpoint {
  readonly path: string;
  readonly methods: Readonly<Record<string, RequestHandler>>;
}

/**
 * 注册端点组，返回摘除器清单。**要么全上、要么全不上**。
 *
 * 中途失败时把已挂的那些摘回去再抛：宿主侧留着一条没有摘除器的路由，比一条都没挂更糟——
 * 它在册、会响应、而下一次装配只会再挂一遍，且没人能摘掉它。
 */
export function registerEndpoints(
  register: RegisterRoute,
  endpoints: readonly Endpoint[],
  logger: LoggerPort,
): Array<() => void> {
  const disposers: Array<() => void> = [];
  for (const endpoint of endpoints) {
    try {
      disposers.push(
        register({
          kind: "exact",
          path: endpoint.path,
          handler: (req, res) => {
            if (!guardLoopbackMethod(req, res, Object.keys(endpoint.methods))) return;
            const handle = endpoint.methods[req.method ?? ""];
            try {
              const done = handle(req, res);
              // 异步端点失败落在 promise、同步端点落在 catch：收口只有一处，两条路都要接上，
              // 否则异步端点的异常会变成未捕获拒绝。
              if (done instanceof Promise) {
                done.catch((cause) => reportFailure(res, logger, cause));
              }
            } catch (cause) {
              reportFailure(res, logger, cause);
            }
          },
        }),
      );
    } catch (cause) {
      for (const dispose of [...disposers].reverse()) {
        try {
          dispose();
        } catch {
          // 回滚阶段不做失败上报：一个端点的摘除失败不该掩盖首个异常。
        }
      }
      throw cause;
    }
  }
  return disposers;
}

/**
 * 异常收口：记日志并回 500。响应头可能已经发出，所以只在不曾写过时才补 500
 * ——重复写会抛 `ERR_HTTP_HEADERS_SENT`，把一次端点失败升级成宿主侧的未捕获异常。
 */
function reportFailure(res: ServerResponse, logger: LoggerPort, cause: unknown): void {
  const reason = cause instanceof Error ? cause.message : String(cause);
  logger.warn("dsh-worktree-sidebar: 浏览器端点处理失败 — " + reason);
  if (!res.headersSent) writeJson(res, 500, { ok: false, error: { message: reason } });
}

/**
 * binding 域装配：绑定表的**唯一事实源**。
 *
 * 内存快照是刻意的：scope 域的解析器与 api 域的路由读同一个对象，两端 revision 因此不可能
 * 各说各话（降级预案 G7）。落盘只是它的持久化副本——写盘失败时内存不前移，
 * 因为「内存说已登记、磁盘说没有」在重启后会变成一次静默的换根失败。
 *
 * 状态（表快照与写盘串行链）住在实例里；域是**进程内单例**，第二次 `install` 由 `installed`
 * 守卫**显式抛错**（响亮失败优于静默共享/丢数据）。
 */
import type { BindingRecord, BindingsFile } from "../model/type.ts";
import type { FileWrite } from "../../../shared/interface.ts";
import type { BindingDeps } from "../../deps.ts";
import { dropBinding, emptyTable, putBinding } from "../model/index.ts";
import { loadTable, saveTable } from "../store/index.ts";

/** 未装配时能力面的失败文案：读到它就说明装配守卫有洞，当场暴露而不是拿旧 deps 出结果。 */
const NOT_INSTALLED = "dsh-worktree-sidebar: binding 域尚未装配";

/** 绑定域的服务面。 */
export interface BindingApi {
  /** 当前表版本。与 api 域路由读的是同一快照，故它也是客户端能观察到的版本。 */
  revision(): number;
  /** 按会话取绑定。 */
  get(sessionId: string): BindingRecord | undefined;
  /** 落一条绑定并持久化。 */
  put(sessionId: string, record: BindingRecord): Promise<FileWrite>;
  /** 摘一条绑定并持久化（幂等：本来就没有不算失败）。 */
  drop(sessionId: string): Promise<FileWrite>;
}

/** 绑定表：唯一实例持有内存快照与写盘串行链。 */
class BindingService implements BindingApi {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  private deps: BindingDeps | undefined;
  private table: BindingsFile = emptyTable();
  /**
   * 写盘串行链：两次并发修改都基于同一份旧表时，后写的那次会静默吞掉前一次的绑定。
   * 链本身不承载结果，失败也不该断链，故 catch 掉、语义归返回值。
   */
  private writes: Promise<unknown> = Promise.resolve();
  /**
   * 装配代数。`release` 的尾部清理要 `await` 在飞的写盘，那一小段时间里**新的一个
   * `install` 可能已经装上并从磁盘读回了新表**；无脑清表会抹掉它，紧接着一次 `put`
   * 就把空表写回磁盘、丢掉所有会话的登记。
   */
  private generation = 0;

  /** 装配绑定域：把 bindings.json 读进内存（损坏回落空表，见 model 块）。重复装配是编程错误。 */
  install(deps: BindingDeps): void {
    if (this.installed) throw new Error("dsh-worktree-sidebar: binding 域只能装配一次");
    this.installed = true;
    this.generation += 1;
    this.deps = deps;
    // 每次都重新读盘：release 之后再装配必须看到磁盘的**现状**，不是上一代留下的内存快照。
    this.table = loadTable(deps.file);
  }

  /**
   * 卸载：**先等在飞的写盘链落定**，再放开入参、丢掉内存快照、复位装配标记。
   * 不等的话，同进程的下一次装配会读到比已提交内容更旧的磁盘状态——表现为「刚写的绑定在重装后消失」。
   * 重复调用无害。
   */
  async release(): Promise<void> {
    const generation = ++this.generation;
    // 只等**这一次 release 入口时**已经排队的那条链：期间新装上的一代有自己的链，不该被我们等，
    // 更不该被我们复位。
    const writes = this.writes;
    this.installed = false;
    this.deps = undefined;
    await writes;
    // 期间有新一代装配过：现在内存里那份表是它的，不是本代留下的，清掉就是把它的内容抹成空。
    if (this.generation !== generation) return;
    this.writes = Promise.resolve();
    this.table = emptyTable();
  }

  revision(): number {
    this.requireInstalled();
    return this.table.revision;
  }

  get(sessionId: string): BindingRecord | undefined {
    this.requireInstalled();
    return this.table.bindings[sessionId];
  }

  put(sessionId: string, record: BindingRecord): Promise<FileWrite> {
    this.requireInstalled();
    if (sessionId.length === 0) return Promise.resolve({ ok: false, reason: "空 sessionId" });
    return this.commit((current) => putBinding(current, sessionId, record));
  }

  drop(sessionId: string): Promise<FileWrite> {
    this.requireInstalled();
    return this.commit((current) => dropBinding(current, sessionId));
  }

  /**
   * 应用一次表变换并持久化。写盘成功才算成功——半成功的内存状态是最坏结果：
   * 内存说有、磁盘说没有，重启后就是一次静默的换根失败。
   *
   * 入参在**调用当刻**取出：在飞的写盘链要活过 `release`（它等的就是这一步落定），
   * 而那一刻 `this.deps` 已经被放开了。
   */
  private commit(reduce: (current: BindingsFile) => BindingsFile): Promise<FileWrite> {
    const deps = this.deps;
    if (deps === undefined) throw new Error(NOT_INSTALLED);
    const run = async (): Promise<FileWrite> => {
      const next = reduce(this.table);
      if (next === this.table) return { ok: true };
      const written = await saveTable(deps.file, next);
      if (written.ok) this.table = next;
      else deps.logger.warn("dsh-worktree-sidebar: 绑定表写盘失败 — " + written.reason);
      return written;
    };
    const queued = this.writes.then(run, run);
    this.writes = queued.catch(() => undefined);
    return queued;
  }

  /** 未装配时能力面当场失败，不拿旧 deps 出结果。 */
  private requireInstalled(): void {
    if (this.deps === undefined) throw new Error(NOT_INSTALLED);
  }
}

/** 本域唯一实例：类不外放，外面 `new` 不出第二份绑定表。 */
export const bindingService = new BindingService();

/**
 * git 查询的 argv 构造与输出解析：全是纯函数。
 *
 * 执行被隔离在装配层之后，所以「branch 名是否经过校验」「positional 前是否加了 `--`」
 * 这类安全属性可以被单测逐字断言，而不需要真仓库。
 *
 * 一律用 `-C <dir>` 而不是依赖进程 cwd：cwd 是全局状态，并发调用会互相污染。
 */
/** 一个 worktree 在 `git worktree list --porcelain` 里的样子。 */
export interface WorktreeEntry {
  readonly path: string;
  readonly branch: string | undefined;
  readonly detached: boolean;
}

/** 问某目录所属仓库的公共 git 目录（同一仓库的所有 worktree 共享它，故它标识「属于哪个仓库」）。 */
export function commonDirArgs(dir: string): readonly string[] {
  return ["-C", dir, "rev-parse", "--git-common-dir"];
}

/** 列出某目录所属仓库的全部 worktree。 */
export function worktreeListArgs(dir: string): readonly string[] {
  return ["-C", dir, "worktree", "list", "--porcelain"];
}

/** 读某 worktree 当前 HEAD 的分支名（`detached` 时 git 返回 `HEAD`）。 */
export function headBranchArgs(dir: string): readonly string[] {
  return ["-C", dir, "rev-parse", "--abbrev-ref", "HEAD"];
}

/** 让 git 自己校验分支名。`--branch` 还会拒绝 `-` 开头的名字，这是把参数注入挡在 argv 之外的第一道。 */
export function checkRefFormatArgs(branch: string): readonly string[] {
  return ["check-ref-format", "--branch", branch];
}

/**
 * 新建 worktree。`--` 结束选项解析，路径即使形如选项也不会被当成标志。
 *
 * 省略 branch 时必须显式 `--detach`：`git worktree add <path>` 的默认行为是**新建一个以目录
 * basename 命名的分支**并 checkout（实测 `Preparing worktree (new branch 'wtA')`），而不是
 * 「check out the repository HEAD」。那条默认路径还有两个后果——basename 含空格时 git 直接
 * `fatal: 'wt spaceB' is not a valid branch name`（macOS 的家目录常见空格），basename 以 `-` 开头时
 * `--` 只挡住了 worktree add 自己的选项解析、挡不住它把 basename 当分支名后的二次解析（`unknown switch`）。
 * `--detach` 让「省略 branch」的语义与文档一致，也把这条二次解析链路整个绕开。
 *
 * **`<path>` 之后的位置参数仍会被重新解析成选项**：实测 git 2.34.1 下
 * `worktree add -b br -- <path> --force` 与 `-f` 都 rc=0，但**起点被静默忽略、从 HEAD 建**；
 * `-badref` 则被当成 `git branch` 的选项报 usage。`--` 与 `--end-of-options` 都挡不住这一处。
 * 所以起点必须由调用方先做形态 guard（拒绝 `-` 开头）并归一化成 commit SHA 再递进来：
 * SHA 不会以 `-` 开头，这条二次解析链路就没有入口。
 */
export function addWorktreeArgs(
  repoRoot: string,
  path: string,
  branch: string | undefined,
  base: string | undefined,
): readonly string[] {
  const flags = branch === undefined ? ["--detach"] : ["-b", branch];
  const startPoint = base === undefined ? [] : [base];
  return ["-C", repoRoot, "worktree", "add", ...flags, "--", path, ...startPoint];
}

/** 把起点（分支 / tag / SHA / 相对 rev）解析成 commit SHA。`^{commit}` 让 annotated tag 也落到提交上。 */
export function revParseCommitArgs(dir: string, rev: string): readonly string[] {
  return ["-C", dir, "rev-parse", "--verify", "--quiet", rev + "^{commit}"];
}

/** 删除 worktree。`force` 只在调用方显式要求时出现——默认可丢未提交改动的删除不该是默认值。 */
export function removeWorktreeArgs(
  repoRoot: string,
  path: string,
  force: boolean,
): readonly string[] {
  const flags = force ? ["--force"] : [];
  return ["-C", repoRoot, "worktree", "remove", ...flags, "--", path];
}

/** 取 `rev-parse` 的单行输出。相对路径返回值（`--git-common-dir` 可能是相对路径）由调用方补全。 */
export function parseSingleLine(stdout: string): string | undefined {
  const line = stdout.split("\n")[0]?.trim() ?? "";
  return line.length === 0 ? undefined : line;
}

/** 解析 `worktree list --porcelain`：空行分块，每块首行是路径，其余是属性。 */
export function parseWorktreeList(stdout: string): readonly WorktreeEntry[] {
  const entries: WorktreeEntry[] = [];
  for (const block of stdout.split(/\r?\n\r?\n/)) {
    let path: string | undefined;
    let branch: string | undefined;
    let detached = false;
    for (const rawLine of block.split(/\r?\n/)) {
      const line = rawLine.trim();
      if (line.startsWith("worktree ")) path = line.slice("worktree ".length);
      else if (line.startsWith("branch ")) branch = line.slice("branch ".length);
      else if (line === "detached") detached = true;
    }
    if (path !== undefined && path.length > 0) entries.push({ path, branch, detached });
  }
  return entries;
}

/**
 * git 域装配：把「一次 git 调用」翻译成归属查询与增删。
 *
 * 所有 argv 构造在 `impl/inspect`（纯函数，可逐字断言），本块只负责执行与把退出码翻译成答案。
 *
 * 状态（归属校验与仓库判定的 TTL 缓存、装配入参）住在实例里；域是**进程内单例**，第二次 `install` 由
 * `installed` 守卫**显式抛错**（响亮失败优于静默共享/丢数据）。
 */
import { resolve } from "node:path";
import type {
  BelongsToReading,
  CommonDirReading,
  GitDeps,
  GitExecPort,
  GitRunResult,
} from "../../deps.ts";
import {
  addWorktreeArgs,
  checkRefFormatArgs,
  commonDirArgs,
  headBranchArgs,
  parseSingleLine,
  parseWorktreeList,
  removeWorktreeArgs,
  revParseCommitArgs,
  worktreeListArgs,
} from "../inspect/index.ts";
import type { WorktreeEntry } from "../inspect/index.ts";

/**
 * 归属校验结论的缓存存活时长。解析器每次目录展开都要问一次，裸起子进程会随展开线性增长。
 *
 * 取值**刻意与任何客户端刷新节拍无关**：早先它与浏览器轮询同为 5s，于是每轮轮询恰好落在
 * 缓存过期点上，一个绑定会话每小时白起约 1500 个 git 子进程。归属只在 worktree 被删除或
 * 移动时才变，而写侧的绑定还另有一道「目录是否存在」的本地检查，故 30s 的不新鲜期不放大风险。
 *
 * 注意它间接吃 `commonDir` 的缓存：本条的条目用「最多 30s 旧」的输入算出，自己再存活 30s，
 * 于是**最坏**不新鲜期是 60s 而不是 30s（两层 TTL 同值同纪律，但读数是叠加的）。
 *
 * 只缓存**已定**读数（`same` / `different`）：`unknown` 不进缓存，理由与 `COMMON_DIR_TTL_MS`
 * 的负答案不缓存同一条——写路径对 `unknown` 是 fail-closed 且文案让调用方「等目录可读后重试」，
 * 把那次 `unknown` 缓存住就等于把这句重试建议变成 30s 内的确定性失败。
 */
const BELONGS_TTL_MS = 30_000;

/** 缓存条目上限。超出即整表丢弃——这是一份加速缓存，不是需要保真的状态。 */
const BELONGS_CACHE_MAX = 256;

/**
 * 仓库判定结论的缓存存活时长。安装期要给**每个新 agent** 判一次「cwd 在不在仓库里」，
 * 裸起子进程会把这次判定推到几十到上百毫秒；而官方 `agents.create()` 是「发布之后立刻开跑」
 * （`dsh-agent/lib/index.js:415` 的契约），子会话的**第一回合**正落在这个窗口里——
 * 判定慢一拍，子会话第一回合就看不到工具。
 *
 * 与 `BELONGS_TTL_MS` 同值同纪律：仓库归属只在 worktree 被删/移动时变，执行期还另有一次兜底校验。
 *
 * 它只缓存**拿到了公共 git 目录**的那种答案。负答案不缓存：`git init` 可能就发生在下一次调用之前
 * （用户在一个空目录里刚初始化完就调工具），而「读不出来」本就该重试而不是记住。
 */
const COMMON_DIR_TTL_MS = 30_000;

/** 仓库判定缓存的条目上限，与归属缓存同口径。 */
const COMMON_DIR_CACHE_MAX = 256;

/** 未装配时能力面的失败文案：读到它就说明装配守卫有洞，当场暴露而不是拿旧 deps 出结果。 */
const NOT_INSTALLED = "dsh-worktree-sidebar: git 域尚未装配";

/** git 域的服务面。 */
export interface GitApi {
  /** 该目录是否在某个仓库里；是则给公共 git 目录的**绝对**路径（带 TTL 缓存）。 */
  commonDir(dir: string): Promise<string | undefined>;
  /** 同一主仓库下的全部 worktree。 */
  listWorktrees(dir: string): Promise<readonly WorktreeEntry[]>;
  /**
   * `dir` 与 `repoRoot` 是否属于同一仓库（带 TTL 缓存）。
   *
   * 回三态而不是布尔：`unknown`（有一侧读不出公共 git 目录）与 `different`（两侧都读出来了、值不同）
   * 对调用方的处置相反——前者要保住用户已有的登记，后者才是「确实换了仓库」。
   */
  belongsTo(dir: string, repoRoot: string): Promise<BelongsToReading>;
  /** 某 worktree 的当前分支显示名。 */
  headBranch(dir: string): Promise<string | undefined>;
  /** 让 git 校验分支名。 */
  checkRefFormat(branch: string): Promise<boolean>;
  /**
   * 新建 worktree。`base` 必须是**已经归一化的 commit SHA**——argv 里 `<path>` 之后的
   * 参数会被 git 重新解析成选项，起点直接传用户输入就等于把注入面留在那里（见 `impl/inspect`）。
   */
  addWorktree(
    repoRoot: string,
    path: string,
    branch: string | undefined,
    base: string | undefined,
  ): Promise<GitMutation>;
  /** 把起点解析成 commit SHA；解析不出来回 undefined（调用方据此给一句可操作的失败）。 */
  resolveCommit(dir: string, rev: string): Promise<string | undefined>;
  /** 删除 worktree。 */
  removeWorktree(repoRoot: string, path: string, force: boolean): Promise<GitMutation>;
}

/** git 写操作的结果：`reason` 是 git 的原文，直接给模型看。 */
export type GitMutation = { readonly ok: true } | { readonly ok: false; readonly reason: string };

/** git 域：唯一实例持有归属缓存与那一次 git 调用面。 */
class GitService implements GitApi {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  /** 装配入参。释放即放开，能力面随之当场失败。 */
  private deps: GitDeps | undefined;
  private readonly belongsCache = new Map<string, { at: number; reading: BelongsToReading }>();
  /** 只放正结果，所以值不是 `string | undefined`——负结果没有条目。 */
  private readonly commonDirCache = new Map<string, { at: number; dir: string }>();

  /** 装配 git 域。重复装配是编程错误，当场暴露。 */
  install(deps: GitDeps): void {
    if (this.installed) throw new Error("dsh-worktree-sidebar: git 域只能装配一次");
    this.installed = true;
    this.deps = deps;
  }

  /** 卸载：丢掉缓存与装配入参，复位装配标记——同进程的下一次 `install` 不该撞上「只能装配一次」。 */
  release(): void {
    this.installed = false;
    this.belongsCache.clear();
    this.commonDirCache.clear();
    this.deps = undefined;
  }

  async commonDir(dir: string): Promise<string | undefined> {
    const reading = await this.reading(dir);
    return reading.kind === "repo" ? reading.dir : undefined;
  }

  /**
   * 带缓存的仓库判定读数。缓存只认正结果（见 `COMMON_DIR_TTL_MS`），负结果每次都真问一次 git。
   */
  private async reading(dir: string): Promise<CommonDirReading> {
    const hit = this.commonDirCache.get(dir);
    if (hit !== undefined && Date.now() - hit.at < COMMON_DIR_TTL_MS) {
      return { kind: "repo", dir: hit.dir };
    }
    const reading = await this.computeCommonDir(dir);
    if (reading.kind === "repo") {
      if (this.commonDirCache.size >= COMMON_DIR_CACHE_MAX) this.commonDirCache.clear();
      this.commonDirCache.set(dir, { at: Date.now(), dir: reading.dir });
    }
    return reading;
  }

  /** 真起一次 git 求公共目录；缓存命中不走这里。 */
  private async computeCommonDir(dir: string): Promise<CommonDirReading> {
    const result = await this.exec().run(commonDirArgs(dir));
    if (!result.ok) {
      return result.code === null
        ? { kind: "failed", reason: reasonOf(result) }
        : { kind: "not-repo" };
    }
    const value = parseSingleLine(result.stdout);
    if (value === undefined) return { kind: "failed", reason: "git 未返回公共 git 目录" };
    // `--git-common-dir` 会返回相对 `dir` 的路径（实测是 `.git`），
    // 直接拿字符串比较会让「同一仓库的两个 worktree」判成不同仓库。
    return { kind: "repo", dir: resolve(dir, value) };
  }

  async listWorktrees(dir: string): Promise<readonly WorktreeEntry[]> {
    const result = await this.exec().run(worktreeListArgs(dir));
    if (!result.ok) return [];
    return parseWorktreeList(result.stdout);
  }

  async belongsTo(dir: string, repoRoot: string): Promise<BelongsToReading> {
    const key = dir + "\u0000" + repoRoot;
    const hit = this.belongsCache.get(key);
    if (hit !== undefined && Date.now() - hit.at < BELONGS_TTL_MS) return hit.reading;
    const [left, right] = await Promise.all([this.reading(dir), this.reading(repoRoot)]);
    // 只有两侧都**确实**给出了公共 git 目录时才有资格说「同 / 不同」；否则是问不出来。
    const reading: BelongsToReading =
      left.kind === "repo" && right.kind === "repo"
        ? left.dir === right.dir
          ? { kind: "same" }
          : { kind: "different" }
        : {
            kind: "unknown",
            reason: unreadableReason(dir, left, repoRoot, right),
            notRepo: left.kind === "not-repo" || right.kind === "not-repo",
          };
    // 只缓存已定读数：`unknown` 不缓存（理由见 `BELONGS_TTL_MS`）。写路径会告诉调用方
    // 「等目录可读后重试」，而那次重试要真的重新问一次 git 才算数。
    if (reading.kind !== "unknown") {
      if (this.belongsCache.size >= BELONGS_CACHE_MAX) this.belongsCache.clear();
      this.belongsCache.set(key, { at: Date.now(), reading });
    }
    return reading;
  }

  async headBranch(dir: string): Promise<string | undefined> {
    const result = await this.exec().run(headBranchArgs(dir));
    if (!result.ok) return undefined;
    const value = parseSingleLine(result.stdout);
    if (value === undefined || value === "HEAD") return undefined;
    return value;
  }

  async checkRefFormat(branch: string): Promise<boolean> {
    const result = await this.exec().run(checkRefFormatArgs(branch));
    return result.ok;
  }

  async addWorktree(
    repoRoot: string,
    path: string,
    branch: string | undefined,
    base: string | undefined,
  ): Promise<GitMutation> {
    const result = await this.exec().run(addWorktreeArgs(repoRoot, path, branch, base));
    return result.ok ? { ok: true } : { ok: false, reason: reasonOf(result) };
  }

  /** 解析起点。`--quiet` 让「不是有效 rev」走退出码而不是 stderr，失败在这里就收成 undefined。 */
  async resolveCommit(dir: string, rev: string): Promise<string | undefined> {
    const result = await this.exec().run(revParseCommitArgs(dir, rev));
    if (!result.ok) return undefined;
    return parseSingleLine(result.stdout);
  }

  async removeWorktree(repoRoot: string, path: string, force: boolean): Promise<GitMutation> {
    const result = await this.exec().run(removeWorktreeArgs(repoRoot, path, force));
    return result.ok ? { ok: true } : { ok: false, reason: reasonOf(result) };
  }

  /** 取执行面：未装配时当场失败，而不是拿一份空执行面跑出「git 说没有」这种假答案。 */
  private exec(): GitExecPort {
    const deps = this.deps;
    if (deps === undefined) throw new Error(NOT_INSTALLED);
    return deps.exec;
  }
}

/** 本域唯一实例：类不外放，外面 `new` 不出第二份缓存。 */
export const gitService = new GitService();

/** 失败原因的取值口径只有这一处：git 的 stderr 优先，空则给退出码。 */
function reasonOf(result: GitRunResult): string {
  const text = result.stderr.trim();
  return text.length > 0 ? text : "git 退出码非零";
}

/** 归属判定「问不出来」的原因：把读不出来的那一侧与它的原因写进一句话，告警才有可操作性。 */
function unreadableReason(
  dir: string,
  left: CommonDirReading,
  repoRoot: string,
  right: CommonDirReading,
): string {
  const sides: string[] = [];
  const describe = (label: string, path: string, reading: CommonDirReading): void => {
    if (reading.kind === "repo") return;
    const why =
      reading.kind === "failed" ? "git 执行失败（" + reading.reason + "）" : "不是 git 工作树";
    sides.push(label + " " + path + " " + why);
  };
  describe("worktree 侧", dir, left);
  describe("主仓库侧", repoRoot, right);
  return sides.join("；");
}

/**
 * scope 域装配：接管 `workspaceFileScope` 的解析，命中绑定就把会话的文件根指到 worktree。
 *
 * 接管是**全局替换**（一个键只有一个解析器），所以本域的三条纪律是硬的：
 * 1. 捕获委托对象必须在 configure 之前；
 * 2. configure 抛错（别人已接管）就整片放弃，不抢；
 * 3. 解析器永不抛出，任何异常都回落官方语义。
 *
 * **provider 由别人注册，我们等它**：官方 dsh-api-workspace-files 在自己的 apply 期才
 * `register("workspaceFileScope", …)`，与本插件的装配先后由宿主启动序决定。所以 provider 不在时
 * 本域既不自己复刻官方默认语义、也不失败，而是**订阅查找表、等它出现**（先订阅再重读一次：
 * 只重读不订阅会漏掉两者之间注册的 provider，只订阅不重读会漏掉订阅之前就已注册的那一个）。
 * 等待期不接管——文件根按官方语义走，这是**正常启动态**而不是降级。
 *
 * 状态（委托对象、装配入参、两个 disposer）住在实例里；域是**进程内单例**，第二次 `install` 由
 * 状态守卫**显式抛错**（响亮失败优于静默共享/丢数据）。
 */
import type { FileScope, ScopeDeps, SessionChainPort } from "../../deps.ts";
import type { WorktreeOrigin } from "../resolve/index.ts";
import {
  bindingOrigin,
  effectiveWorktree as resolveEffectiveWorktree,
  resolveScope,
} from "../resolve/index.ts";

/** 未装配时能力面的失败文案：读到它就说明装配守卫有洞，当场暴露而不是拿旧 deps 出结果。 */
const NOT_INSTALLED = "dsh-worktree-sidebar: scope 域尚未装配";

/**
 * 接管状态。`waiting` 与 `abandoned` 都不接管，但成因不同，故分开报：
 * 前者是「宿主还没把 provider 装上」（正常启动态，会自动收敛），后者是「这个键被别人占了」（终态）。
 */
export type TakeoverState = "idle" | "waiting" | "live" | "abandoned";

/** 委托对象：官方的 resolve（provider 缺失时不接管，所以没有第二来源）。 */
type Delegate = (sessionId: string) => Promise<FileScope | undefined>;

/** scope 域的服务面。 */
export interface ScopeApi {
  /**
   * 当前**生效**的 worktree 根；null 表示该会话按 cwd 走。
   * 浏览器路由读它，所以它与解析器给出的答案是同一个（G7）。
   */
  effectiveWorktree(sessionId: string): Promise<string | null>;
  /**
   * 该会话的**绑定来源**（自己的登记 / 继承来的登记 / 没有）。工具面读它，用来区分
   * 「本会话自己的登记」与「继承自哪个会话」。
   *
   * 它与 `effectiveWorktree` 的**唯一差别是不设 takeover 门**（后者在 `state !== "live"` 时回 null）。
   * 这是刻意的：工具面要的是「登记事实」，而「文件根有没有真的换根」是宿主启动期读数，
   * 由 `/health` 的 `scopeTakeover` 报告。waiting / abandoned 期两者结论不同，不是 bug。
   */
  worktreeOrigin(sessionId: string): Promise<WorktreeOrigin>;
  /** 接管状态的诊断读数：只给 health 用，判定逻辑不看它。接管与否看它是否等于 `live`。 */
  takeoverState(): TakeoverState;
  /** 会话链持久面的读数：查了几次、坏了几次、最后一次为什么坏。同样只给 health 用。 */
  chainDiagnostics(): ChainDiagnostics;
}

/**
 * 会话链持久面的读数。
 *
 * 它存在的唯一理由是**那处收口是无声的**：持久面读不出来时本域按「到顶」处理（正确的行为），
 * 于是功能悄悄降级成 live-only，而真机上插件的 `logger.warn` 不落盘（§19.5），
 * 排查时既没有日志也没有别的痕迹。health 是唯一一条能落地的观测面。
 */
export interface ChainDiagnostics {
  /** 持久面被查了几次：父链的「会话不在册」回落，以及每次会话身份核对。 */
  readonly storedReads: number;
  /** 其中抛错的次数——到顶收口就是在这里发生的。 */
  readonly storedFailures: number;
  /** 最后一次失败的原因；没有失败时缺席。 */
  readonly lastFailure: string | undefined;
}

/**
 * 内部计数器：对外那份是**只读快照**，这里才是唯一被改的那一份。
 * 拆成两个形状是有意的——调用方拿到的读数改不动，域内记账又不必绕开类型。
 */
interface ChainReading {
  storedReads: number;
  storedFailures: number;
  lastFailure: string | undefined;
}

/** `workspaceFileScope` 的接管者：唯一实例。 */
class ScopeService implements ScopeApi {
  private state: TakeoverState = "idle";
  private deps: ScopeDeps | undefined;
  /** 捕获到的委托对象。释放即丢掉，不留在实例上供下一次装配复用。 */
  private delegate: Delegate | undefined;
  /** configure 交回的释放面：调用它官方默认解析即恢复。 */
  private dispose: (() => void) | undefined;
  /** 查找表订阅的退订面。等待期需要它，进入终态后它只是空转。 */
  private unsubscribe: (() => void) | undefined;
  /** 等待期只出一次声：通知可能来很多次，每次都报会把日志淹掉。 */
  private warnedWaiting = false;
  /** 持久面读数。跨调用存活，所以只能住在这里，不能住在 `inherit`（那是无状态函数）。 */
  private chain: ChainReading = { storedReads: 0, storedFailures: 0, lastFailure: undefined };

  /** 装配 scope 域。重复装配是编程错误，当场暴露。 */
  install(deps: ScopeDeps): void {
    if (this.state !== "idle") throw new Error("dsh-worktree-sidebar: scope 域只能装配一次");
    this.chain = { storedReads: 0, storedFailures: 0, lastFailure: undefined };
    // 持久面加一圈读数：失败被 `inherit` 收口成「到顶」，收口点之外没有别人看得见那次失败。
    this.deps = { ...deps, sessions: this.observed(deps.sessions) };
    this.state = "waiting";
    // 先订阅、再重读一次：provider 可能正好在两者之间注册，那次通知已经发完了。
    this.unsubscribe = deps.typert.subscribe(() => this.attempt());
    this.attempt();
  }

  /**
   * 卸载：把 resolver 交还官方、退订、丢掉捕获到的委托与装配入参，复位状态。重复调用无害。
   * 此后到达的解析请求回 undefined（gateway 走它自己的 lookup-not-found），不会拿旧 deps 继续服务。
   */
  release(): void {
    const unsubscribe = this.unsubscribe;
    const dispose = this.dispose;
    this.state = "idle";
    this.deps = undefined;
    this.delegate = undefined;
    this.dispose = undefined;
    this.unsubscribe = undefined;
    this.warnedWaiting = false;
    this.chain = { storedReads: 0, storedFailures: 0, lastFailure: undefined };
    if (unsubscribe !== undefined) {
      try {
        unsubscribe();
      } catch {
        // 卸载阶段不做失败上报，避免掩盖首个异常。
      }
    }
    if (dispose === undefined) return;
    try {
      dispose();
    } catch {
      // 同上。
    }
  }

  takeoverState(): TakeoverState {
    return this.state;
  }

  /** 读数是快照：调用方拿不到本域内部那个对象，改不动它。 */
  chainDiagnostics(): ChainDiagnostics {
    return { ...this.chain };
  }

  /**
   * 给会话链的持久面加一圈读数。失败**照原样抛回**，收口仍在调用方——
   * 这里只负责记账，不改变任何判定。
   *
   * 身份核对也走同一条持久面，所以它同样计入读数：只统计父链会让「身份读不出来」这类
   * 故障在 health 上完全不可见。
   */
  private observed(inner: SessionChainPort): SessionChainPort {
    return {
      liveParentOf: (sessionId) => inner.liveParentOf(sessionId),
      storedParentOf: (sessionId) => this.counted(() => inner.storedParentOf(sessionId)),
      liveIdentityOf: (sessionId) => inner.liveIdentityOf(sessionId),
      storedIdentityOf: (sessionId) => this.counted(() => inner.storedIdentityOf(sessionId)),
    };
  }

  /** 记一次持久面读取：无论成败都算一次读，抛错另计一次失败并留下最后原因。 */
  private async counted<T>(read: () => Promise<T>): Promise<T> {
    this.chain.storedReads += 1;
    try {
      return await read();
    } catch (cause) {
      this.chain.storedFailures += 1;
      this.chain.lastFailure = cause instanceof Error ? cause.message : String(cause);
      throw cause;
    }
  }

  async effectiveWorktree(sessionId: string): Promise<string | null> {
    const deps = this.deps;
    if (deps === undefined) throw new Error(NOT_INSTALLED);
    // 还没接管（等 provider）或接管权被别人占了时文件根保持官方语义，客户端因此不动它。
    if (this.state !== "live") return null;
    return resolveEffectiveWorktree(deps, sessionId);
  }

  /**
   * 绑定来源。**不设 takeover 门**：登记是否存在与「文件根是否已经换成它」是两件事，
   * 工具面（register / create / remove）要的是前者的完整答案——它据此决定能不能摘、
   * 该不该报「继承自哪个会话」。把工具面也卡在 `live` 上，接管冲突时连一条已确认失效的
   * 登记都清理不掉。
   */
  async worktreeOrigin(sessionId: string): Promise<WorktreeOrigin> {
    const deps = this.deps;
    if (deps === undefined) throw new Error(NOT_INSTALLED);
    return bindingOrigin(deps, sessionId);
  }

  /**
   * 试一次接管。provider 没出现就退回等待态，等待由查找表的变更通知再次叫醒。
   */
  private attempt(): void {
    if (this.state !== "waiting") return;
    const deps = this.deps;
    if (deps === undefined) return;
    const descriptor = deps.typert.current();
    if (descriptor === undefined) {
      if (!this.warnedWaiting) {
        this.warnedWaiting = true;
        deps.logger.warn(
          "dsh-worktree-sidebar: workspaceFileScope 的 provider 尚未注册，先等它出现（文件根暂按官方语义）",
        );
      }
      return;
    }
    // 三件事都必须在 configure 之前落定：configure 会**同步**发出一次查找表变更通知，
    // 重入的 attempt 只有看到终态（并已拿到委托）才不会把自己判成「已被别人占用」。
    const delegate = descriptor.resolve;
    this.delegate = delegate;
    this.state = "live";
    try {
      this.dispose = deps.typert.configure((sessionId) => this.resolve(sessionId));
    } catch (cause) {
      // 第三方已经接管这个键：接管权是全局唯一的，本插件只放弃并出声，不抢。
      // 「已被占用」是**当次**的事实——不缓存成永久结论，release 之后再装配会重新尝试。
      const reason = cause instanceof Error ? cause.message : String(cause);
      this.state = "abandoned";
      this.delegate = undefined;
      this.dispose = undefined;
      deps.logger.warn(
        "dsh-worktree-sidebar: workspaceFileScope 已有解析器，放弃接管（文件根保持官方语义）— " +
          reason,
      );
    }
  }

  /**
   * 交给官方 typert 的解析器。委托对象与装配入参都按**调用当刻**取：释放之后这个闭包只剩
   * undefined，官方拿到的是它自己的 lookup-not-found，而不是一份过期绑定。
   */
  private async resolve(sessionId: string): Promise<FileScope | undefined> {
    const deps = this.deps;
    const delegate = this.delegate;
    if (deps === undefined || delegate === undefined) return undefined;
    return resolveScope(deps, delegate, sessionId);
  }
}

/** 本域唯一实例：类不外放，外面 `new` 不出第二份接管者。 */
export const scopeService = new ScopeService();

/**
 * 三个工具共用的绑定动作：来源读取、路径解析、归属校验、落登记。
 *
 * 校验顺序是刻意的：先「存在且是目录」（本地事实，最便宜），再「属于同一仓库」（要起 git）。
 * 反过来的话，一个手误的路径会先换来一次 git 调用和一句含糊的 git 报错。
 *
 * 绑定来源**只从 scope 域读**（`readOrigin`）：侧边栏的生效根与工具面的现状读数因此同源，
 * 工具才不会在 fork 出来的会话里回一句「本会话没有绑定」——那正是 #847 要修的缺陷。
 */
import { statSync } from "node:fs";
import { isAbsolute, resolve } from "node:path";
import type { BindingRecord } from "../../../binding/interface.ts";
import type { WorktreeOrigin } from "../../../scope/interface.ts";
import type { AgentFace, ToolsDeps } from "../../deps.ts";
import type { SessionFace } from "../session/index.ts";
import type { ToolResultValue } from "../protocol/index.ts";

/** 当前的绑定状态（三个工具的返回信封都要它）。 */
export interface BindingState {
  readonly bound: boolean;
  readonly worktree: string;
  readonly branch: string;
}

/**
 * 还没解析出来源时用的中性读数。早退路径（缺会话、缺 cwd、不在仓库、缺必填参数）用它：
 * 为一句「没有 cwd」白付一趟 git 与持久面读不值得，那些失败的成因也和「绑在哪」无关。
 */
export const NO_ORIGIN: WorktreeOrigin = { kind: "none" };

/**
 * 读来源的结果：`problem` 非空时 `origin` 是中性读数，调用方应直接把 `problem` 当作失败原因报出去。
 */
export interface OriginRead {
  readonly origin: WorktreeOrigin;
  readonly problem: string | undefined;
}

/**
 * 读某个会话的绑定来源（自己的登记 / 继承来的登记 / 没有）。
 *
 * 解析异常在这里收口。scope 域未装配或已释放时它抛的是**插件自己的装配状态**（内部文案是
 * 「scope 域尚未装配」）：那句话与调用者正在做的事毫无关系，透给模型只会让它照着一句无法行动的
 * 话去猜。所以对外只说「读不到绑定状态、稍后重试」，原因留给 logger —— 现场痕迹不丢，
 * 模型也不会拿到内部装配文案。
 *
 * 不静默翻成「没有绑定」：那会把一次真实故障说成事实，而「看错地方」正是本插件最该避免的事。
 */
export async function readOrigin(deps: ToolsDeps, sessionId: string): Promise<OriginRead> {
  try {
    return { origin: await deps.scope.worktreeOrigin(sessionId), problem: undefined };
  } catch (cause) {
    deps.logger.warn(
      "dsh-worktree-sidebar: 读取绑定来源失败 —— " +
        (cause instanceof Error ? cause.message : String(cause)),
    );
    return {
      origin: NO_ORIGIN,
      problem:
        "Could not read this session's binding state. Retry once the extension is fully loaded.",
    };
  }
}

/** 把来源翻成信封里的状态读数：继承态下 worktree / branch 取的是继承到的那条登记。 */
export function stateOf(origin: WorktreeOrigin): BindingState {
  if (origin.kind === "none") return { bound: false, worktree: "", branch: "" };
  return { bound: true, worktree: origin.record.worktreeRoot, branch: origin.record.branch };
}

/**
 * 组装结果信封。**继承来源说明只在这里加一次**：三个工具、每条成功与失败路径都经过它。
 * 各调用点自己拼就一定会漏——漏掉之后模型读到的是「本会话没有绑定」，它会去重建一条
 * 本已存在的登记（#847 的现场就是这样）。
 */
export function resultOf(origin: WorktreeOrigin, ok: boolean, detail: string): ToolResultValue {
  const state = stateOf(origin);
  const inherited =
    origin.kind === "inherited"
      ? "This root is inherited from session " +
        origin.ownerSessionId +
        "; this session has no binding of its own. "
      : "";
  return {
    ok,
    bound: state.bound,
    worktree: state.worktree,
    branch: state.branch,
    detail: inherited + detail,
  };
}

/**
 * 把调用方给的路径解析成绝对路径。相对路径按**会话 cwd** 解析（那是调用者心里的基准），不是进程 cwd。
 *
 * 参数是 `string` 而不是 `string | undefined`：两个调用方都在更早的分支上把「没有 cwd」判失败并返回了，
 * 这里再留一条 undefined 分支就是一段**不可达代码**（覆盖率替一段永远到不了的代码记账没有意义）。
 */
export function resolveTarget(cwd: string, raw: string): string {
  return isAbsolute(raw) ? raw : resolve(cwd, raw);
}

/** 是目录才继续。不是就给一句能照着做的失败。 */
export function directoryProblem(target: string): string | undefined {
  const info = statSync(target, { throwIfNoEntry: false });
  if (info === undefined) return "No such directory: " + target;
  if (!info.isDirectory()) return "Not a directory: " + target;
  return undefined;
}

/** 会话所属仓库的可用 worktree 清单，用于失败时的可操作提示。 */
export async function availableWorktrees(deps: ToolsDeps, repo: string): Promise<string> {
  const entries = await deps.git.listWorktrees(repo);
  if (entries.length === 0) return "";
  return "\nAvailable worktrees:\n" + entries.map((entry) => "- " + entry.path).join("\n");
}

/**
 * 落一条绑定。归属校验在这里做唯一一次——三个工具都经过它，
 * 所以「只允许绑定同一仓库的 worktree」这条不变量不会因为某条路径漏写而破。
 *
 * `before` 由调用方先解析好再递进来：调用方在更早的分支上就要用它（那几处失败路径也要报现状），
 * 在这里重算一遍等于白付一趟 git 与持久面读。
 */
export async function bindWorktree(
  deps: ToolsDeps,
  session: SessionFace,
  repo: string,
  target: string,
  registeredAt: string,
  before: WorktreeOrigin,
): Promise<ToolResultValue> {
  // 身份凭据缺席时拒绝落盘：没有它，这条登记在下一个进程里可能被一个同 id 的新会话继承，
  // 而那是「静默看错地方」——留一条不可核对的登记比不登记更危险。
  if (session.createdAt === undefined) {
    return resultOf(
      before,
      false,
      "This session exposes no creation timestamp, so the binding could not be told apart from a " +
        "different session that reuses the same id after a restart. Refusing to bind.",
    );
  }
  const belongs = await deps.git.belongsTo(target, repo);
  if (belongs.kind !== "same") {
    // 写路径 fail-closed：读不出归属时拒绝，而不是照着「没验成」去写一条可能指向别的仓库的登记。
    // `notRepo` 在这里只用来把**文案**说准（git 明确回了否定），不参与摘除判定：权限不可读的目录
    // 在读数上与「不是工作树」同形，所以这句「不是本会话仓库的 worktree」读作「git 拒绝把它当工作树」，
    // 而不是「我们已经验过了」。剩下那一支（spawn 失败 / 超时）才说「没验成、稍后重试」。
    const why =
      belongs.kind === "different" || (belongs.kind === "unknown" && belongs.notRepo)
        ? "That directory is not a worktree of this session's repository (" +
          repo +
          "), so binding it would point the file tree outside this repository."
        : "Could not verify that the directory belongs to this session's repository (" +
          repo +
          "): " +
          (belongs.kind === "unknown" ? belongs.reason : "") +
          ". Retry once the directory is readable.";
    return resultOf(before, false, why + (await availableWorktrees(deps, repo)));
  }
  const branch = (await deps.git.headBranch(target)) ?? "";
  const record: BindingRecord = {
    repoRoot: repo,
    worktreeRoot: target,
    branch,
    createdAt: registeredAt,
    sessionCreatedAt: session.createdAt,
  };
  const written = await deps.binding.put(session.id, record);
  if (!written.ok) {
    return resultOf(before, false, "Could not persist the binding: " + written.reason);
  }
  // 成功路径的 after 就是刚写下的那条记录（own 态的定义如此），不必再解析一遍——
  // 那会白付一趟 git 与持久面读，而结果只可能等价。
  return resultOf(
    { kind: "own", record },
    true,
    "Bound this session to the worktree." +
      " Open or refresh the right-sidebar Files tab to see it; the session cwd is unchanged," +
      " and @ references / present targets still resolve against the cwd.",
  );
}

/** 会话是否在一个 git 仓库里。不在就没有工具可言。 */
export async function repoOf(deps: ToolsDeps, agent: AgentFace): Promise<string | undefined> {
  if (agent.cwd === undefined) return undefined;
  const common = await deps.git.commonDir(agent.cwd);
  return common === undefined ? undefined : agent.cwd;
}

/**
 * `ws_worktree_remove`：摘掉登记；只有显式 `removeDirectory` 才连带 `git worktree remove`。
 *
 * 默认不删目录是刻意的：删除可能丢掉未提交改动，而「我只是想换个根」与「我要销毁这个工作区」
 * 是两件事，不该由同一个默认值承担。
 *
 * **继承态不摘任何东西**：本会话没有自己的登记时，右栏的根属于父会话——摘它是改别人的状态，
 * 删目录更是销毁别人的工作区。这一态只如实说明并给出路。
 */
import type { ToolDefinition } from "@deepseek-ai/dsh-tools";
import type { ToolsDeps } from "../../deps.ts";
import { NO_ORIGIN, readOrigin, resultOf } from "../bind/index.ts";
import { argBool, RESULT_SCHEMA, renderResult } from "../protocol/index.ts";
import type { ToolResultValue } from "../protocol/index.ts";
import { sessionOf } from "../session/index.ts";

/**
 * 继承态的解绑出路。三条互为补充：第 1 条是正路；2、3 两条在**父会话已经结束**（fork 的常见
 * 形态）时仍然走得通。第 3 条把本会话登记到自己的 cwd，视觉上等于取消继承——写的是一条**普通
 * 登记**（own 优先覆盖继承），不是任何形式的否定登记。
 */
function inheritedHelp(ownerSessionId: string, cwd: string | undefined): string {
  const main =
    "Nothing to unbind here: the Files tab root belongs to session " +
    ownerSessionId +
    ", not to this session. To stop following it: (1) unbind it in that session with ws_worktree_remove, " +
    "or (2) bind this session to another worktree with ws_worktree_create / ws_worktree_register.";
  if (cwd === undefined) return main;
  return (
    main +
    " A third option, when that session is gone: bind this session to its own working directory with " +
    'ws_worktree_register({ worktree: "' +
    cwd +
    '" }), which makes this session stop inheriting.'
  );
}

export function buildRemoveTool(deps: ToolsDeps): ToolDefinition {
  return {
    name: "ws_worktree_remove",
    description:
      "Unbind the worktree from THIS session; the right-sidebar Files tab returns to the session cwd " +
      "on its next open or refresh. " +
      "This only touches this session's own binding: when the Files tab follows a root inherited from a " +
      "parent session instead, the tool refuses (it never unbinds or removes another session's worktree) " +
      "and reports which session owns that root plus the ways to stop following it. " +
      "By default the worktree directory is left in place - pass removeDirectory: true to also run " +
      "git worktree remove, and force: true as well when it has uncommitted changes you accept losing. " +
      "The plugin never deletes directories itself.",
    parameters: {
      type: "object",
      properties: {
        removeDirectory: {
          type: "boolean",
          description:
            "Also remove the worktree directory with git worktree remove. Defaults to false: only the binding is dropped.",
        },
        force: {
          type: "boolean",
          description:
            "Adds --force to git worktree remove, discarding uncommitted changes. Only valid together with removeDirectory: true.",
        },
      },
      additionalProperties: false,
    },
    output: {
      schema: RESULT_SCHEMA,
      render: (_args: unknown, value: unknown) => renderResult(value as ToolResultValue),
    },
    execute: async (args: unknown, exec: unknown): Promise<ToolResultValue> => {
      const session = sessionOf(exec);
      if (session === undefined) {
        return resultOf(
          NO_ORIGIN,
          false,
          "This tool needs an agent session, and the call carries none. Run it as an agent tool call.",
        );
      }
      const read = await readOrigin(deps, session.id);
      // 读不到绑定状态时也在**参数解析之前**报失败：那会儿连「本会话有没有自己的登记」都不知道，
      // 继续往下只会给出一个基于中性读数的错答案。
      if (read.problem !== undefined) return resultOf(read.origin, false, read.problem);
      // 继承态与未绑定态同样在参数解析之前判掉：否则 {removeDirectory:true} 会走到下面
      // 拿不到自己的记录，回一句含糊的失败，模型会以为「重试一次就好」。
      const origin = read.origin;
      if (origin.kind === "inherited") {
        return resultOf(origin, false, inheritedHelp(origin.ownerSessionId, session.cwd));
      }
      if (origin.kind === "none") {
        return resultOf(
          origin,
          false,
          "No worktree is bound to this session, so there is nothing to unbind.",
        );
      }
      const removeDirectory = argBool(args, "removeDirectory");
      const force = argBool(args, "force");
      if (force && !removeDirectory) {
        return resultOf(
          origin,
          false,
          "force only applies together with removeDirectory: true; the binding is unchanged.",
        );
      }

      if (!removeDirectory) {
        const dropped = await deps.binding.drop(session.id);
        if (!dropped.ok) {
          return resultOf(origin, false, "Could not persist the unbind: " + dropped.reason);
        }
        // 摘掉自己的登记之后**必须重新解析**：右栏可能回落到继承来的根，那是调用者必须知道的事实。
        const after = await readOrigin(deps, session.id);
        if (after.problem !== undefined) {
          // 摘除已经落盘，动作成功；只是现状读不回来——如实说不确定，而不是猜一个状态。
          return resultOf(
            after.origin,
            true,
            "Unbound this session's own binding. The Files tab root could not be read back: " +
              after.problem,
          );
        }
        return resultOf(
          after.origin,
          true,
          after.origin.kind === "inherited"
            ? "Unbound this session's own binding. The Files tab now follows the root inherited from " +
                "session " +
                after.origin.ownerSessionId +
                "."
            : "Unbound the worktree from this session. The directory was left in place; open or refresh " +
                "the Files tab to return to the session cwd.",
        );
      }

      const removed = await deps.git.removeWorktree(
        origin.record.repoRoot,
        origin.record.worktreeRoot,
        force,
      );
      if (!removed.ok) {
        return resultOf(
          origin,
          false,
          "git worktree remove failed: " + removed.reason + " The binding is unchanged.",
        );
      }
      const dropped = await deps.binding.drop(session.id);
      if (!dropped.ok) {
        // 目录已经没了、登记还在：解析器会把「目录不存在」按未绑定处理，故这是一条自愈路径，
        // 但对调用者必须说清楚，否则下次来看会以为还绑着。
        return resultOf(
          origin,
          false,
          "Removed the worktree directory, but the binding could not be dropped: " +
            dropped.reason +
            " It is now stale and will be treated as unbound; call this tool again to retry the unbind.",
        );
      }
      const after = await readOrigin(deps, session.id);
      if (after.problem !== undefined) {
        // 目录与登记都已经落地，动作成功；现状读不回来时如实说明。
        return resultOf(
          after.origin,
          true,
          "Unbound this session and removed the worktree directory with git worktree remove. " +
            "The Files tab root could not be read back: " +
            after.problem,
        );
      }
      return resultOf(
        after.origin,
        true,
        after.origin.kind === "inherited"
          ? "Unbound this session and removed the worktree directory with git worktree remove. The " +
              "Files tab now follows the root inherited from session " +
              after.origin.ownerSessionId +
              "."
          : "Unbound this session and removed the worktree directory with git worktree remove.",
      );
    },
  };
}

