/**
 * api 域的两个端点。都是只读的：浏览器侧没有写绑定的路径。
 *
 * 两个刻意的取舍：
 * - 绑定查询**不回 repoRoot**。客户端只需要目录根，多回一个字段就多一份「客户端知道主仓库位置」的暴露面。
 * - 缺 `session` 参数判 400 而不是回空。前者是调用方出错（可修），后者会被误读成「该会话没有绑定」。
 *
 * 两个事实来自两个域（修订号来自 binding、生效根来自 scope），故入参是两个窄端口而不是一个拼出来的对象。
 */
import type { Endpoint } from "../route/index.ts";
import type { EffectiveWorktreePort, RevisionPort, ScopeStatePort } from "../../deps.ts";
import { ROUTES } from "../../../../shared/interface.ts";
import type { BindingResponse } from "../../../../shared/interface.ts";
import { writeJson } from "../../../../../../../shared/host-utils.js";

/** 从 `req.url` 取 query 参数。返回 undefined 表示缺席或空串（两者对调用方同义）。 */
function queryParam(url: string | undefined, name: string): string | undefined {
  if (url === undefined) return undefined;
  // 用固定 base 解析相对 URL：路由处理器拿到的是 path?query 形态，不是绝对 URL。
  const value = new URL(url, "http://placeholder.invalid").searchParams.get(name);
  return value === null || value.length === 0 ? undefined : value;
}

/** `GET /api/dsh-worktree-sidebar/bindings?session=<id>` —— 单会话文件根查询。 */
export function bindingsEndpoint(binding: RevisionPort, scope: EffectiveWorktreePort): Endpoint {
  return {
    path: ROUTES.bindings,
    methods: {
      GET: async (req, res) => {
        const session = queryParam(req.url, "session");
        if (session === undefined) {
          writeJson(res, 400, { ok: false, error: { message: "缺少 session 参数" } });
          return;
        }
        // 先生算出生效根、再读 revision：这样报出去的 revision 不会早于它所描述的那个事实。
        const worktreePath = await scope.effectiveWorktree(session);
        const body: BindingResponse = { revision: binding.revision(), worktreePath };
        writeJson(res, 200, body);
      },
    },
  };
}

/**
 * `GET /api/dsh-worktree-sidebar/health` —— 存活探针。带回 revision 与接管状态，让它同时是有用的状态查询。
 *
 * `scopeTakeover` 是「文件根为什么没换」的第一手证据：真实启动序里 provider 与插件的先后没有稳定保证，
 * 只报「没换根」会让 waiting / abandoned / 未命中绑定三种成因长得一模一样。
 *
 * `scopeChain` 解的是另一类**无声**故障：已结束会话的父链只能从持久面读，读不出来时本域按「到顶」收口
 * （正确的行为），于是继承悄悄退回 live-only——而真机上插件的 `logger.warn` 不落盘（doc §19.5），
 * 现场除这个读数之外没有任何痕迹。
 */
export function healthEndpoint(binding: RevisionPort, scope: ScopeStatePort): Endpoint {
  return {
    path: ROUTES.health,
    methods: {
      GET: (_req, res) => {
        writeJson(res, 200, {
          ok: true,
          revision: binding.revision(),
          scopeTakeover: scope.takeoverState(),
          scopeChain: scope.chainDiagnostics(),
        });
      },
    },
  };
}

/**
 * api 域装配：**浏览器出口**。把宿主端的事实经 HTTP 送到页面；本域不判业务，也不写任何状态。
 *
 * 它是本插件唯一的浏览器入口，所以围栏（回环判定、方法判定、异常收口）也只有一份实现，
 * 少写一处就是多开一个洞。
 *
 * 已挂路由的 disposer 住在实例里；域是**进程内单例**，第二次 `install` 由 `installed` 守卫
 * **显式抛错**（响亮失败优于静默共享/丢数据）。
 */
import type { ApiDeps } from "../../deps.ts";
import { bindingsEndpoint, healthEndpoint } from "../handlers/index.ts";
import { registerEndpoints } from "../route/index.ts";

/** api 域实例：装配的产物只对外给一个释放面。 */
export interface ApiInstance {
  /** 摘掉全部路由。幂等。 */
  release(): void;
}

/** 浏览器出口：唯一实例。 */
class ApiService implements ApiInstance {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  /** 已挂路由的摘除器。释放即逐个调用并清空，所以不会叠成两份。 */
  private disposers: Array<() => void> = [];
  /** 路由当前是否在册。释放幂等靠它，也靠它区分「没装过」与「已摘完」。 */
  private live = false;

  /** 装配浏览器出口（组合根在 apply 期调用一次）。重复装配是编程错误，当场暴露。 */
  install(deps: ApiDeps): void {
    if (this.installed) throw new Error("dsh-worktree-sidebar: api 域只能装配一次");
    // 先注册、成功了才算装上：挂在装配标记之后的话，一次中途失败会让这个域停在
    // 「已装配但没路由、也没摘除器」的半装态——组合根的释放链里没有它（它的 push 还没走到），
    // 于是同进程的下一次装配会撞上「只能装配一次」。
    const disposers = registerEndpoints(
      deps.register,
      [bindingsEndpoint(deps.binding, deps.scope), healthEndpoint(deps.binding, deps.scope)],
      deps.logger,
    );
    this.installed = true;
    this.disposers = disposers;
    this.live = true;
  }

  /** 摘掉全部路由并复位装配标记——同进程的下一次 `install` 会重新注册，且只注册一份。 */
  release(): void {
    this.installed = false;
    if (!this.live) return;
    this.live = false;
    for (const dispose of this.disposers) {
      try {
        dispose();
      } catch {
        // 卸载阶段不做失败上报：一个端点的摘除失败不该阻断其余，也不该掩盖首个异常。
      }
    }
    this.disposers = [];
  }
}

/** 本域唯一实例：类不外放，外面 `new` 不出第二份注册。 */
export const apiService = new ApiService();

/**
 * api 域对外契约：**浏览器出口**。把宿主端的事实经 HTTP 送到页面。
 *
 * 本文件只做收口——单例与它的 `ApiInstance` 形状的物理定义都在 `impl/service`（形状不从门面转出：
 * 它是实现细节，转出就成了本域的第二张公开契约），围栏与端点注册在 `impl/route`，端点形状在 `impl/handlers`。
 * 本域不对外提供能力（端点就是它的产物），门面因此只有装配与释放。
 */
import type { ApiDeps } from "./deps.ts";
import { apiService } from "./impl/service/index.ts";

/** 装配浏览器出口（组合根在 `apply` 期调用一次）。重复装配是编程错误，当场抛错。 */
export function installApi(deps: ApiDeps): void {
  apiService.install(deps);
}

/** 摘掉全部路由，与 `installApi` 配对（重复调用无害）。 */
export function releaseApi(): void {
  apiService.release();
}

/**
 * 绑定表纯逻辑：形状校验、按会话索引、revision 递增规则。
 *
 * 不碰磁盘、不碰宿主——所以「损坏文件当空表」「revision 单调」「摘不存在的会话不涨 revision」
 * 这三条判据可以被单测直接打红，不需要起 cordis，也不需要真文件。
 */
import { BINDINGS_VERSION } from "./type.ts";
import type { BindingRecord, BindingsFile } from "./type.ts";

/** 空表。revision 从 0 起：它是**内容版本**而不是写入次数，客户端只做相等比较。 */
export function emptyTable(): BindingsFile {
  return { version: BINDINGS_VERSION, revision: 0, bindings: {} };
}

/** 单条记录的字段校验。任何一项不合格就丢弃该条——半条记录比没有记录更危险。 */
export function validateRecord(value: unknown): BindingRecord | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const raw = value as Record<string, unknown>;
  const repoRoot = raw["repoRoot"];
  const worktreeRoot = raw["worktreeRoot"];
  const branch = raw["branch"];
  const createdAt = raw["createdAt"];
  const sessionCreatedAt = raw["sessionCreatedAt"];
  if (typeof repoRoot !== "string" || repoRoot.length === 0) return undefined;
  if (typeof worktreeRoot !== "string" || worktreeRoot.length === 0) return undefined;
  if (typeof branch !== "string") return undefined;
  if (typeof createdAt !== "string") return undefined;
  // 身份凭据缺席就丢弃这条记录：留着它等于留着「新会话可能继承旧登记」那个洞。
  if (typeof sessionCreatedAt !== "number" || !Number.isFinite(sessionCreatedAt)) return undefined;
  return { repoRoot, worktreeRoot, branch, createdAt, sessionCreatedAt };
}

/**
 * 解析绑定表文本。**任何**异常与形状不符都回落空表：这里没有「部分恢复」的选项——
 * 一条来源不明的绑定会把会话的文件树指向一个用户没选过的目录。
 */
export function parseTable(text: string): BindingsFile {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return emptyTable();
  }
  if (typeof parsed !== "object" || parsed === null) return emptyTable();
  const raw = parsed as Record<string, unknown>;
  // 只接受当前版本：更高版本字段含义未定，猜错会静默挂错目录；更低版本的迁移路径在真正出现旧版时才引入。
  if (raw["version"] !== BINDINGS_VERSION) return emptyTable();
  const revision = raw["revision"];
  if (typeof revision !== "number" || !Number.isFinite(revision) || revision < 0)
    return emptyTable();
  const entries = raw["bindings"];
  if (typeof entries !== "object" || entries === null) return emptyTable();
  const bindings: Record<string, BindingRecord> = {};
  for (const [sessionId, value] of Object.entries(entries as Record<string, unknown>)) {
    if (sessionId.length === 0) continue;
    const record = validateRecord(value);
    if (record !== undefined) bindings[sessionId] = record;
  }
  return { version: BINDINGS_VERSION, revision, bindings };
}

/** 序列化。带缩进是为了让人能直接看这份文件——它的内容就是「哪个会话指向哪」的全部答案。 */
export function serializeTable(table: BindingsFile): string {
  return JSON.stringify(table, null, 2) + "\n";
}

/** 落一条绑定。revision 递增：客户端以它判定「宿主侧是否已经变了」。 */
export function putBinding(
  table: BindingsFile,
  sessionId: string,
  record: BindingRecord,
): BindingsFile {
  return {
    version: table.version,
    revision: table.revision + 1,
    bindings: { ...table.bindings, [sessionId]: record },
  };
}

/** 摘一条绑定。目标不存在时**原样返回**（不涨 revision）：否则每次「清理一个本来就没有的会话」都会让全网客户端白刷一次。 */
export function dropBinding(table: BindingsFile, sessionId: string): BindingsFile {
  if (!(sessionId in table.bindings)) return table;
  const bindings = { ...table.bindings };
  delete bindings[sessionId];
  return { version: table.version, revision: table.revision + 1, bindings };
}

/** binding 域的磁盘面：读文本交给纯逻辑解析、写走共享层原子写。这里不做判断，只搬运。 */
import { readTextFileSync, writeTextAtomic } from "../../../shared/interface.ts";
import type { FileWrite } from "../../../shared/interface.ts";
import type { BindingsFile } from "../model/type.ts";
import { parseTable, serializeTable } from "../model/index.ts";

/** 读绑定表。文件缺失、不可读、内容损坏一律回落空表（parseTable 自己兜底）。 */
export function loadTable(file: string): BindingsFile {
  const read = readTextFileSync(file);
  if (!read.ok) return parseTable("");
  return parseTable(read.text);
}

/** 原子写绑定表。返回值而不是抛异常——调用方对失败的处置是统一的「内存不前移 + 出声」。 */
export function saveTable(file: string, table: BindingsFile): Promise<FileWrite> {
  return writeTextAtomic(file, serializeTable(table));
}

/**
 * binding 域对外契约：绑定表的**唯一事实源**。
 *
 * 本文件只做收口——`BindingApi` 与单例的物理定义在 `impl/service`，表的读写形状在 `impl/model`，
 * 落盘在 `impl/store`。单例本身不出这道门：它一旦被转出就成了本域的第二张公开契约，
 * 调用方还能持有它、绕过释放。
 */
import type { BindingRecord } from "./impl/model/type.ts";
import type { FileWrite } from "../shared/interface.ts";
import type { BindingDeps } from "./deps.ts";
import { bindingService } from "./impl/service/index.ts";

export { BINDINGS_VERSION } from "./impl/model/type.ts";
export type { BindingRecord } from "./impl/model/type.ts";

/** 装配 binding 域（组合根在 `apply` 期调用一次）。重复装配是编程错误，当场抛错。 */
export function installBinding(deps: BindingDeps): void {
  bindingService.install(deps);
}

/** 卸载 binding 域，与 `installBinding` 配对：等在飞的写盘落定后丢掉内存快照。此后能力面当场失败。 */
export function releaseBinding(): Promise<void> {
  return bindingService.release();
}

/** 当前表版本。与 api 域路由读的是同一快照，故它也是客户端能观察到的版本。 */
export function revision(): number {
  return bindingService.revision();
}

/** 按会话取绑定。 */
export function get(sessionId: string): BindingRecord | undefined {
  return bindingService.get(sessionId);
}

/** 落一条绑定并持久化。 */
export function put(sessionId: string, record: BindingRecord): Promise<FileWrite> {
  return bindingService.put(sessionId, record);
}

/** 摘一条绑定并持久化（幂等：本来就没有不算失败）。 */
export function drop(sessionId: string): Promise<FileWrite> {
  return bindingService.drop(sessionId);
}

/**
 * git 执行面的真实实现：`execFile` + argv，**不经 shell**。
 *
 * argv 数组是安全边界的一半——路径与分支名里的空格、`;`、`$()` 不会被任何 shell 重新解释；
 * 另一半在 argv 构造处（`impl/inspect`）。两件事分开写，是为了让「谁负责什么」在评审时看得见。
 */
import { execFile } from "node:child_process";
import type { GitExecPort, GitRunResult } from "../../deps.ts";

/** 单次 git 调用的墙钟上限。挂住的 git 会把整个文件树拖死，而这只查询在最坏情况下也远快于它。 */
const TIMEOUT_MS = 10_000;

/** stdout 上限。超限按失败处理而不是截断——截断的 `worktree list` 会解析出一个残缺的仓库结构。 */
const MAX_BUFFER = 4 * 1024 * 1024;

/** 真实的 git 执行面。它没有任何状态，故是常量而不是工厂——组合根没得选，测试换的是装配入参。 */
export const gitExec: GitExecPort = {
  run: (args) =>
    new Promise<GitRunResult>((resolve) => {
      execFile(
        "git",
        [...args],
        { timeout: TIMEOUT_MS, maxBuffer: MAX_BUFFER, windowsHide: true },
        (error, stdout, stderr) => {
          // git 没装时 stderr 是空串，只有 error 知道原因（spawn git ENOENT）；
          // 不把它折进来，上层看到的失败原因就是一句没有信息量的「退出码非零」。
          const detail = stderr.length > 0 ? stderr : error === null ? "" : error.message;
          // 只有数字 code 才是「git 跑完了并给出退出码」；字符串 code（如 ENOENT）与 timeout 的
          // killed 都是「没跑成」，上层据此保住上一次结论而不是把它当成否定答案。
          const code = error === null ? 0 : typeof error.code === "number" ? error.code : null;
          resolve({ ok: error === null, stdout, stderr: detail, code });
        },
      );
    }),
};

/**
 * git 域对外契约：worktree 归属查询与增删。
 *
 * 本文件只做收口——`GitApi` 与单例的物理定义在 `impl/service`（`GitApi` 形状不从门面转出），argv 构造在 `impl/inspect`。
 * `gitExec` 也从这里出去：组合根只允许引 `interface.ts`（verify-dir-imports 规则 1/2），
 * 把它藏进 impl 会让组合根要么直引实现、要么自己重写一份 exec。
 * 单例本身不出这道门：它一旦被转出就成了本域的第二张公开契约，调用方还能持有它、绕过释放。
 */
import type { BelongsToReading, GitDeps } from "./deps.ts";
import type { WorktreeEntry } from "./impl/inspect/index.ts";
import type { GitMutation } from "./impl/service/index.ts";
import { gitService } from "./impl/service/index.ts";

/** 真实的 git 执行面：它没有状态，故按常量转出而不是工厂。 */
export { gitExec } from "./impl/exec/index.ts";

/** 装配 git 域（组合根在 `apply` 期调用一次）。重复装配是编程错误，当场抛错。 */
export function installGit(deps: GitDeps): void {
  gitService.install(deps);
}

/** 卸载 git 域，与 `installGit` 配对：丢掉归属缓存与装配入参。此后能力面当场失败。 */
export function releaseGit(): void {
  gitService.release();
}

/** 该目录是否在某个仓库里；是则给公共 git 目录的**绝对**路径。 */
export function commonDir(dir: string): Promise<string | undefined> {
  return gitService.commonDir(dir);
}

/** 同一主仓库下的全部 worktree。 */
export function listWorktrees(dir: string): Promise<readonly WorktreeEntry[]> {
  return gitService.listWorktrees(dir);
}

/** `dir` 与 `repoRoot` 是否属于同一仓库。三态：`unknown` 不是「不同」。 */
export function belongsTo(dir: string, repoRoot: string): Promise<BelongsToReading> {
  return gitService.belongsTo(dir, repoRoot);
}

/** 某 worktree 的当前分支显示名。 */
export function headBranch(dir: string): Promise<string | undefined> {
