/**
 * 新建 worktree。`base` 必须已经被调用方归一化成 commit SHA（理由见 `resolveCommit`）。
 */
export function addWorktree(
  repoRoot: string,
  path: string,
  branch: string | undefined,
  base: string | undefined,
