/**
 * 宿主 agent 适配层：把官方 `Agent` 面收窄成 tools 域认得的注册面。
 *
 * 「装给**所有** agent（含子 agent）」与「装进去的效应随 agent 一起释放」这两条判断住在这里。
 * 它只认下面这个窄端口，因此不需要起 cordis 就能被白盒驱动。
 */
import type { ToolDefinition } from "@deepseek-ai/dsh-tools";
import type { AgentFace, AgentPort } from "../tools/deps.ts";

/**
 * 适配器真正用到的宿主 agent 面。刻意与官方 `Agent` 解耦：公开的 `Agent` 面要求一个真的
 * `Context`，而本适配器只用「身份 / 会话 cwd / 往这个作用域装工具 / 效应随作用域释放」四件事。
 * 官方 `Agent` 结构上可赋值给它。
 */
export interface HostAgentLike {
  readonly id: string;
  readonly session: { readonly header: { readonly cwd?: string } };
  readonly ctx: {
    readonly tools: { register(definition: ToolDefinition): () => void };
    /** 返回该效应的释放器；官方实现是「可等待的」，域内只需能调用它。 */
    effect(execute: () => () => void): () => unknown;
  };
}

/** 宿主事件面与 agent 枚举面：只开本适配器要的两样。 */
export interface AgentHostPort {
  /** 订阅 agent 发布。返回退订函数。 */
  on(event: "agent/created", handler: (payload: { agent: HostAgentLike }) => void): () => void;
  /** 当前**所有存活** agent 快照（含子 agent）。 */
  all(): readonly HostAgentLike[];
}

/** agent 注册面：工具域只看到「一个 agent 有 id、有 cwd、可以往里装工具」。 */
export function bindAgents(host: AgentHostPort): AgentPort {
  const faceOf = (agent: HostAgentLike): AgentFace => ({
    id: agent.id,
    cwd: agent.session.header.cwd,
  });

  return {
    subscribe: (handler) =>
      host.on("agent/created", ({ agent }) => {
        // 这里原先按顶层枚举挡掉子 agent，理由是「子代理的工具面由它的调用方决定，不该被本插件改变」。
        // 该判断被**有意推翻**（不是删除时漏掉守卫）：子会话同样会点开侧边栏、同样需要把 worktree
        // 登记给自己那条会话，而工具装进各 agent 自己的 effect、随该 agent 一起释放，
        // 并不会改动调用方的工具面。子会话的展示语义见 README。
        handler(faceOf(agent));
      }),
    list: () => host.all().map(faceOf),
    publish: (face, definitions) => {
      // 按 id 现查而不是缓存 agent 对象：缓存要能覆盖「宣告过但已退场」的 id 就得永不删除，
      // 而 agent 的 ctx 挂着它整个服务图——装给所有子 agent 之后那就是进程级的无界增长。
      // 代价是「宣告与装配之间被释放」的窄竞态落到下面的抛错分支（tools 域本来就会 catch 出声）。
      const agent = host.all().find((candidate) => candidate.id === face.id);
      if (agent === undefined) {
        // 「未装配的占位要抛错」而不是给空 disposer：`publish` 的调用点是自家 tools 域的同步
        // 调用，且只发生在 list/subscribe 递出同一个 face 之后，未知 id 只可能是组合根递错了
        // 一个从没注册过的 face。静默回空会让它表现成「工具装上了但其实没有」。
        // 与 notifier 的「挂在宿主事件链上、未装配时静默丢弃」相反先例无关：那是宿主回调，
        // 这里是我们自己的同步调用。
        throw new Error(`dsh-worktree-sidebar: agent ${face.id} 未注册，拒绝把工具装进未知作用域`);
      }
      // 装进 agent 自己的 effect：agent 释放时工具随之摘除，顺序交给框架，
      // 我们不需要另外订阅 agent/disposed。
      const disposers = definitions.map((definition) => agent.ctx.tools.register(definition));
      const disposeTools = (): void => {
        for (const dispose of disposers) {
          try {
            dispose();
          } catch {
            // 卸载阶段不做失败上报，避免掩盖首个异常。
          }
        }
      };
      const dispose = agent.ctx.effect(() => disposeTools);
      // cordis 的 effect disposer 是**可等待的**（Disposable<Promise<void>>），而 tools 域的释放链是同步的
      // （它的调用点全部在同步的卸载路径上）。agent 释放在框架侧本来就会跑这个 effect，
      // 这里只是允许主动提前；因此不阻塞，也不让 rejection 变成未处理拒绝。
      return () => {
        void Promise.resolve(dispose()).catch(() => undefined);
      };
    },
  };
}

/**
 * 会话链适配层：只回答「这个会话的父会话是谁」。
 *
 * 官方把父链记在会话 header 上（`parentSession?: SessionId`，dsh-session/lib/types/types.d.ts:71）。它有两个来源，
 * **两个都必要**：活会话走 `ctx.sessions.get`（同步），已结束会话只能走持久面 `sessionPersistence.stat`
 * （单会话定位，不读事件日志）——官方 `dsh-session/lib/index.js:1550-1557` 的 `get` 契约明写是
 * "Look up a live session"，会话被释放/detach 之后 header 就取不到了。而 UI 里能点选的子会话恰恰是
 * **已结束**的那些，少了持久面这一半，继承在用户可见的那个状态上就是空的。
 *
 * 持久面是可选服务（`dsh-base/cordis.patch.yml:110-111` 的 jsonl 后端提供）：缺席时如实回 undefined，
 * 继承退回 live-only，功能降级而不是把整条文件根解析拖垮。
 */
import type { SessionId } from "@deepseek-ai/dsh-session";
import type { LiveParent, SessionChainPort, SessionIdentity } from "../scope/deps.ts";

/**
 * 官方会话 header 的窄面。`createdAt` 与 `parentSession` 同样重要：
 * id 是进程内计数器、重启后会重排，绑定要靠 `createdAt` 才认得出「这是不是同一个会话」。
 */
interface SessionHeaderFace {
  readonly parentSession?: string;
  readonly createdAt: number;
}

/** 官方 sessions 服务的窄面：只按 id 取一次**活**会话记录。 */
export interface SessionsFace {
  get(id: SessionId): { readonly header: SessionHeaderFace } | undefined;
}

/** 官方持久会话服务的窄面：只取一条已结束会话的 header。 */
export interface StoredSessionsFace {
  stat(id: SessionId): Promise<{ readonly header: SessionHeaderFace } | undefined>;
}

/**
 * 身份读数：`createdAt` 是有限数才算凭据，否则按「读不出来」回 undefined。
 *
 * 为什么要在这里拦一道：`scope` 域把「凭据与登记不同」当成**正面证据**并据此摘掉用户的绑定，
 * 于是畸形 header（非数值）会被读成「另一个会话」。官方存储不会产出这种 header
 * （`dsh-session` 构造与恢复都校验/填充），但本包对同类外部输入（`sessionOf`、`validateRecord`）
 * 一律在边界校验，这里保持同一条纪律。
 */
function identityFrom(createdAt: number): SessionIdentity | undefined {
  return Number.isFinite(createdAt) ? { createdAt } : undefined;
}

export function bindSessions(
  sessions: SessionsFace,
  /**
   * 持久面按**调用时刻**取：`ctx.get` 的语义是「取当刻值，未提供回 undefined」
   * （`cordis/lib/index.js:754-771`），在 apply 期取一次会让晚挂的后端永久退化成缺席。
   */
  storedSessions: () => StoredSessionsFace | undefined,
): SessionChainPort {
  return {
    liveParentOf: (sessionId): LiveParent => {
      const session = sessions.get(sessionId as SessionId);
      if (session === undefined) return { kind: "not-live" };
      const parent = session.header.parentSession;
      return parent === undefined ? { kind: "root" } : { kind: "parent", id: parent };
    },
    storedParentOf: async (sessionId) => {
      const stored = storedSessions();
      if (stored === undefined) return undefined;
      const snapshot = await stored.stat(sessionId as SessionId);
      return snapshot?.header.parentSession;
    },
    liveIdentityOf: (sessionId): SessionIdentity | undefined => {
      const live = sessions.get(sessionId as SessionId);
      return live === undefined ? undefined : identityFrom(live.header.createdAt);
    },
    storedIdentityOf: async (sessionId): Promise<SessionIdentity | undefined> => {
      const stored = storedSessions();
      if (stored === undefined) return undefined;
      const snapshot = await stored.stat(sessionId as SessionId);
      // 持久面也没有这条会话：此刻无从核对，交给调用方按「读不了不等于不存在」处置。
      return snapshot === undefined ? undefined : identityFrom(snapshot.header.createdAt);
    },
  };
}

/**
 * typert 适配层：官方类型只在这里出现，scope 域只认自己的窄接口。
 *
 * 两处**刻意**的窄化，各自的依据都写在这里：
 * 1. `lookups.get()` 的返回类型是**无参数**的 `TypertLookupProvider`（`unknown/unknown`），
 *    参数只出现在 `register` / `configure` 的重载上（dsh-typert-protocol/lib/types/types.d.ts:389）。
 *    运行时它确实是该键的描述符，所以这里按键的类型断言回来。
 * 2. 我们的 `FileScope.sessionId` 是 `string`，官方 wire 是品牌化的 `SessionId`——
 *    品牌只在边界上有意义，域内带着它只会让五个域都得认识官方类型。
 */
import type { WorkspaceFileScope } from "@deepseek-ai/dsh-api-workspace-files";
import type { SessionId } from "@deepseek-ai/dsh-session";
import type { TypertLookupRegistry } from "@deepseek-ai/dsh-typert-protocol";
import type { FileScope, TypertPort } from "../scope/deps.ts";

/**
 * 查找表窄面：本插件只读当前描述符、配置自己那一个键、并订阅变化，其余能力（register/definitions）不开。
 *
 * `subscribe` 是「等 provider」那条路径的唯一叫醒源：官方 `register`/`withdraw` 都会 emit
 * `{kind:"lookup", key}`（dsh-typert-registry/lib/index.js:238-251 与 :211-224），
 * 监听器不关心事件载荷，只把「再看一眼」这件事做一次。
 */
export type TypertLookupsPort = Pick<TypertLookupRegistry, "get" | "configure" | "subscribe">;

export function bindTypert(lookups: TypertLookupsPort): TypertPort {
  return {
    current: () => {
      const descriptor = lookups.get("workspaceFileScope") as
        | {
            resolve: (
              id: SessionId,
            ) => WorkspaceFileScope | undefined | Promise<WorkspaceFileScope | undefined>;
          }
        | undefined;
      if (descriptor === undefined) return undefined;
      const resolve = descriptor.resolve.bind(descriptor);
      return {
        resolve: async (sessionId: string): Promise<FileScope | undefined> => {
          const scope = await resolve(sessionId as SessionId);
          if (scope === undefined) return undefined;
          return { sessionId: scope.sessionId, workspaceRoot: scope.workspaceRoot };
        },
      };
    },
    subscribe: (listener) => lookups.subscribe(() => listener()),
    configure: (resolver) =>
      lookups.configure("workspaceFileScope", async (sessionId) => {
        const scope = await resolver(sessionId);
        if (scope === undefined) return undefined;
        // sessionId 用官方那一个（已品牌化），而不是我们回传的字符串。
        return { sessionId, workspaceRoot: scope.workspaceRoot };
      }),
  };
}

mutants.replacement:
for (; false;) {
  const parent = await parentOf(deps, current);
  if (parent === undefined || seen.has(parent)) return undefined;
  seen.add(parent);
  const inherited = await ownRecord(deps, parent);
  if (inherited !== undefined) return {
    record: inherited,
    ownerSessionId: parent
  };
  current = parent;
}

