/**
 * 继承父会话的登记：本会话没登记时沿父链向上找。
 *
 * 子会话是**独立会话**——dsh-subagent 建它时只把父的 cwd 拷进子 header
 * （dsh-subagent/lib/index.js:504-510），而绑定记在父会话 id 上（工具是从会话上下文取 id 写登记的）。
 * 不问父链，子 agent 的文件根就永远是它自己的 cwd。
 *
 * 用户 fork 出来的会话走的是同一条判据（header.parentSession），本域**刻意不区分** fork 与子 agent：
 * fork 的 header 同样拷了父的 cwd，视图根跟着一起继承才与「文件根是会话 cwd 的改写」自洽。
 *
 * 三条边界是硬的：到顶即停（没有父就回未绑定）、父链成环时不转圈（错数据不该把请求拖死）、
 * 父会话的登记失效时按它自己的自愈逻辑摘掉并继续向上（最终仍是未命中，也就是回退自己的 cwd）。
 */
import type { BindingRecord } from "../../../binding/interface.ts";
import type { ScopeDeps } from "../../deps.ts";
import { ownRecord } from "../own/index.ts";

/**
 * 沿父链找到的第一个有效登记，连同**持有它的那个会话 id**（不是直接父）。
 *
 * `ownerSessionId` 是工具面唯一能给出的「去哪个会话解绑」的答案，所以它必须是持有登记的那个祖先，
 * 而不是只上跳一步的父——多级 fork 链上这两者并不相同。
 */
export async function inheritedOrigin(
  deps: ScopeDeps,
  sessionId: string,
): Promise<{ record: BindingRecord; ownerSessionId: string } | undefined> {
  const seen = new Set<string>([sessionId]);
  let current = sessionId;
  for (;;) {
    const parent = await parentOf(deps, current);
    if (parent === undefined || seen.has(parent)) return undefined;
    seen.add(parent);
    const inherited = await ownRecord(deps, parent);
    if (inherited !== undefined) return { record: inherited, ownerSessionId: parent };
    current = parent;
  }
}

/**
 * 上跳一步。活 header 优先；只有「不在册」才回落持久面——活着的顶层会话是**确定的到顶**，
 * 再去问持久面等于给每个普通会话白加一次 IO。
 *
 * 持久面坏了按「到顶」收口：它答不出来时正确的行为是让文件根退回会话自己的 cwd，
 * 而不是把异常抛进解析器（解析器与路由共用这条路径，抛出去等于把右栏文件树一起打掉）。
 */
async function parentOf(deps: ScopeDeps, sessionId: string): Promise<string | undefined> {
  const live = deps.sessions.liveParentOf(sessionId);
  if (live.kind === "parent") return live.id;
  if (live.kind === "root") return undefined;
  try {
    return await deps.sessions.storedParentOf(sessionId);
  } catch {
    return undefined;
  }
}

/**
 * 一个会话**自己**的登记现在还有效吗——失效就摘掉。
 *
 * 摘掉而不是仅仅忽略：客户端以 revision 判定缓存有效性，只忽略不摘的话 revision 不变、
 * 客户端继续把文件根指向 worktree，而宿主已经按 cwd 解析——用户看到的是持续的 outside-workspace
 * 报错，且没有任何东西会自愈。
 *
 * 但「失效」的要求是硬证据。三条判据里只有**确实拿到**了否定答案的那种才允许摘：
 * 目录不存在（`stat` 说 ENOENT）、会话 id 已被另一个会话复用（`createdAt` 不同）、
 * 两侧都读出了公共 git 目录且不同。读不出来的一律保住登记——一次权限抖动或持久面抖动
 * 不该变成一次永久的摘除。
 *
 * 自愈（摘除）经 `binding.drop` 写盘，所以本函数的调用方**不只是解析器**：工具面读绑定来源时
 * 也走它，于是工具调用同样可能摘掉一条已确认失效的登记——这是刻意的，不摘的话那条登记永远不会
 * 自愈，而它已经确定不成立了。
 */
import { statSync } from "node:fs";
import type { BindingRecord } from "../../../binding/interface.ts";
import type { ScopeDeps, SessionIdentity } from "../../deps.ts";

/** 存在性判定看到的形状。窄到只需要一个方法，测试才能用一个字面量替身驱动。 */
interface StatLike {
  isDirectory(): boolean;
}

/** 默认实现：直连 fs。`throwIfNoEntry` 只把 ENOENT 变成 undefined，其余错误照抛。 */
function realStat(path: string): StatLike | undefined {
  return statSync(path, { throwIfNoEntry: false });
}

/**
 * 目录是否真的在。只有 ENOENT/ENOTDIR 才算「不在」；其它错误（EACCES、EIO）按存在处理。
 *
 * `stat` 是可注入的：这段「读不了不等于不存在」的语义正是最容易写错、也最不该靠真实权限去构造
 * 测试环境的地方（换成 `return false` 会把一次权限抖动变成永久摘掉用户的绑定）。
 */
export function directoryExists(
  path: string,
  stat: (p: string) => StatLike | undefined = realStat,
): boolean {
  try {
    return stat(path)?.isDirectory() === true;
  } catch {
    // 读不了不等于不存在。把权限或 IO 抖动当成「目录没了」会**永久摘掉**用户的绑定，
    // 而重试的代价只是这一次列表失败。
    return true;
  }
}

/**
 * 只看本会话自己的登记：没有、或已失效（目录没了 / 已不是该仓库的 worktree）都回 undefined。
 *
 * 返回整条记录而不是根：调用方（解析器与工具面）还要用到根之外的字段（分支名、仓库根），
 * 只回一个字符串会让它们各自再查一遍表。
 */
export async function ownRecord(
  deps: ScopeDeps,
  sessionId: string,
): Promise<BindingRecord | undefined> {
  const record = deps.binding.get(sessionId);
  if (record === undefined) return undefined;

  const exists = deps.existsDirectory ?? directoryExists;
  if (!exists(record.worktreeRoot)) {
    await drop(deps, sessionId, "worktree 目录不存在：" + record.worktreeRoot);
    return undefined;
  }
  const identity = await identityOf(deps, sessionId);
  if (identity !== undefined && identity.createdAt !== record.sessionCreatedAt) {
    await drop(
      deps,
      sessionId,
      "会话 id 已被另一个会话复用（登记属于 createdAt=" +
        record.sessionCreatedAt +
        "，当前会话是 " +
        identity.createdAt +
        "）：" +
        record.worktreeRoot,
    );
    return undefined;
  }
  const belongs = await deps.git.belongsTo(record.worktreeRoot, record.repoRoot);
  if (belongs.kind === "different") {
    await drop(deps, sessionId, "已不是该仓库的 worktree：" + record.worktreeRoot);
    return undefined;
  }
  if (belongs.kind === "unknown") {
    // 保留登记 + 出声：这一次问不出归属，正确的行为是沿用上次的成功态，而不是摘掉用户的登记。
    deps.logger.warn(
      "dsh-worktree-sidebar: 无法确认 worktree 归属，保留该会话的登记 — " + belongs.reason,
    );
  }
  return record;
}

/** 核对会话身份。读不出来（持久面缺席或抛错）时回 undefined，调用方因此保住登记。 */
async function identityOf(
  deps: ScopeDeps,
  sessionId: string,
): Promise<SessionIdentity | undefined> {
  const live = deps.sessions.liveIdentityOf(sessionId);
  if (live !== undefined) return live;
  try {
    return await deps.sessions.storedIdentityOf(sessionId);
  } catch (cause) {
    deps.logger.warn(
      "dsh-worktree-sidebar: 无法核对会话身份，保留该会话的登记 — " +
        (cause instanceof Error ? cause.message : String(cause)),
    );
    return undefined;
  }
}

async function drop(deps: ScopeDeps, sessionId: string, reason: string): Promise<void> {
  deps.logger.warn("dsh-worktree-sidebar: " + reason + " —— 已摘掉该会话的登记");
  try {
    const dropped = await deps.binding.drop(sessionId);
    if (!dropped.ok) {
      deps.logger.warn("dsh-worktree-sidebar: 摘除失效绑定失败 — " + dropped.reason);
    }
  } catch (cause) {
    deps.logger.warn(
      "dsh-worktree-sidebar: 摘除失效绑定抛出 — " +
        (cause instanceof Error ? cause.message : String(cause)),
    );
  }
}

/**
 * 把「绑定」翻译成「生效的文件根」。解析器与浏览器路由**共用**这一个函数，
 * 两端因此不可能各说各话（降级预案 G7 的根治办法：不是让两边都算对，而是让只有一边在算）。
 *
 * 文件根的两个来源分别是 `impl/own`（本会话自己的登记）与 `impl/inherit`（沿父链继承），
 * 本文件只负责把它们合成一个答案、并保证解析器**永不抛出**。
 *
 * `bindingOrigin` 是这条链条对外的**唯一事实源**：它不只回答「根在哪」，还回答「根是谁的」。
 * 工具面要区分「本会话自己的登记」与「继承来的登记」，唯一正确的做法就是读它——让工具面
 * 另算一遍继承，得到的就是本插件最该避免的「两个事实源各说一句话」。
 */
import type { BindingRecord } from "../../../binding/interface.ts";
import type { FileScope, ScopeDeps } from "../../deps.ts";
import { inheritedOrigin } from "../inherit/index.ts";
import { ownRecord } from "../own/index.ts";

/**
 * 绑定来源。用判别联合而不是「根 + 若干冗余字段」：`root` 恒等于 `record.worktreeRoot`，
 * 存两份就多一个能漂移的地方；`kind` 也把「没有登记」时其余字段该取什么值这个问题整个消掉。
 */
export type WorktreeOrigin =
  | { readonly kind: "none" }
  | { readonly kind: "own"; readonly record: BindingRecord }
  | { readonly kind: "inherited"; readonly record: BindingRecord; readonly ownerSessionId: string };

/** 来源对应的 worktree 根；`none`（该会话按官方语义走）回 null。 */
export function rootOf(origin: WorktreeOrigin): string | null {
  return origin.kind === "none" ? null : origin.record.worktreeRoot;
}

/** 本会话的绑定来源：自己的登记优先，其次沿父链继承，都没有就是 none。 */
export async function bindingOrigin(deps: ScopeDeps, sessionId: string): Promise<WorktreeOrigin> {
  const own = await ownRecord(deps, sessionId);
  if (own !== undefined) return { kind: "own", record: own };
  const inherited = await inheritedOrigin(deps, sessionId);
  if (inherited !== undefined) {
    return {
      kind: "inherited",
      record: inherited.record,
      ownerSessionId: inherited.ownerSessionId,
    };
  }
  return { kind: "none" };
}

/** 当前生效的 worktree 根；null 表示该会话按官方语义（cwd）走。 */
export async function effectiveWorktree(
  deps: ScopeDeps,
  sessionId: string,
): Promise<string | null> {
  return rootOf(await bindingOrigin(deps, sessionId));
}

/**
 * 解析器的入口：命中绑定就给 worktree，否则委托。
 *
 * **永不抛出**是这里的核心承诺：官方 gateway 把 resolver 的异常翻成 `gateway/lookup-failed`，
 * 那是整条文件读取链路的硬失败，不是回退。所以 catch 必须在这里，而不是指望上游。
 */
export async function resolveScope(
  deps: ScopeDeps,
  delegate: (sessionId: string) => Promise<FileScope | undefined>,
  sessionId: string,
): Promise<FileScope | undefined> {
  try {
    const root = await effectiveWorktree(deps, sessionId);
    if (root !== null) return { sessionId, workspaceRoot: root };
  } catch (cause) {
    deps.logger.warn(
      "dsh-worktree-sidebar: 解析文件根失败，回退官方语义 — " +
        (cause instanceof Error ? cause.message : String(cause)),
    );
  }
  try {
    return await delegate(sessionId);
  } catch (cause) {
    // 委托是官方的 resolve，它抛错说明上游环境有问题；
    // 回 undefined 让 gateway 走它的 lookup-not-found，而不是让异常从这里逃出去。
    deps.logger.warn(
      "dsh-worktree-sidebar: 官方默认解析失败 — " +
        (cause instanceof Error ? cause.message : String(cause)),
    );
    return undefined;
  }
}

/**
 * scope 域对外契约：接管 `workspaceFileScope` 的解析，命中绑定就把会话的文件根指到 worktree。
 *
 * 本文件只做收口——单例与它的 `ScopeApi` 形状的物理定义都在 `impl/service`（形状不从门面转出），
 * 解析判定在 `impl/resolve`。单例本身不出这道门：它一旦被转出就成了
 * 本域的第二张公开契约，调用方还能持有它、绕过释放。
 */
import type { ScopeDeps } from "./deps.ts";
import type { WorktreeOrigin } from "./impl/resolve/index.ts";
import { rootOf } from "./impl/resolve/index.ts";
import { scopeService } from "./impl/service/index.ts";

export { rootOf };
export type { WorktreeOrigin };

/** 装配 scope 域（组合根在 `apply` 期调用一次）。重复装配是编程错误，当场抛错。 */
export function installScope(deps: ScopeDeps): void {
  scopeService.install(deps);
}

/** 卸载 scope 域，与 `installScope` 配对：把 resolver 交还官方。此后能力面当场失败。 */
export function releaseScope(): void {
  scopeService.release();
}

/** 当前**生效**的 worktree 根；null 表示该会话按 cwd 走。 */
export function effectiveWorktree(sessionId: string): Promise<string | null> {
  return scopeService.effectiveWorktree(sessionId);
}

/**
 * 该会话的**绑定来源**（自己的登记 / 继承来的登记 / 没有）。
 *
 * 与 `effectiveWorktree` 的唯一差别是**不设 takeover 门**：工具面要的是「登记事实」，
 * 而文件根有没有真的换成它由 `/health` 的 `scopeTakeover` 报告。waiting / abandoned 期
 * 两者结论不同（工具面照旧给出登记，浏览器面仍按 cwd），这是刻意设计，不是 bug。
 */
export function worktreeOrigin(sessionId: string): Promise<WorktreeOrigin> {
  return scopeService.worktreeOrigin(sessionId);
}

/**
 * 接管状态的诊断读数（`idle` / `waiting` / `live` / `abandoned`）。
 *
 * 只给 health 端点用：真实启动序里「provider 与插件谁先到」没有稳定保证，这个读数让
 * 「文件根没换根」当场可分辨成「还没等到 provider」「被别人占了」「接管了但没命中绑定」三种。
 */
export function takeoverState(): ReturnType<typeof scopeService.takeoverState> {
  return scopeService.takeoverState();
}

/**
 * 会话链持久面的读数（查了几次 / 坏了几次 / 最后一次的原因）。
 *
 * 只给 health 端点用：持久面读失败被收口成「到顶」是一处**静默降级**，这条读数是它唯一落地的痕迹。
 */
export function chainDiagnostics(): ReturnType<typeof scopeService.chainDiagnostics> {
  return scopeService.chainDiagnostics();
}

/**
 * 落盘 IO 的单一实现：先写同目录临时文件、再 `rename` 覆盖。
 *
 * 同一文件系统内 `rename` 是原子的，读到的要么是旧内容要么是新内容；
 * 直接 `writeFile` 到目标则在截断与写入之间留了窗口，而绑定表被读的时刻
 * 恰好是文件树的每次刷新。失败用返回值表达而不是抛出——调用方的处置一律是
 * 「保持上次成功态 + 出声」，异常在类型上就不该是控制流。
 */
import { readFileSync } from "node:fs";
import { mkdir, rename, writeFile } from "node:fs/promises";
import { dirname } from "node:path";

/** 读取结果：「不存在」「不可读」「是目录」归为同一类——调用方对三者的处置都是回落空值。 */
type FileRead = { readonly ok: true; readonly text: string } | { readonly ok: false };

/** 写入结果。 `reason` 是给日志用的原因文本，不含路径之外的额外事实。 */
export type FileWrite = { readonly ok: true } | { readonly ok: false; readonly reason: string };

/** 同步读全文。只给装配路径用：装配返回时必须已拿到最终值，否则会开一个「读面已可用、文件还没加载」的窗口。 */
export function readTextFileSync(file: string): FileRead {
  try {
    return { ok: true, text: readFileSync(file, "utf8") };
  } catch {
    return { ok: false };
  }
}

/** 原子写全文：补齐父目录 → 写临时文件 → `rename` 覆盖。父目录在这里补齐，谁给出路径谁负责让它可写。 */
export async function writeTextAtomic(file: string, text: string): Promise<FileWrite> {
  const temporary = `${file}.tmp-${process.pid}`;
  try {
    await mkdir(dirname(file), { recursive: true });
    await writeFile(temporary, text, "utf8");
    await rename(temporary, file);
    return { ok: true };
  } catch (cause) {
    // 不清临时文件：同名临时文件会被下一次写入覆盖，不会累积。
    return { ok: false, reason: cause instanceof Error ? cause.message : String(cause) };
  }
}

/**
 * 落盘位置的单一事实源。只看 `DSH_HOME` 一个变量（经 shared/dsh-home.js 归一），
 * 隔离验证换掉它即换掉全部落盘位置——路径若在别处再拼一次，隔离性就有第二个事实源。
 */
import { join } from "node:path";
import { dshHome } from "../../../../../shared/dsh-home.js";

/** 本插件在 DSH home 下的私有目录（按 npm 包名分区，避免与其它插件争用根目录）。 */
const PACKAGE_DIR = "@wingsky-1/dsh-worktree-sidebar";

/** 绑定表文件名。 */
const BINDINGS_FILE_NAME = "bindings.json";

/** 绑定表完整路径。目录是否存在由写入方按需创建。 */
export function bindingsFile(): string {
  return join(dshHome(), PACKAGE_DIR, BINDINGS_FILE_NAME);
}

/** `ws_worktree_create`：先 `git worktree add` 建出来，再登记给当前会话。 */
import type { ToolDefinition } from "@deepseek-ai/dsh-tools";
import type { ToolsDeps } from "../../deps.ts";
import { bindWorktree, NO_ORIGIN, readOrigin, resolveTarget, resultOf } from "../bind/index.ts";
import { argString, RESULT_SCHEMA, renderResult } from "../protocol/index.ts";
import type { ToolResultValue } from "../protocol/index.ts";
import { sessionOf } from "../session/index.ts";

export function buildCreateTool(deps: ToolsDeps): ToolDefinition {
  return {
    name: "ws_worktree_create",
    description:
      "Create a git worktree from this session's repository with git worktree add, then bind it to " +
      "THIS session so the right-sidebar Files tab is rooted at it (open or refresh that tab to see " +
      "the new root). The session cwd does not change. " +
      "Prefer this over a bare git worktree add when the Files tab should show the new worktree: a bare " +
      "git command creates the directory but leaves the Files tab rooted at the session cwd (for a " +
      "worktree you created that way, call ws_worktree_register on it instead). " +
      "Path and branch are yours to choose; the plugin imposes no layout convention. " +
      "base defaults to the current HEAD of the repository the session working directory is in, so pass " +
      "it explicitly when you need a different start point. " +
      "If git worktree add succeeds but binding fails, the directory is left in place and the result says " +
      "so. Whether the Files tab then actually follows the binding is reported by GET " +
      "/api/dsh-worktree-sidebar/health as scopeTakeover.",
    parameters: {
      type: "object",
      properties: {
        path: {
          type: "string",
          description:
            "Where to create the worktree: an absolute path, or a path relative to the session working directory.",
        },
        branch: {
          type: "string",
          description:
            "Optional branch to create for the worktree (git worktree add -b). Validated with " +
            "git check-ref-format --branch before git is called. Omit to check out the start point " +
            "detached (git worktree add --detach): that is base, or the repository HEAD when base is " +
            "omitted too. Creating no branch also works for paths whose last segment is not a valid " +
            "branch name.",
        },
        base: {
          type: "string",
          description:
            "Optional start point (commit-ish: branch, tag, or SHA, e.g. origin/main). Defaults to the " +
            "current HEAD of the repository the session working directory is in.",
        },
      },
      required: ["path"],
      additionalProperties: false,
    },
    output: {
      schema: RESULT_SCHEMA,
      render: (_args: unknown, value: unknown) => renderResult(value as ToolResultValue),
    },
    execute: async (args: unknown, exec: unknown): Promise<ToolResultValue> => {
      const session = sessionOf(exec);
      if (session === undefined) {
        return resultOf(
          NO_ORIGIN,
          false,
          "This tool needs an agent session, and the call carries none. Run it as an agent tool call.",
        );
      }
      if (session.cwd === undefined) {
        return resultOf(
          NO_ORIGIN,
          false,
          "This session has no working directory, so it cannot be checked against a git repository.",
        );
      }
      const repo = session.cwd;
      if ((await deps.git.commonDir(repo)) === undefined) {
        return resultOf(NO_ORIGIN, false, "This session is not inside a git repository.");
      }
      const raw = argString(args, "path");
      if (raw === undefined) {
        return resultOf(NO_ORIGIN, false, "Missing required parameter: path.");
      }
      // 来源解析放在上面那些廉价校验之后：早退路径不白付一趟 git 与持久面读。
      const read = await readOrigin(deps, session.id);
      if (read.problem !== undefined) return resultOf(read.origin, false, read.problem);
      const origin = read.origin;
      const target = resolveTarget(repo, raw);
      const branch = argString(args, "branch");
      if (branch !== undefined && !(await deps.git.checkRefFormat(branch))) {
        return resultOf(
          origin,
          false,
          "Not a valid git branch name: " +
            branch +
            " (git check-ref-format --branch rejected it).",
        );
      }
      const base = argString(args, "base");
      // 形态 guard 必须在 git 调用之前：起点位置的 "-" 开头值会被 worktree add 内部的选项解析吞掉
      // （实测 -f / --force 会 rc=0 但忽略起点、从 HEAD 建），那正是「静默产出过期基线」本身。
      if (base !== undefined && base.startsWith("-")) {
        return resultOf(
          origin,
          false,
          "Not a valid start point: " + base + ' (a start point must not begin with "-").',
        );
      }
      let startPoint: string | undefined;
      if (base !== undefined) {
        // 归一化成 SHA 之后再进 argv：SHA 不以 "-" 开头，二次解析因此无处下手。
        startPoint = await deps.git.resolveCommit(repo, base);
        if (startPoint === undefined) {
          return resultOf(origin, false, "Not a valid start point: " + base + ".");
        }
      }

      const created = await deps.git.addWorktree(repo, target, branch, startPoint);
      if (!created.ok) {
        return resultOf(origin, false, "git worktree add failed: " + created.reason);
      }

      const bound = await bindWorktree(deps, session, repo, target, deps.now(), origin);
      if (!bound.ok) {
        // 建出来了但没绑上：这是一次**部分成功**，不能报成失败让调用者以为目录没建。
        return {
          ...bound,
          detail:
            "The worktree was created at " +
            target +
            ", but binding it to this session failed: " +
            bound.detail +
            " The directory is left in place: bind it with ws_worktree_register, or remove it with " +
            "git worktree remove -- " +
            target,
        };
      }
      return {
        ...bound,
        detail:
          "Created the worktree and bound this session to it. Open or refresh the right-sidebar Files " +
          "tab to see it; the session cwd is unchanged.",
      };
    },
  };
}

/**
 * 工具的输入读取与结果信封。
 *
 * 三个工具共用同一个结果形状，是为了让「当前指向哪个 worktree」这件事永远出现在返回文本里：
 * 失败路径也要说清现状，否则模型在错误之后只知道「失败了」，不知道自己现在到底绑在哪。
 *
 * 输出 schema 只用 enforced subset 支持的键（单一 `type`、无 type 数组），
 * 「没有值」一律用空串表达而不是 null——该子集不接受可空类型。
 */
import type { JsonSchemaNode } from "@deepseek-ai/dsh-tools";

/** 三个工具的统一返回值。 */
export interface ToolResultValue {
  /** 本次请求的操作是否成功。 */
  readonly ok: boolean;
  /** 调用之后该会话是否仍有绑定（含沿父链继承来的那条）。 */
  readonly bound: boolean;
  /** 绑定指向的 worktree 绝对路径；`bound` 为 false 时是空串。 */
  readonly worktree: string;
  /** 绑定的分支名；无绑定或 detached 时是空串。 */
  readonly branch: string;
  /** 面向模型的结果说明：成功是事实陈述，失败是原因加可操作的下一步。 */
  readonly detail: string;
}

/** 结果信封的 schema（`output.schema`）。 */
export const RESULT_SCHEMA: JsonSchemaNode = {
  type: "object",
  properties: {
    ok: { type: "boolean", description: "Whether the requested operation succeeded." },
    bound: {
      type: "boolean",
      description:
        "Whether a worktree is bound to this session or inherited from a parent session after the call.",
    },
    worktree: {
      type: "string",
      description: "Absolute path of the bound worktree; empty when bound is false.",
    },
    branch: {
      type: "string",
      description: "Bound branch name; empty when bound is false or the worktree is detached.",
    },
    detail: {
      type: "string",
      description:
        "What happened: for failures, the reason and the next thing to try; for successes, the effect.",
    },
  },
  required: ["ok", "bound", "worktree", "branch", "detail"],
  additionalProperties: false,
};

/**
 * 结果渲染。**状态行永远在前**：模型据此知道调用后的真实状态，不必再调一次工具确认。
 */
export function renderResult(value: ToolResultValue): Array<{ type: "text"; text: string }> {
  const state = value.bound
    ? "bound worktree: " + value.worktree + (value.branch === "" ? "" : " [" + value.branch + "]")
    : "no worktree bound to this session";
  return [{ type: "text", text: state + "\n" + value.detail }];
}

/** 读一个非空字符串参数。空白串视同缺席（模型偶尔会给空串表示「没填」）。 */
export function argString(args: unknown, key: string): string | undefined {
  if (typeof args !== "object" || args === null) return undefined;
  const value = (args as Record<string, unknown>)[key];
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  return trimmed.length === 0 ? undefined : trimmed;
}

/** 读一个布尔参数。只有显式 `true` 为真——缺席、非布尔、字符串 "true" 都不算。 */
export function argBool(args: unknown, key: string): boolean {
  if (typeof args !== "object" || args === null) return false;
  return (args as Record<string, unknown>)[key] === true;
}

/** `ws_worktree_register`：把一个**已存在**的 worktree 登记给当前会话。 */
import type { ToolDefinition } from "@deepseek-ai/dsh-tools";
import type { ToolsDeps } from "../../deps.ts";
import {
  availableWorktrees,
  bindWorktree,
  directoryProblem,
  NO_ORIGIN,
  readOrigin,
  resolveTarget,
  resultOf,
} from "../bind/index.ts";
import { argString, RESULT_SCHEMA, renderResult } from "../protocol/index.ts";
import type { ToolResultValue } from "../protocol/index.ts";
import { sessionOf } from "../session/index.ts";

export function buildRegisterTool(deps: ToolsDeps): ToolDefinition {
  return {
    name: "ws_worktree_register",
    description:
      "Bind an existing git worktree to THIS session, so the right-sidebar Files tab is rooted at that " +
      "worktree once you open or refresh it. The session cwd does not change. " +
      "Use this when the directory already exists - including a worktree you created with a bare " +
      "git worktree add, which creates the directory but leaves the Files tab on the session cwd; use " +
      "ws_worktree_create when the worktree still has to be created. Only the Files tab follows the " +
      "binding: @ file references, present targets and the skill catalog still resolve against the " +
      "session cwd, and under the workspace-write file policy the agent cannot write into the worktree. " +
      "If this session inherits a root from a parent session, binding here overrides that inherited root " +
      "for this session only. Whether the Files tab then actually follows the binding is reported by GET " +
      "/api/dsh-worktree-sidebar/health as scopeTakeover.",
    parameters: {
      type: "object",
      properties: {
        worktree: {
          type: "string",
          description:
            "The worktree to bind: an absolute path, or a path relative to the session working directory.",
        },
      },
      required: ["worktree"],
      additionalProperties: false,
    },
    output: {
      schema: RESULT_SCHEMA,
      render: (_args: unknown, value: unknown) => renderResult(value as ToolResultValue),
    },
    execute: async (args: unknown, exec: unknown): Promise<ToolResultValue> => {
      const session = sessionOf(exec);
      if (session === undefined) {
        return resultOf(
          NO_ORIGIN,
          false,
          "This tool needs an agent session, and the call carries none. Run it as an agent tool call.",
        );
      }
      if (session.cwd === undefined) {
        return resultOf(
          NO_ORIGIN,
          false,
          "This session has no working directory, so it cannot be checked against a git repository.",
        );
      }
      if ((await deps.git.commonDir(session.cwd)) === undefined) {
        return resultOf(NO_ORIGIN, false, "This session is not inside a git repository.");
      }
      const raw = argString(args, "worktree");
      if (raw === undefined) {
        return resultOf(NO_ORIGIN, false, "Missing required parameter: worktree.");
      }
      // 来源解析放在上面那些廉价校验之后：早退路径不必为一句「没有 cwd」白付一趟 git 子进程。
      const read = await readOrigin(deps, session.id);
      if (read.problem !== undefined) return resultOf(read.origin, false, read.problem);
      const origin = read.origin;
      const target = resolveTarget(session.cwd, raw);
      const problem = directoryProblem(target);
      if (problem !== undefined) {
        return resultOf(origin, false, problem + (await availableWorktrees(deps, session.cwd)));
      }
      return bindWorktree(deps, session, session.cwd, target, deps.now(), origin);
    },
  };
}

/**
 * tools 域装配：把三个工具装进「位于 git 仓库里的」所有 agent 的作用域（含子 agent）。
 *
 * 两条入口缺一不可：`agent/created` 覆盖之后发布的 agent，`list()` 覆盖**本装配之前就已经在跑**的那些。
 * 后者不是理论情形——dev HMR、动态装插件、以及任何在会话已经打开时才挂上的插件都会撞上它，
 * 而漏掉它的表现是「老会话看不到工具」，且只在重启后才复现。
 *
 * 已注册的 agent 映射与订阅住在实例里；域是**进程内单例**，第二次 `install` 由 `installed` 守卫
 * **显式抛错**（响亮失败优于静默共享/丢数据）。
 */
import type { ToolDefinition } from "@deepseek-ai/dsh-tools";
import type { AgentFace, ToolsDeps } from "../../deps.ts";
import { buildCreateTool } from "../create/index.ts";
import { buildRemoveTool } from "../remove/index.ts";
import { buildRegisterTool } from "../register/index.ts";
import { repoOf } from "../bind/index.ts";

/** 三个工具的注册者：唯一实例。 */
class ToolsService {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  private deps: ToolsDeps | undefined;
  /** 每个 agent 的工具摘除器。释放时逐个调用并清空，下一次装配才装得进同一个 agent。 */
  private readonly perAgent = new Map<string, () => void>();
  private unsubscribe: (() => void) | undefined;
  // 判定要走一次 git，是异步的；不串行化的话两个同时发布的 agent 会各自看到「尚未注册」，
  // 于是同一个 agent 被装两遍。
  private chain: Promise<unknown> = Promise.resolve();
  /**
   * 装配代数。在飞的异步判定跨过一次 release 就作废——否则它会把上一代的 deps 装进新一代，
   * 而那种串味的症状是「工具装了但绑的是上一个装配体的表」。
   */
  private generation = 0;

  /** 装配工具域。重复装配是编程错误，当场暴露。 */
  install(deps: ToolsDeps): void {
    if (this.installed) throw new Error("dsh-worktree-sidebar: tools 域只能装配一次");
    this.installed = true;
    this.deps = deps;
    const generation = this.generation;
    const consider = (agent: AgentFace): void => this.consider(generation, agent);
    this.unsubscribe = deps.agents.subscribe(consider);
    for (const agent of deps.agents.list()) consider(agent);
  }

  /**
   * 卸载：退订、逐个摘掉每个 agent 的工具、丢掉映射与在飞的异步链，复位装配标记。重复调用无害。
   * 映射必须清空——留着它下一次装配会把同一个 agent 当成「已装过」直接跳过，工具永远装不上。
   */
  release(): void {
    this.installed = false;
    this.generation += 1;
    this.deps = undefined;
    const unsubscribe = this.unsubscribe;
    this.unsubscribe = undefined;
    if (unsubscribe !== undefined) {
      try {
        unsubscribe();
      } catch {
        // 卸载阶段不做失败上报，避免掩盖首个异常。
      }
    }
    for (const dispose of [...this.perAgent.values()].reverse()) {
      try {
        dispose();
      } catch {
        // 同上。
      }
    }
    this.perAgent.clear();
    this.chain = Promise.resolve();
  }

  /** 判定一个 agent 是否该装工具，该装就装。同一个 agent 只处理一次。 */
  private consider(generation: number, agent: AgentFace): void {
    this.chain = this.chain
      .then(async () => {
        const deps = this.deps;
        if (deps === undefined) return;
        if (generation !== this.generation || this.perAgent.has(agent.id)) return;
        if ((await repoOf(deps, agent)) === undefined) return;
        // 解析期间可能已被释放、已被换了一代装配，或该 agent 已被处理过：都要重新确认。
        if (generation !== this.generation || this.perAgent.has(agent.id)) return;
        const definitions: readonly ToolDefinition[] = [
          buildRegisterTool(deps),
          buildCreateTool(deps),
          buildRemoveTool(deps),
        ];
        this.perAgent.set(agent.id, deps.agents.publish(agent, definitions));
      })
      .catch((cause: unknown) => {
        const deps = this.deps;
        // 失败要归因到活着的那一代：落后一代的失败连「谁的 logger」都无从谈起。
        if (deps === undefined || generation !== this.generation) return;
        const reason = cause instanceof Error ? cause.message : String(cause);
        deps.logger.warn("dsh-worktree-sidebar: 工具注册失败 — " + reason);
      });
  }
}

/** 本域唯一实例：类不外放，外面 `new` 不出第二份注册表。 */
export const toolsService = new ToolsService();

/**
 * 执行期身份解析：从 `exec` 取会话身份与工作目录。
 *
 * `exec.agent` 在类型上是可选的（子派发、非 agent 调用都没有它），所以这里返回
 * `undefined` 而不是抛错；调用方必须把它翻成一句明确的失败，而不是回落到 `process.cwd()`
 * ——后者会把绑定挂到一个与调用者无关的目录上。
 */
export interface SessionFace {
  readonly id: string;
  readonly cwd: string | undefined;
  /**
   * 会话 header 的创建时间。登记要把它一起落盘：id 是进程内计数器，重启后会被新会话复用，
   * 没有它就分不清「同一个会话」与「另一个会话拿到了同一个 id」。
   */
  readonly createdAt: number | undefined;
}

/** 解析会话身份。形状不符即 undefined，不猜。 */
export function sessionOf(exec: unknown): SessionFace | undefined {
  if (typeof exec !== "object" || exec === null) return undefined;
  const session = readObject(readObject(exec, "agent"), "session");
  if (session === undefined) return undefined;
  const id = (session as { id?: unknown }).id;
  if (typeof id !== "string" || id.length === 0) return undefined;
  const header = readObject(session, "header");
  const cwd = header === undefined ? undefined : (header as { cwd?: unknown }).cwd;
  const createdAt = header === undefined ? undefined : (header as { createdAt?: number }).createdAt;
  return {
    id,
    cwd: typeof cwd === "string" && cwd.length > 0 ? cwd : undefined,
    createdAt: typeof createdAt === "number" && Number.isFinite(createdAt) ? createdAt : undefined,
  };
}

function readObject(source: unknown, key: string): unknown {
  if (typeof source !== "object" || source === null) return undefined;
  const value = (source as Record<string, unknown>)[key];
  return typeof value === "object" && value !== null ? value : undefined;
}

/**
 * tools 域对外契约：三个 agent 工具的注册与释放。
 *
 * 工具按 **agent 作用域**注册（每个 agent 自己的 `ctx.tools`），只在会话位于 git 仓库里时才装；
 * 会话不在仓库里就一个工具都不给——给了也只会每次都失败。
 *
 * 本文件只做收口：门面的物理定义在 `impl/service`。本域不对外提供能力（工具就是它的产物），
 * 门面因此只有装配与释放。
 */
import type { ToolsDeps } from "./deps.ts";
import { toolsService } from "./impl/service/index.ts";

/** 装配工具域（组合根在 `apply` 期调用一次）。重复装配是编程错误，当场抛错。 */
export function installTools(deps: ToolsDeps): void {
  toolsService.install(deps);
}

/** 卸载工具域，与 `installTools` 配对：退订 + 摘掉每个 agent 的工具（重复调用无害）。 */
export function releaseTools(): void {
  toolsService.release();
}

