describe("子 agent 继承父会话的登记", () => {
  const official: LookupDescriptorPort = {
    resolve: async (id) => ({ sessionId: id, workspaceRoot: "/official" }),
  };

  it("本会话没登记时取父会话的生效根", async () => {
    const { deps } = scopeDeps({
      binding: { parent: record },
      parents: { child: "parent" },
      exists: true,
      belongs: true,
    });
    expect(await effectiveWorktree(deps, "child")).toBe("/wt");
  });

  it("父链多级：本会话 → 父 → 祖父", async () => {
    const { deps } = scopeDeps({
      binding: { grand: record },
      parents: { child: "parent", parent: "grand" },
      exists: true,
      belongs: true,
    });
    expect(await effectiveWorktree(deps, "child")).toBe("/wt");
  });

  it("自己登记了就不向上看（父的登记是另一个根）", async () => {
    const own: BindingRecord = { ...record, worktreeRoot: "/wt-own" };
    const { deps } = scopeDeps({
      binding: { child: own, parent: record },
      parents: { child: "parent" },
      exists: true,
      belongs: true,
    });
    expect(await effectiveWorktree(deps, "child")).toBe("/wt-own");
  });

  it("到顶（没有父）按未绑定处理，且不再向不存在的父会话查登记", async () => {
    const { deps, bindingGets, storedCalls } = scopeDeps({
      binding: { parent: record },
      parents: {},
      exists: true,
      belongs: true,
    });
    expect(await effectiveWorktree(deps, "child")).toBeNull();
    expect(bindingGets).toEqual(["child"]);
    // 活着的会话答「没有父」就是确定的到顶：不该再去问持久面（那是请求路径上的额外 IO）。
    expect(storedCalls).toEqual([]);
  });

  it("父链成环时停下（错数据不转圈，每个会话最多查一次）", async () => {
    const { deps, bindingGets } = scopeDeps({ parents: { a: "b", b: "a" }, exists: true });
    expect(await effectiveWorktree(deps, "a")).toBeNull();
    expect(bindingGets).toEqual(["a", "b"]);
  });

  it("父会话的登记失效 → 摘掉它，仍按未绑定处理（回退自己的 cwd）", async () => {
    const { deps, dropped, table } = scopeDeps({
      binding: { parent: record },
      parents: { child: "parent" },
      exists: false,
    });
    expect(await effectiveWorktree(deps, "child")).toBeNull();
    expect(dropped).toEqual(["parent"]);
    expect(table.has("parent")).toBe(false);
  });

  it("子会话已结束（不在册）时从持久面取父链：继承仍然成立", async () => {
    const { deps, storedCalls } = scopeDeps({
      binding: { parent: record },
      notLive: ["child"],
      storedParents: { child: "parent" },
      exists: true,
      belongs: true,
    });
    expect(await effectiveWorktree(deps, "child")).toBe("/wt");
    expect(storedCalls).toEqual(["child"]);
  });

  it("多级父链跨两种来源：结束的子 → 结束的父 → 活着的祖父", async () => {
    const { deps, storedCalls } = scopeDeps({
      binding: { grand: record },
      notLive: ["child", "parent"],
      storedParents: { child: "parent", parent: "grand" },
      exists: true,
      belongs: true,
    });
    expect(await effectiveWorktree(deps, "child")).toBe("/wt");
    expect(storedCalls).toEqual(["child", "parent"]);
  });

  it("持久面读不出来时按「到顶」收口，不把异常抛进解析器", async () => {
    const { deps } = scopeDeps({
      binding: { parent: record },
      notLive: ["child"],
      storedThrows: true,
      exists: true,
      belongs: true,
    });
    expect(await effectiveWorktree(deps, "child")).toBeNull();
  });

  it("持久面查了几次、坏了几次都进 health 读数（那是这处无声降级唯一的痕迹）", async () => {
    const hit = scopeDeps({
      descriptor: official,
      binding: { parent: record },
      notLive: ["child"],
      storedParents: { child: "parent" },
      exists: true,
      belongs: true,
    });
    installScope(hit.deps);
    expect(await scopeService.effectiveWorktree("child")).toBe("/wt");
    expect(chainDiagnostics()).toEqual({
      storedReads: 1,
      storedFailures: 0,
      lastFailure: undefined,
    });

    releaseScope();
    const broken = scopeDeps({
      descriptor: official,
      notLive: ["child"],
      storedThrows: true,
      exists: true,
      belongs: true,
    });
    installScope(broken.deps);
    // 收口仍然成立（到顶），但这一次失败必须留在读数里，而不是只留在没人看得到的 catch 里。
    expect(await scopeService.effectiveWorktree("child")).toBeNull();
    expect(chainDiagnostics()).toEqual({
      storedReads: 1,
      storedFailures: 1,
      lastFailure: "stored sessions unavailable",
    });
  });

  it("活着的顶层会话不查持久面，读数也必须是 0（判定与成本读数同源）", async () => {
    const { deps } = scopeDeps({
      descriptor: official,
      binding: { s1: record },
      exists: true,
      belongs: true,
    });
    installScope(deps);
    expect(await scopeService.effectiveWorktree("s1")).toBe("/wt");
    expect(chainDiagnostics().storedReads).toBe(0);
  });

  it("release 复位读数：下一次装配从 0 起，不留上一代的痕迹", async () => {
    const first = scopeDeps({ descriptor: official, notLive: ["child"], storedThrows: true });
    installScope(first.deps);
    await scopeService.effectiveWorktree("child");
    expect(chainDiagnostics().storedFailures).toBe(1);

    releaseScope();
    const second = scopeDeps({ descriptor: official, notLive: ["child"], storedParents: {} });
    installScope(second.deps);
    await scopeService.effectiveWorktree("child");
    expect(chainDiagnostics()).toEqual({
      storedReads: 1,
      storedFailures: 0,
      lastFailure: undefined,
    });
  });

  it("持久面缺席（组合里没挂后端）＝退回 live-only，不抛", async () => {
    const { deps } = scopeDeps({
      binding: { parent: record },
      notLive: ["child"],
      exists: true,
      belongs: true,
    });
    expect(await effectiveWorktree(deps, "child")).toBeNull();
  });

  it("路由与解析器读同一份继承结果（一处实现覆盖两端）", async () => {
    const { deps, configured } = scopeDeps({
      descriptor: official,
      binding: { parent: record },
      parents: { child: "parent" },
      exists: true,
      belongs: true,
    });
    installScope(deps);
    // 路由那条（api 域读 effectiveWorktree）与 resolver 那条（官方 gateway 读它）必须同源。
    expect(await scopeService.effectiveWorktree("child")).toBe("/wt");
    expect(await configured[0]?.("child")).toEqual({
      sessionId: "child",
      workspaceRoot: "/wt",
    });
  });
});

describe("bindingOrigin 的三态与来源读取面", () => {
  it("rootOf 把三态翻成根：none 回 null，own / inherited 回登记里的根", () => {
    expect(rootOf({ kind: "none" })).toBeNull();
    expect(rootOf({ kind: "own", record })).toBe("/wt");
    expect(rootOf({ kind: "inherited", record, ownerSessionId: "parent" })).toBe("/wt");
  });

  it("本会话自己的登记 → own，record 就是表里那一条", async () => {
    const { deps } = scopeDeps({ binding: { s1: record }, exists: true, belongs: true });
    expect(await bindingOrigin(deps, "s1")).toEqual({ kind: "own", record });
  });

  it("只有父链上有登记 → inherited，并报出持有它的那个会话", async () => {
    const { deps } = scopeDeps({
      binding: { parent: record },
      parents: { child: "parent" },
      exists: true,
      belongs: true,
    });
    expect(await bindingOrigin(deps, "child")).toEqual({
      kind: "inherited",
      record,
      ownerSessionId: "parent",
    });
  });

  it("哪都没有 → none（不是「继承了一个 null」）", async () => {
    const { deps } = scopeDeps();
    expect(await bindingOrigin(deps, "s1")).toEqual({ kind: "none" });
  });

  it("双跳链：ownerSessionId 是最近一个**持有登记**的祖先，不是直接父", async () => {
    const { deps } = scopeDeps({
      binding: { grand: record },
      parents: { child: "parent", parent: "grand" },
      exists: true,
      belongs: true,
    });
    const origin = await bindingOrigin(deps, "child");
    expect(origin).toEqual({ kind: "inherited", record, ownerSessionId: "grand" });
  });

  it("用户 fork 的形态（有 parentSession、无 delegationDepth）与子 agent 走同一条判据", async () => {
    // fork 的 header 里本域能看到的事实只有 parentSession（端口里没有 delegationDepth / origin），
    // 所以「有父链」就是继承——维护者裁决「保留 fork 继承」在代码里就是这个样子。
    // 形态取自真机会话链：0d295ac4 ← f20ff925 ← fe0d5336，三条都是 isSeeded 的 fork。
    const { deps } = scopeDeps({
      binding: { "session-0d295ac4": record },
      parents: { "session-fe0d5336": "session-f20ff925", "session-f20ff925": "session-0d295ac4" },
      exists: true,
      belongs: true,
    });
    expect(await effectiveWorktree(deps, "session-fe0d5336")).toBe("/wt");
    expect(await bindingOrigin(deps, "session-fe0d5336")).toEqual({
      kind: "inherited",
      record,
      ownerSessionId: "session-0d295ac4",
    });
  });

  it("父记录失效时先摘掉它，再继续向上命中祖父（自愈不截断父链）", async () => {
    const grand: BindingRecord = { ...record, worktreeRoot: "/wt-grand" };
    const { deps, dropped, table } = scopeDeps({
      binding: { parent: record, grand },
      parents: { child: "parent", parent: "grand" },
      belongs: true,
    });
    // 只有父那条登记的目录没了；祖父那条仍然有效（harness 的 exists 是全局的，故这里按路径覆盖）。
    const scoped: ScopeDeps = { ...deps, existsDirectory: (path) => path !== record.worktreeRoot };
    expect(await bindingOrigin(scoped, "child")).toEqual({
      kind: "inherited",
      record: grand,
      ownerSessionId: "grand",
    });
    expect(dropped).toEqual(["parent"]);
    expect(table.has("parent")).toBe(false);
  });

  it("takeover 门是刻意分叉的：provider 缺席（waiting）时生效根回 null，登记事实照旧可读", async () => {
    const { deps } = scopeDeps({ binding: { s1: record }, exists: true, belongs: true });
    installScope(deps);
    expect(scopeService.takeoverState()).toBe("waiting");
    // 浏览器面（生效根）按官方语义走；工具面（登记事实）必须仍能读到自己的登记，
    // 否则接管冲突时连一条登记都清理不掉。
    expect(await scopeService.effectiveWorktree("s1")).toBeNull();
    expect(await worktreeOrigin("s1")).toEqual({ kind: "own", record });
  });
});

describe("resolveScope 的委托与永不抛出", () => {
  it("命中绑定时不调用委托", async () => {
    const { deps } = scopeDeps({ binding: { s1: record }, exists: true, belongs: true });
    let called = 0;
    const result = await resolveScope(
      deps,
      async () => {
        called += 1;
        return undefined;
      },
      "s1",
    );
    expect(result).toEqual({ sessionId: "s1", workspaceRoot: "/wt" });
    expect(called).toBe(0);
  });

  it("未命中时委托官方语义", async () => {
    const { deps } = scopeDeps();
    const result = await resolveScope(
      deps,
      async (id) => ({ sessionId: id, workspaceRoot: "/cwd" }),
      "s1",
    );
    expect(result).toEqual({ sessionId: "s1", workspaceRoot: "/cwd" });
  });

  it("取绑定抛异常时回落委托，且异常不外泄", async () => {
    const { deps } = scopeDeps();
    const throwing: ScopeDeps = {
      ...deps,
      binding: {
        get: () => {
          throw new Error("boom");
        },
        drop: deps.binding.drop,
      },
    };
    const result = await resolveScope(
      throwing,
      async (id) => ({ sessionId: id, workspaceRoot: "/cwd" }),
      "s1",
    );
    expect(result).toEqual({ sessionId: "s1", workspaceRoot: "/cwd" });
    expect(warns.some((w) => w.includes("解析文件根失败"))).toBe(true);
  });

  it("存在性判定本身抛异常时也回落委托（不是硬失败）", async () => {
    const { deps } = scopeDeps({ binding: { s1: record } });
    const throwing: ScopeDeps = {
      ...deps,
      existsDirectory: () => {
        throw new Error("stat exploded");
      },
    };
    const result = await resolveScope(
      throwing,
      async (id) => ({ sessionId: id, workspaceRoot: "/cwd" }),
      "s1",
    );
    expect(result).toEqual({ sessionId: "s1", workspaceRoot: "/cwd" });
    expect(warns.some((w) => w.includes("解析文件根失败"))).toBe(true);
  });

  it("委托自己也抛错时返回 undefined，不把异常抛给 gateway", async () => {
    const { deps } = scopeDeps();
    const result = await resolveScope(
      deps,
      async () => {
        throw new Error("delegate exploded");
      },
      "s1",
    );
    expect(result).toBeUndefined();
    expect(warns.some((w) => w.includes("官方默认解析失败"))).toBe(true);
  });
});

describe("installScope 的接管资格", () => {
  const official: LookupDescriptorPort = {
    resolve: async (id) => ({ sessionId: id, workspaceRoot: "/official" }),
  };

  it("provider 已注册时**捕获官方 resolve** 并委托（不是委托我们自己的包装）", async () => {
    const { deps, configured } = scopeDeps({ descriptor: official });
    installScope(deps);
    expect(scopeService.takeoverState()).toBe("live");
    expect(takeoverState()).toBe("live");
    expect(configured.length).toBe(1);
    expect(await configured[0]?.("s1")).toEqual({ sessionId: "s1", workspaceRoot: "/official" });
  });

  it("provider 尚未注册时不接管、不 configure，只出声等它（文件根保持官方语义）", async () => {
    const { deps, configured } = scopeDeps();
    installScope(deps);
    expect(takeoverState()).toBe("waiting");
    expect(scopeService.takeoverState()).not.toBe("live");
    expect(configured.length).toBe(0);
    expect(await scopeService.effectiveWorktree("s1")).toBeNull();
    expect(warns.filter((w) => w.includes("provider 尚未注册")).length).toBe(1);
  });

  it("provider 随后出现（查找表通知）→ 当场接管", async () => {
    const { deps, configured, appear } = scopeDeps();
    installScope(deps);
    appear(official);
    expect(takeoverState()).toBe("live");
    expect(configured.length).toBe(1);
    expect(await configured[0]?.("s1")).toEqual({ sessionId: "s1", workspaceRoot: "/official" });
  });

  it("provider 恰好在订阅调用期间注册 → 订阅之后的那次重读必须看见它", () => {
    // 事件在 subscribe 调用里就发完了（订阅者还没有登记），只靠通知会永久停在等待态。
    const { deps, configured } = scopeDeps({ providerArrivesDuringSubscribe: official });
    installScope(deps);
    expect(takeoverState()).toBe("live");
    expect(configured.length).toBe(1);
  });

  it("等待期的重复通知不重复出声，接管后也不再 configure", () => {
    const { deps, configured, appear } = scopeDeps();
    installScope(deps);
    appear(official);
    appear(official);
    expect(configured.length).toBe(1);
    expect(warns.filter((w) => w.includes("provider 尚未注册")).length).toBe(1);
  });

  it("已被第三方 configure 时放弃接管并出声，且此后不再试（终态）", () => {
    const { deps, configured, appear } = scopeDeps({
      descriptor: official,
      configureThrows: true,
    });
    installScope(deps);
    expect(takeoverState()).toBe("abandoned");
    expect(scopeService.takeoverState()).not.toBe("live");
    expect(configured.length).toBe(0);
    expect(warns.some((w) => w.includes("已有解析器，放弃接管"))).toBe(true);
    // 再来通知也不再试：重试只会反复撞同一个「已被占用」。
    appear(official);
    expect(configured.length).toBe(0);
  });

  it("未接管（等待中或已放弃）时 effectiveWorktree 恒为 null（客户端因此不动文件根）", async () => {
    const waiting = scopeDeps();
    installScope(waiting.deps);
    expect(await scopeService.effectiveWorktree("s1")).toBeNull();
    releaseScope();

    const abandoned = scopeDeps({ descriptor: official, configureThrows: true });
    installScope(abandoned.deps);
    expect(await scopeService.effectiveWorktree("s1")).toBeNull();
  });

  it("接管后 effectiveWorktree 反映当前绑定（路由与解析器读同一个值）", async () => {
    const { deps } = scopeDeps({
      descriptor: official,
      binding: { s1: record },
      exists: true,
      belongs: true,
    });
    installScope(deps);
    expect(await scopeService.effectiveWorktree("s1")).toBe("/wt");
    expect(await scopeService.effectiveWorktree("other")).toBeNull();
  });

  it("release 之后官方那侧留着的闭包不再拿旧 deps 出结果（回 undefined）", async () => {
    const { deps, configured } = scopeDeps({
      descriptor: official,
      binding: { s1: record },
      exists: true,
      belongs: true,
    });
    installScope(deps);
    expect(await configured[0]?.("s1")).toEqual({ sessionId: "s1", workspaceRoot: "/wt" });
    releaseScope();
    // 闭包按调用当刻读装配入参：释放之后它只能回 undefined，让 gateway 走 lookup-not-found。
    expect(await configured[0]?.("s1")).toBeUndefined();
  });

  it("release 退订、调用 disposer（官方默认解析随之恢复），且幂等", () => {
    const { deps, isDisposed, lookups } = scopeDeps({ descriptor: official });
    installScope(deps);
    expect(lookups.listenerCount()).toBe(1);
    releaseScope();
    expect(isDisposed()).toBe(true);
    expect(lookups.listenerCount()).toBe(0);
    releaseScope();
    expect(isDisposed()).toBe(true);
  });
});

describe("二次装配守卫与 release 复位", () => {
  const official: LookupDescriptorPort = {
    resolve: async (id) => ({ sessionId: id, workspaceRoot: "/official" }),
  };

  it("第二次装配当场抛错，不静默接管两份", () => {
    const first = scopeDeps({ descriptor: official });
    installScope(first.deps);
    // 说清是哪个域拒绝的：`/只能装配一次/` 这种宽判据在「装配体被整段短路」时也会绿。
    expect(() => installScope(scopeDeps().deps)).toThrow(
      "dsh-worktree-sidebar: scope 域只能装配一次",
    );
    expect(first.configured.length).toBe(1);
  });

  it("release 交还 resolver，且再次装配必须能重新接管", () => {
    const first = scopeDeps({ descriptor: official });
    installScope(first.deps);
    expect(scopeService.takeoverState()).toBe("live");
    releaseScope();
    expect(first.isDisposed()).toBe(true);
    expect(scopeService.takeoverState()).not.toBe("live");
    expect(takeoverState()).toBe("idle");

    const second = scopeDeps({ descriptor: official });
    installScope(second.deps);
    expect(scopeService.takeoverState()).toBe("live");
    expect(second.configured.length).toBe(1);
  });

  it("「已被占用」是当次事实：上一次被占用不阻止 release 后的下一次接管", () => {
    const occupied = scopeDeps({ descriptor: official, configureThrows: true });
    installScope(occupied.deps);
    expect(scopeService.takeoverState()).not.toBe("live");
    releaseScope();
    const free = scopeDeps({ descriptor: official });
    installScope(free.deps);
    expect(scopeService.takeoverState()).toBe("live");
    expect(free.configured.length).toBe(1);
  });

  it("release 之后能力面当场失败，不拿旧 deps 出结果", async () => {
    releaseScope();
    await expect(scopeService.effectiveWorktree("s1")).rejects.toThrow(
      "dsh-worktree-sidebar: scope 域尚未装配",
    );
  });
});

/**
 * 装配根（src/client/index.ts）—— 契约层用例：递手写假 ctx 驱动 `apply`。
 *
 * 这是契约层而不是 unit 的同域白盒面：装配根的依赖面就是宿主给的 `ctx`，
 * 不递假面就无法驱动它。
 *
 * 静态 import 本身就是一条判据：非 bundle 环境里没有构建期注入的 `__DSH_ROUTES__`，
 * 装配根靠 `typeof` 守卫回落到 `src/shared/contract.ts` 的 `ROUTES`，模块求值得当场成功。
 * 先往 globalThis 挂一个桩再 import，会把这条判据遮掉。
 *
 * 为什么允许打桩 `globalThis.fetch`：读宿主绑定的唯一出口就是它，不桩会真的发出网络请求
 * （离线纪律）。这里只用它当调用计数器与响应源，不伪造别的进程事实。
 *
 * 时间纪律：客户端**没有定时器**（请求只由页签挂载 / 官方刷新 / 窗口重新可见触发），
 * 所以本文件不假时间；异步等待一律用 `settleMicrotasks` 排空队列，不写真实 sleep。
 */
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it } from "vitest";
import { apply } from "../../src/client/index.ts";
import type {
  ObservablePort,
  SessionsSnapshotLike,
  TabDefinitionLike,
  TabsPort,
} from "../../src/client/shared/ports.ts";
import { createFakeSlots } from "../helpers.ts";
import { BODY_SLOT, FILES_KIND } from "../../src/client/takeover.ts";

const OFFICIAL_ID = "@deepseek-ai/dsh-client-ui-sidebar-files/files";
const SESSION_ID = "s1";
const TAB_ID = "tab-1";
/** 官方正文递进来的 cwd：绑定不可用时的回退根。 */
const CWD = "/cwd";

/** 官方正文每次被播种 / 列目录都记一笔：这是断言「播的是哪个根」的唯一证据面。 */
const officialStarts: Array<{ tabId: string; root: string }> = [];
const officialLoads: Array<{ tabId: string; path: string }> = [];

/** 官方正文条目的两个承载面：组件与 inject 工厂（登记进假座位表，装配根从原始账里找它）。 */
const OFFICIAL_BODY = {
  component: { name: "FilesBody" },
  inject: () => ({
    useFiles: "official-useFiles",
    start: (tabId: string, root: string) => {
      officialStarts.push({ tabId, root });
    },
    load: (tabId: string, path: string) => {
      officialLoads.push({ tabId, path });
    },
    toggle: () => undefined,
  }),
};

const OFFICIAL_DEFINITION: TabDefinitionLike = {
  id: OFFICIAL_ID,
  kind: FILES_KIND,
  priority: "builtin",
  title: () => "Files",
};

/** 排空在飞的微任务链：`start` 之后还有一次异步的绑定读取与纠正播种。 */
function settleMicrotasks(): Promise<void> {
  return new Promise((resolve) => setImmediate(resolve));
}

/** 官方 root（官方正文递进来的 cwd）那一次播种：改用例时读起来比裸 CWD 常量清楚。 */
const OFFICIAL_SEED = { tabId: TAB_ID, root: CWD };

/** 一个会话在册的快照。 */
function liveSnapshot(): SessionsSnapshotLike {
  return { byId: { [SESSION_ID]: { title: "t" } } };
}

/** 我们注册的那条正文的 inject 面（已包装）。 */
interface Face {
  start?: (tabId: string, root: string, signal?: AbortSignal) => void;
  load?: (tabId: string, path: string, signal?: AbortSignal) => void;
  [key: string]: unknown;
}

interface Mounted {
  /** 假 sessions.list 当前返回的真实快照。 */
  readonly snapshot: { value: SessionsSnapshotLike };
  /** 装配时注册正文传进去的那份 inject（我们的包装产物）。 */
  capturedInject(): (...args: unknown[]) => Record<string, unknown>;
  /** 该会话累计发起的绑定拉取次数。 */
  fetchesFor(sessionId: string): number;
  /** 官方 `start` 收到的每次播种。 */
  starts(): ReadonlyArray<{ tabId: string; root: string }>;
  /** 官方 `load` 收到的每次列目录。 */
  loads(): ReadonlyArray<{ tabId: string; path: string }>;
  /** 调 ctx.effect 收下的 disposer（整包卸载）。 */
  dispose(): void;
}

let active: Mounted | undefined;
const savedFetch = globalThis.fetch;

afterEach(() => {
  active?.dispose();
  active = undefined;
  globalThis.fetch = savedFetch;
});

/**
 * 装一次假 ctx 并调 apply。
 *
 * 假面必须复刻装配根真正用到的形状：`sessions` 服务对象本身**没有** `getSnapshot`，
 * 快照在 `sessions.list` 上——这正是本文件要钉住的那条接缝。
 */
function mount(respond: () => Response | Promise<Response>): Mounted {
  const snapshot: { value: SessionsSnapshotLike } = { value: liveSnapshot() };
  const fetchUrls: string[] = [];
  const disposers: Array<() => void> = [];
  officialStarts.length = 0;
  officialLoads.length = 0;

  // 假座位表复刻官方语义（优先级最低者当值）：没有它，「我们的条目是否当值」这条
  // 自检会判否，装配根会当场退位——用例就会在一条并不存在的失败上变绿。
  const fake = createFakeSlots();
  fake.slots.register(
    { name: BODY_SLOT, key: OFFICIAL_ID, inject: OFFICIAL_BODY.inject },
    OFFICIAL_BODY.component,
  );
  const sidebarRightTabs: TabsPort = {
    get: (kind) => (kind === FILES_KIND ? OFFICIAL_DEFINITION : undefined),
  };

  globalThis.fetch = async (input) => {
    fetchUrls.push(String(input));
    return respond();
  };

  apply({
    slots: fake.slots,
    sidebarRightTabs,
    sessions: {
      list: {
        getSnapshot: () => snapshot.value,
        subscribe: () => () => undefined,
      },
    },
    effect: (execute) => {
      disposers.push(execute());
      return () => undefined;
    },
  });

  const mounted: Mounted = {
    snapshot,
    // 我们那条正文的 inject：认自己不能靠一个常量（priority 是按官方那条算出来的），
    // 但官方那条在夹具里**没有声明 priority**，所以「有 priority 的那条」就是我们。
    capturedInject: () => {
      const entry = fake
        .entries(BODY_SLOT)
        .find((candidate) => candidate.options.priority !== undefined);
      if (entry?.inject === undefined) throw new Error("我们那条正文没有登记上");
      return entry.inject;
    },
    fetchesFor: (sessionId) =>
      fetchUrls.filter((url) => url.endsWith("?session=" + sessionId)).length,
    starts: () => officialStarts.slice(),
    loads: () => officialLoads.slice(),
    dispose: () => {
      for (const dispose of disposers) dispose();
    },
  };
  active = mounted;
  return mounted;
}

/** 一次成功的绑定读取。 */
function bindingResponse(): Response {
  return new Response(JSON.stringify({ revision: 1, worktreePath: "/wt" }), { status: 200 });
}

describe("entry 注入面的 sessions 接在真快照源上（A2）", () => {
  it("hooks.sessions.getSnapshot() 回的是宿主快照", () => {
    const h = mount(() => new Response(null, { status: 404 }));
    const face = h.capturedInject()(SESSION_ID);
    const sessions = (face["hooks"] as { sessions: { getSnapshot(): SessionsSnapshotLike } })
      .sessions;
    // 只断「hooks.sessions 存在」是恒真断言：接错面（换成 ctx.sessions）时构造期不抛、
    // typeof 也仍是 function，只有真的调用一次才会 TypeError。
    expect(sessions.getSnapshot()).toBe(h.snapshot.value);
  });
});

/**
 * 树根播种。这是**换根真正生效**的地方：官方只在 `state === undefined` 时播一次种
 * （sidebar-files/lib/client.js:426-428），刷新按钮也只重列已展开的路径（同文件 :455-458），
 * 所以"绑定后树根自动正确"必须由我们覆盖 `start`/`load` 来保证。
 */
describe("树根播种：只在用户可感知的时机读绑定（没有定时轮询）", () => {
  it("没有页签挂载时一个请求都不发", () => {
    const h = mount(bindingResponse);
    h.capturedInject()(SESSION_ID);
    expect(h.fetchesFor(SESSION_ID)).toBe(0);
  });

  it("打开页签：先按官方 cwd 播种，绑定到达后再纠正到生效根（首帧不空白）", async () => {
    const h = mount(bindingResponse);
    const face = h.capturedInject()(SESSION_ID) as Face;
    face.start?.(TAB_ID, CWD);
    await settleMicrotasks();

    expect(h.fetchesFor(SESSION_ID)).toBe(1);
    expect(h.starts()).toEqual([OFFICIAL_SEED, { tabId: TAB_ID, root: "/wt" }]);
  });

  it("查询参数完整编码会话标识，并声明 JSON 响应类型", async () => {
    const requests: Array<{ url: string; accept: string | null }> = [];
    const h = mount(bindingResponse);
    globalThis.fetch = async (input, init) => {
      requests.push({ url: String(input), accept: new Headers(init?.headers).get("accept") });
      return bindingResponse();
    };
    const face = h.capturedInject()("会话 /?&=+#") as Face;
    face.start?.(TAB_ID, CWD);
    await settleMicrotasks();
    expect(requests).toEqual([
      {
        url: "/api/dsh-worktree-sidebar/bindings?session=%E4%BC%9A%E8%AF%9D%20%2F%3F%26%3D%2B%23",
        accept: "application/json",
      },
    ]);
  });

  it.each([
    [
      "invalid revision",
      () => new Response(JSON.stringify({ revision: "2", worktreePath: "/other" })),
    ],
    ["invalid JSON", () => new Response("not-json")],
    ["network rejection", () => Promise.reject(new Error("offline"))],
  ])("%s 保留上次已确认的根", async (_name, failure) => {
    let calls = 0;
    const h = mount(() => (++calls === 1 ? bindingResponse() : failure()));
    const face = h.capturedInject()(SESSION_ID) as Face;
    face.start?.(TAB_ID, CWD);
    await settleMicrotasks();
    expect(h.starts()).toEqual([OFFICIAL_SEED, { tabId: TAB_ID, root: "/wt" }]);
    face.load?.(TAB_ID, "/wt");
    await settleMicrotasks();
    expect(h.starts()).toEqual([OFFICIAL_SEED, { tabId: TAB_ID, root: "/wt" }]);
  });

  it("绑定查询永不返回时，官方那一帧照播（树不会一直空白）", async () => {
    // 端点慢/挂起时，官方正文的 state 会停在 undefined 并渲染 null；把首帧挂在这次 fetch 上，
    // 等于让**所有会话**（含从未登记的）的 Files 树一起空白。所以必须先播官方 root。
    const h = mount(() => new Promise<Response>(() => undefined));
    const face = h.capturedInject()(SESSION_ID) as Face;
    face.start?.(TAB_ID, CWD);
    await settleMicrotasks();

    expect(h.starts()).toEqual([OFFICIAL_SEED]);
  });

  it("拉取失败保持上次成功态：HTTP 失败不等于「没有绑定」", async () => {
    let status = 200;
    const h = mount(() =>
      status === 200 ? bindingResponse() : new Response(null, { status: 500 }),
    );
    const face = h.capturedInject()(SESSION_ID) as Face;
    face.start?.(TAB_ID, CWD);
    await settleMicrotasks();
    expect(h.starts()).toEqual([OFFICIAL_SEED, { tabId: TAB_ID, root: "/wt" }]);

    status = 500;
    face.load?.(TAB_ID, "/wt");
    await settleMicrotasks();

    // 失败被当成「未绑定」的话，这里会多出一次回退到 cwd 的播种——那正是「看错地方」。
    expect(h.starts()).toEqual([OFFICIAL_SEED, { tabId: TAB_ID, root: "/wt" }]);
  });

  it("乱序返回：更早发出的请求带着更小 revision 后到时不回退快照", async () => {
    const gates: Array<(response: Response) => void> = [];
    const h = mount(() => new Promise<Response>((resolve) => gates.push(resolve)));
    const face = h.capturedInject()(SESSION_ID) as Face;

    face.start?.(TAB_ID, CWD); // 请求 1
    await settleMicrotasks();
    face.load?.(TAB_ID, CWD); // 请求 2（官方刷新那一跳）
    await settleMicrotasks();
    expect(gates.length).toBe(2);

    // 新的先回（revision 2 /new）→ 播种 /new
    gates[1]?.(
      new Response(JSON.stringify({ revision: 2, worktreePath: "/new" }), { status: 200 }),
    );
    await settleMicrotasks();
    expect(h.starts()).toEqual([OFFICIAL_SEED, { tabId: TAB_ID, root: "/new" }]);

    // 旧的后回（revision 1 /old）→ 必须被丢掉，否则快照与树根一起回退
    gates[0]?.(
      new Response(JSON.stringify({ revision: 1, worktreePath: "/old" }), { status: 200 }),
    );
    await settleMicrotasks();
    expect(h.starts()).toEqual([OFFICIAL_SEED, { tabId: TAB_ID, root: "/new" }]);
  });

  it("点刷新（load 命中已播种的根）会重读绑定；worktree 变了就用官方 start 重根", async () => {
    let body: Record<string, unknown> = { revision: 1, worktreePath: "/wt" };
    const h = mount(() => new Response(JSON.stringify(body), { status: 200 }));
    const face = h.capturedInject()(SESSION_ID) as Face;
    face.start?.(TAB_ID, CWD);
    await settleMicrotasks();
    expect(h.starts()).toEqual([OFFICIAL_SEED, { tabId: TAB_ID, root: "/wt" }]);

    body = { revision: 2, worktreePath: "/wt2" };
    face.load?.(TAB_ID, "/wt");
    await settleMicrotasks();

    expect(h.starts()).toEqual([
      OFFICIAL_SEED,
      { tabId: TAB_ID, root: "/wt" },
      { tabId: TAB_ID, root: "/wt2" },
    ]);
    // 官方那次 load 仍要发生：我们只补一次重读，不吞掉官方刷新动作。
    expect(h.loads()).toEqual([{ tabId: TAB_ID, path: "/wt" }]);
  });

  it("绑定变了但生效根没变：不重播官方 start（官方每次 start 都会再加一个 abort 监听）", async () => {
    let body: Record<string, unknown> = { revision: 1, worktreePath: "/wt" };
    const h = mount(() => new Response(JSON.stringify(body), { status: 200 }));
    const face = h.capturedInject()(SESSION_ID) as Face;
    face.start?.(TAB_ID, CWD);
    await settleMicrotasks();

    // revision 涨了、路径没变：状态会通知，但根没变，因此不该再调一次官方 start。
    body = { revision: 2, worktreePath: "/wt" };
    face.load?.(TAB_ID, "/wt");
    await settleMicrotasks();

    expect(h.starts()).toEqual([OFFICIAL_SEED, { tabId: TAB_ID, root: "/wt" }]);
  });

  it("绑定被摘掉（worktreePath: null）时回退到官方递进来的 cwd", async () => {
    let body: Record<string, unknown> = { revision: 1, worktreePath: "/wt" };
    const h = mount(() => new Response(JSON.stringify(body), { status: 200 }));
    const face = h.capturedInject()(SESSION_ID) as Face;
    face.start?.(TAB_ID, CWD);
    await settleMicrotasks();

    body = { revision: 2, worktreePath: null };
    face.load?.(TAB_ID, "/wt");
    await settleMicrotasks();

    expect(h.starts()).toEqual([
      OFFICIAL_SEED,
      { tabId: TAB_ID, root: "/wt" },
      { tabId: TAB_ID, root: CWD },
    ]);
  });

  it("信号在 start 之前就已 abort：不再为它重播（reseed 的 aborted 跳过）", async () => {
    let body: Record<string, unknown> = { revision: 1, worktreePath: "/wt" };
    const h = mount(() => new Response(JSON.stringify(body), { status: 200 }));
    const face = h.capturedInject()(SESSION_ID) as Face;
    const controller = new AbortController();
    controller.abort();
    face.start?.(TAB_ID, CWD, controller.signal);
    await settleMicrotasks();
    const before = h.starts().length;
    // 刷新那一跳认的是「最近播种进去的根」：用实际播过的根去触发，免得判据依赖某个固定字符串。
    const seeded = h.starts().at(-1)?.root ?? CWD;

    // 已经 abort 的信号不会再触发 abort 事件，页签因此留在 watched 里；
    // 重播时的 aborted 判断就是它不把树重设到一个已经关掉的页签上的唯一闸门。
    body = { revision: 2, worktreePath: "/wt2" };
    face.load?.(TAB_ID, seeded, controller.signal);
    await settleMicrotasks();

    expect(h.starts().length).toBe(before);
  });

  it("没有 signal 的播种面在整包卸载时被收口：卸载后绑定变化不再重播", async () => {
    // 官方界面包现在总是把页签 signal 传进来，但那是它的实现细节：没有 signal 时
    // 「最后一个页签 abort」永远不会发生，watched 与两条订阅会一直挂在单例座位注册表上。
    let body: Record<string, unknown> = { revision: 1, worktreePath: "/wt" };
    const h = mount(() => new Response(JSON.stringify(body), { status: 200 }));
    const face = h.capturedInject()(SESSION_ID) as Face;
    face.start?.(TAB_ID, CWD);
    await settleMicrotasks();
    const before = h.starts().length;

    h.dispose();
    body = { revision: 2, worktreePath: "/wt2" };
    face.load?.(TAB_ID, "/wt");
    await settleMicrotasks();

    expect(h.starts().length).toBe(before);
  });

  it("卸载时仍在等待的绑定响应到达后，不再调用官方 start", async () => {
    let resolveBinding!: (response: Response) => void;
    const pending = new Promise<Response>((resolve) => {
      resolveBinding = resolve;
    });
    const h = mount(() => pending);
    const face = h.capturedInject()(SESSION_ID) as Face;
    face.start?.(TAB_ID, CWD);
    expect(h.starts()).toEqual([OFFICIAL_SEED]);

    h.dispose();
    resolveBinding(bindingResponse());
    await settleMicrotasks();

    expect(h.starts()).toEqual([OFFICIAL_SEED]);
  });

  it("视图缓存有上限：最冷的会话被淘汰，仍然在缓存的会话引用稳定", () => {
    const h = mount(bindingResponse);
    const inject = h.capturedInject();
    const sourceOf = (sessionId: string): ObservablePort<SessionsSnapshotLike> =>
      (inject(sessionId)["hooks"] as { sessions: ObservablePort<SessionsSnapshotLike> }).sessions;

    const cold = sourceOf("s-cold");
    for (let i = 0; i < 200; i += 1) sourceOf("s-" + i);

    // 被挤出缓存之后重建：同一个 id 拿到的是另一套状态（它自己仍会读同一份宿主事实）。
    expect(sourceOf("s-cold")).not.toBe(cold);
    // 缓存内的会话仍然恒回同一对象（渲染层按源缓存订阅，换了对象会被当成状态一直在变）。
    const hot = sourceOf("s-hot");
    expect(sourceOf("s-hot")).toBe(hot);
  });

  it("展开子目录（load 更深路径）不触发请求，但官方 load 照旧", async () => {
    const h = mount(bindingResponse);
    const face = h.capturedInject()(SESSION_ID) as Face;
    face.start?.(TAB_ID, CWD);
    await settleMicrotasks();
    const before = h.fetchesFor(SESSION_ID);

    face.load?.(TAB_ID, "/wt/sub");
    await settleMicrotasks();

    expect(h.fetchesFor(SESSION_ID)).toBe(before);
    expect(h.loads()).toEqual([{ tabId: TAB_ID, path: "/wt/sub" }]);
  });

  it("页签关闭（abort）后不再为它重读绑定", async () => {
    const h = mount(bindingResponse);
    const face = h.capturedInject()(SESSION_ID) as Face;
    const controller = new AbortController();
    face.start?.(TAB_ID, CWD, controller.signal);
    await settleMicrotasks();
    const before = h.fetchesFor(SESSION_ID);

    controller.abort();
    face.load?.(TAB_ID, "/wt", controller.signal);
    await settleMicrotasks();

    expect(h.fetchesFor(SESSION_ID)).toBe(before);
  });
});

/**
 * 路由字面量哨兵：客户端只认 `src/shared/contract.ts` 的 `ROUTES`（构建期由 bundle-host 注入
 * `__DSH_ROUTES__`）。客户端里任何一处手写 `/api/...` 都会在宿主改路由时静默漂移，
 * 而两端各自的单测都不会红——所以这条扫源码文本，守的是真实的双端 ABI，不是代码风格。
 */
describe("路由单一事实源：客户端没有硬编码路由字面量", () => {
  it("src/client/** 里 /api/ 出现次数为 0", () => {
    const dir = fileURLToPath(new URL("../../src/client", import.meta.url));
    const names = readdirSync(dir, { recursive: true, encoding: "utf8" }).filter((name) =>
      name.endsWith(".ts"),
    );
    // 非空锚：扫描面真的走到了客户端目录（否则下一条断言会因为「一个文件都没扫」而恒真）。
    expect(names).toContain("index.ts");
    const withLiterals = names.filter((name) =>
      readFileSync(join(dir, name), "utf8").includes("/api/"),
    );
    expect(withLiterals).toEqual([]);
  });
});

/**
 * 接管 files 页签 —— 用**复刻官方语义**的假座位表驱动（`createFakeSlots`，见 test/helpers.ts）。
 *
 * 为什么先写负向用例：接管的失败形态是「右栏坏了」，而它比「右栏没变」严重得多。
 * 所以这里的第一条判据不是「接管成功了吗」，而是「抓不到官方正文时，我们**一个注册都没有**」。
 *
 * 本文件钉的是**遮蔽语义**：以官方 id 为 key、更低 priority 再登记一条，官方那条原样留在账上。
 * 判据因此不能是「我们调了 register 没有」，必须是「座位上当值的是哪一条」——那正是渲染层读的东西
 * （官方 `renderer/lib/client.js:827`：`entriesOfSlot(slot).find(e => e.options.key === entryKey)`）。
 */
import { describe, expect, it } from "vitest";
import { createFakeSlots } from "../helpers.ts";
import { createInjectWrapper } from "../../src/client/inject.ts";
import type {
  ClientSlotsPort,
  InjectFactory,
  ObservablePort,
  SessionView,
  SessionsSnapshotLike,
  StoredEntryLike,
  TabDefinitionLike,
  TabsPort,
} from "../../src/client/shared/ports.ts";
import {
  BODY_SLOT,
  FILES_KIND,
  installTakeover,
  shadowPriorityOf,
} from "../../src/client/takeover.ts";

const OFFICIAL_ID = "@deepseek-ai/dsh-client-ui-sidebar-files/files";
/** 官方标题座位的 key（我们不再往这里登记任何东西）。 */
const TITLE_SLOT = "sidebar.right.pane.tab.title";
const LOCALE = "sidebarFiles";
const STORE = { kind: "store" };
const FILES_BODY = { name: "FilesBody" };
const FILES_TITLE = { name: "FilesTitle" };
const GUIDE = [{ order: 10, title: () => "Workspace files" }];
const OFFICIAL_DEFINITION: TabDefinitionLike = {
  id: OFFICIAL_ID,
  kind: FILES_KIND,
  priority: "builtin",
  title: () => "Files",
  guide: GUIDE,
};

/** 改写源的假件：本文件的注册/释放用例不经过 inject，递一个引用稳定的空源即可。 */
const STABLE_SOURCE: ObservablePort<SessionsSnapshotLike> = {
  getSnapshot: () => ({}),
  subscribe: () => () => undefined,
};

/** 一个会话视图的假件：本文件只走注册/释放与 inject 面包装，生效根读数不承载判据。 */
function viewOf(source: ObservablePort<SessionsSnapshotLike>): SessionView {
  return {
    source,
    root: {
      getSnapshot: () => null,
      subscribe: () => () => undefined,
      refresh: () => Promise.resolve(),
    },
  };
}

/** 排空微任务：官方登记/撤销的变更通知是微任务批处理的，我们自己那次通知也会走到 evaluate。 */
function settle(): Promise<void> {
  return new Promise((resolve) => setImmediate(resolve));
}

function harness(
  options: {
    /** 我们那条正文的登记永久失败。 */
    bodyFails?: boolean;
    /** 我们那条正文的登记失败前 N 次（用来演「瞬时失败 → 下一次通知重试成功」）。 */
    bodyFailsTimes?: number;
    /** 官方那条自己声明的 priority；缺省即「没声明」（按 0 算）。 */
    officialPriority?: number;
  } = {},
) {
  const warns: string[] = [];
  const fake = createFakeSlots();
  const officialInject = (): Record<string, unknown> => ({
    useFiles: "official-useFiles",
    hooks: { other: "keep-me" },
  });
  const registerOfficial = (component: unknown): (() => void) =>
    fake.slots.register(
      {
        name: BODY_SLOT,
        key: OFFICIAL_ID,
        locale: LOCALE,
        store: STORE,
        inject: officialInject,
        ...(options.officialPriority === undefined ? {} : { priority: options.officialPriority }),
      },
      component,
    );
  let officialEntry: StoredEntryLike | undefined;
  let disposeOfficial = registerOfficial(FILES_BODY);
  officialEntry = fake.entries(BODY_SLOT)[0];
  fake.slots.register({ name: TITLE_SLOT, key: OFFICIAL_ID }, FILES_TITLE);

  /**
   * 类型注册表的假件：**运行时真有 `register`**（官方那份 API 就挂在 `ctx.sidebarRightTabs` 上），
   * 只是我们的端口不声明它。所以这里用 `Object.assign` 挂上去而不是写进对象字面量——
   * 复刻「能力在、但我们看不见」这个真实形态，也让「类型表一个字节没动」那条判据不是恒真。
   */
  let officialType: TabDefinitionLike | undefined = OFFICIAL_DEFINITION;
  const tabs: TabsPort = Object.assign(
    { get: (kind: string) => (kind === FILES_KIND ? officialType : undefined) },
    {
      register: (definition: TabDefinitionLike) => {
        const previous = officialType;
        officialType = definition;
        return () => {
          if (officialType === definition) officialType = previous;
        };
      },
    },
  );

  /**
   * 正文登记失败：只对我们那条抛。认自己不看具体数值——priority 是按官方那条算出来的，
   * 而官方那条在夹具里默认**不声明** priority，所以「带 priority 的登记」就是我们。
   */
  /** 我们那条条目的 identity：wrapper 产出的 inject 工厂是我们唯一能精确认出的东西。 */
  const ourInjectFactories = new Set<InjectFactory>();
  const attempts = { count: 0 };
  const failsOurs = (): boolean => {
    attempts.count += 1;
    if (options.bodyFails === true) return true;
    return options.bodyFailsTimes !== undefined && attempts.count <= options.bodyFailsTimes;
  };
  const needsFailingRegister = options.bodyFails === true || options.bodyFailsTimes !== undefined;
  const slots: ClientSlotsPort = needsFailingRegister
    ? {
        ...fake.slots,
        register: (regOptions, component) => {
          if (regOptions["priority"] !== undefined && failsOurs()) {
            throw new Error("body register exploded");
          }
          return fake.slots.register(regOptions, component);
        },
      }
    : fake.slots;

  /** 我们那条条目：`inject` 是我们这个 wrapper 的产物（官方那条的 inject 是它自己的工厂）。 */
  const isOurs = (entry: StoredEntryLike): boolean =>
    entry.inject !== undefined && ourInjectFactories.has(entry.inject);

  const ours = (): readonly StoredEntryLike[] =>
    fake.entries(BODY_SLOT).filter((entry) => isOurs(entry));

  return {
    fake,
    tabs,
    warns,
    ours,
    /** 我们那条正文；不在就当场判红（省得断言里到处写可选链）。 */
    mustOurs: (): StoredEntryLike => {
      const entry = ours()[0];
      if (entry === undefined) throw new Error("我们那条正文不在座位上");
      return entry;
    },
    /** 官方那条正文：登记时当场记下的那个对象（HMR 重登记会换成新对象）。 */
    official: (): StoredEntryLike | undefined => officialEntry,
    setOfficialType: (definition: TabDefinitionLike | undefined) => {
      officialType = definition;
    },
    /** 官方包 HMR：旧登记退场、同 key 重新登记一条新组件。 */
    reRegisterOfficial: (component: unknown) => {
      disposeOfficial();
      disposeOfficial = registerOfficial(component);
      officialEntry = fake
        .entries(BODY_SLOT)
        .find((entry) => entry.options.key === OFFICIAL_ID && !isOurs(entry));
    },
    dropOfficial: () => disposeOfficial(),
    install: () =>
      installTakeover({
        slots,
        tabs,
        logger: { warn: (message: string) => warns.push(message) },
        wrapInject: (official) => {
          const wrapped = createInjectWrapper(() => viewOf(STABLE_SOURCE))(official);
          ourInjectFactories.add(wrapped);
          return wrapped;
        },
      }),
  };
}

describe("抓不到官方正文时零注册", () => {
  it("座位里没有官方条目 → 一个注册都没有", () => {
    const h = harness();
    h.dropOfficial();
    h.install();
    expect(h.ours()).toHaveLength(0);
  });

  it("类型注册表里没有 files 类型 → 一个注册都没有", () => {
    const h = harness();
    h.setOfficialType(undefined);
    h.install();
    expect(h.ours()).toHaveLength(0);
  });

  it("官方那条已退场（abdicated）→ 不接管一个已退场的座位", () => {
    const h = harness();
    const official = h.official();
    if (official === undefined) throw new Error("官方条目不在");
    h.fake.abdicate(official);
    h.install();
    expect(h.ours()).toHaveLength(0);
  });

  it("正文登记失败 → 零注册、出声，且官方那条仍当值（不是空 cell）", () => {
    const h = harness({ bodyFails: true });
    h.install();
    expect(h.ours()).toHaveLength(0);
    expect(h.warns.some((w) => w.includes("接管 files 页签正文失败"))).toBe(true);
    expect(h.fake.winner(BODY_SLOT)).toBe(h.official());
  });
});

describe("瞬时失败与永久失败分道", () => {
  it("登记瞬时失败：下一次座位通知重试并接管成功", async () => {
    // 一次瞬时失败就永久放弃，会让接管静默失效，而恢复条件只剩官方包 HMR。
    const h = harness({ bodyFailsTimes: 1 });
    h.install();
    expect(h.ours()).toHaveLength(0);
    expect(h.warns).toHaveLength(1);

    h.fake.emit(BODY_SLOT);
    expect(h.ours()).toHaveLength(1);
    expect(h.fake.winner(BODY_SLOT)).toBe(h.mustOurs());
  });

  it("连续失败到上限之后不再重试（有限次：否则每次座位通知都白试一遍）", async () => {
    const h = harness({ bodyFailsTimes: 99 });
    h.install();
    h.fake.emit(BODY_SLOT);
    h.fake.emit(BODY_SLOT);
    h.fake.emit(BODY_SLOT);
    // 上限 2 次尝试：第 2 次之后该条目被判成「不再试」，后续通知不再出声也不再登记。
    expect(h.warns).toHaveLength(2);
    expect(h.ours()).toHaveLength(0);
  });
});

describe("遮蔽当值", () => {
  it("登记之后当值的是我们那条，官方那条仍在账上（不是顶掉）", () => {
    const h = harness();
    h.install();
    const official = h.official();
    if (official === undefined) throw new Error("官方条目不在");
    const winner = h.fake.winner(BODY_SLOT);
    expect(winner?.options.priority).toBe(shadowPriorityOf(official));
    expect(winner?.options.key).toBe(OFFICIAL_ID);
    expect(h.ours()).toHaveLength(1);
    expect(h.official()).toBeDefined();
  });

  it("priority 按官方那条算：官方自己声明了 priority 时我们低一档仍然当值", () => {
    // 写死常量的话，官方哪天声明了更低的 priority，我们就从遮蔽者变成被遮蔽者（自检退位）。
    const h = harness({ officialPriority: -5 });
    h.install();
    expect(h.mustOurs().options.priority).toBe(-6);
    expect(h.fake.winner(BODY_SLOT)).toBe(h.mustOurs());
  });

  it("类型表一个字节没动：接管前后是同一个定义引用（guide 也在原处）", () => {
    const h = harness();
    const restore = h.install();
    expect(h.tabs.get(FILES_KIND)).toBe(OFFICIAL_DEFINITION);
    expect((h.tabs.get(FILES_KIND) as TabDefinitionLike).guide).toBe(GUIDE);
    restore();
    expect(h.tabs.get(FILES_KIND)).toBe(OFFICIAL_DEFINITION);
  });

  it("复用官方组件、store、locale", () => {
    const h = harness();
    h.install();
    expect(h.mustOurs().component).toBe(FILES_BODY);
    expect(h.mustOurs().store).toBe(STORE);
    expect(h.mustOurs().locale).toBe(LOCALE);
  });

  it("标题座位零登记（官方标题原样渲染）", () => {
    const h = harness();
    h.install();
    expect(h.fake.entries(TITLE_SLOT)).toHaveLength(1);
  });

  it("我们自己登记引发的通知不会重复注册（官方通知是微任务批处理）", async () => {
    const h = harness();
    h.install();
    await settle();
    await settle();
    expect(h.ours()).toHaveLength(1);
  });
});

describe("当值自检：不当值就退位", () => {
  it("官方（或别的插件）登记了更低的 priority → 我们撤销自己那条并出声，且不自旋", async () => {
    const h = harness();
    h.install();
    h.fake.slots.register({ name: BODY_SLOT, key: OFFICIAL_ID, priority: -5 }, { name: "Other" });
    h.fake.emit(BODY_SLOT);
    expect(h.ours()).toHaveLength(0);
    expect(h.warns.some((w) => w.includes("接管 files 页签正文失败"))).toBe(true);
    // 退位之后座位上仍有当值项（那条更低的），不会出现空 cell。
    expect(h.fake.winner(BODY_SLOT)?.options.priority).toBe(-5);
    // 登记与撤销各自会触发一次座位通知：同一条官方条目只许试一次，否则就是永不停歇的微任务自旋。
    await settle();
    expect(h.ours()).toHaveLength(0);
    expect(h.warns).toHaveLength(1);
  });

  it("官方组件换了（HMR 重新登记）→ 重捕到新组件", () => {
    const h = harness();
    h.install();
    const newBody = { name: "NewBody" };
    h.reRegisterOfficial(newBody);
    h.fake.emit(BODY_SLOT);
    expect(h.ours()).toHaveLength(1);
    expect(h.mustOurs().component).toBe(newBody);
    expect(h.fake.winner(BODY_SLOT)).toBe(h.mustOurs());
  });

  it("官方正文消失时撤销我们的注册，但不退订（再出现能重新接管）", () => {
    const h = harness();
    h.install();
    expect(h.ours()).toHaveLength(1);
    h.dropOfficial();
    h.fake.emit(BODY_SLOT);
    expect(h.ours()).toHaveLength(0);
    h.reRegisterOfficial(FILES_BODY);
    h.fake.emit(BODY_SLOT);
    expect(h.ours()).toHaveLength(1);
  });

  it("dispose 撤销注册，且退订之后不再重评", () => {
    const h = harness();
    const restore = h.install();
    expect(h.ours()).toHaveLength(1);
    restore();
    expect(h.ours()).toHaveLength(0);
    h.reRegisterOfficial({ name: "Newer" });
    h.fake.emit(BODY_SLOT);
    expect(h.ours()).toHaveLength(0);
  });
});

describe("正文的 inject 面被包装：hooks.sessions 换成改写源", () => {
  it("调用登记进去的 inject 后 hooks.sessions 是本会话的改写源，官方面其余键原样保留", () => {
    const source = { getSnapshot: () => ({}), subscribe: () => () => undefined };
    const asked: string[] = [];
    const fake = createFakeSlots();
    fake.slots.register(
      {
        name: BODY_SLOT,
        key: OFFICIAL_ID,
        inject: () => ({ useFiles: "official-useFiles", hooks: { other: "keep-me" } }),
      },
      FILES_BODY,
    );
    installTakeover({
      slots: fake.slots,
      tabs: { get: (kind) => (kind === FILES_KIND ? OFFICIAL_DEFINITION : undefined) },
      logger: { warn: () => undefined },
      wrapInject: createInjectWrapper((sessionId) => {
        asked.push(sessionId);
        return viewOf(source);
      }),
    });
    const entry = fake.entries(BODY_SLOT).find((e) => e.options.priority !== undefined);
    const face = (entry?.inject as (sessionId: string) => Record<string, unknown>)("s1");
    expect(face["hooks"]).toEqual({ other: "keep-me", sessions: source });
    expect(face["useFiles"]).toBe("official-useFiles");
    expect(asked).toEqual(["s1"]);
  });

  it("取不到会话 id 时原样返回官方 face（不猜会话）", () => {
    const officialFace = { hooks: { other: "keep-me" } };
    const fake = createFakeSlots();
    fake.slots.register(
      { name: BODY_SLOT, key: OFFICIAL_ID, inject: () => officialFace },
      FILES_BODY,
    );
    installTakeover({
      slots: fake.slots,
      tabs: { get: () => OFFICIAL_DEFINITION },
      logger: { warn: () => undefined },
      wrapInject: createInjectWrapper(() => {
        throw new Error("不该被调用");
      }),
    });
    const entry = fake.entries(BODY_SLOT).find((e) => e.options.priority !== undefined);
    const face = (entry?.inject as (...args: unknown[]) => Record<string, unknown>)({
      notAString: true,
    });
    expect(face).toBe(officialFace);
  });
});

describe("崩溃归因", () => {
  it("只对我们自己的 entry 出声", () => {
    const h = harness();
    h.install();
    const official = h.official();
    if (official === undefined) throw new Error("官方条目不在");
    h.fake.reportError(BODY_SLOT, official, new Error("nope"));
    expect(h.warns).toHaveLength(0);
    h.fake.reportError(BODY_SLOT, h.mustOurs(), new Error("ours broke"));
    expect(h.warns.some((w) => w.includes("ours broke"))).toBe(true);
  });
});

describe("初始化失败时不留悬挂订阅", () => {
  it("evaluate 抛错时两条订阅逆序撤销后再抛（否则它们留在单例注册表上，卸载时没人收）", () => {
    const fake = createFakeSlots();
    fake.slots.register({ name: BODY_SLOT, key: OFFICIAL_ID, inject: () => ({}) }, FILES_BODY);
    let subscribed = 0;
    let unsubscribed = 0;
    const slots: ClientSlotsPort = {
      ...fake.slots,
      // evaluate 的第一步就是读原始账：让它抛，模拟座位注册表在初始化期坏掉。
      entries: () => {
        throw new Error("entries exploded");
      },
      subscribe: (key, listener) => {
        subscribed += 1;
        const off = fake.slots.subscribe(key, listener);
        return () => {
          unsubscribed += 1;
          off();
        };
      },
      onEntryError: (listener) => {
        subscribed += 1;
        const off = fake.slots.onEntryError(listener);
        return () => {
          unsubscribed += 1;
          off();
        };
      },
    };
    expect(() =>
      installTakeover({
        slots,
        tabs: { get: (kind) => (kind === FILES_KIND ? OFFICIAL_DEFINITION : undefined) },
        logger: { warn: () => undefined },
        wrapInject: createInjectWrapper(() => viewOf(STABLE_SOURCE)),
      }),
    ).toThrow("entries exploded");
    expect(subscribed).toBe(2);
    expect(unsubscribed).toBe(2);
  });
});

describe("端口形状对运行时公开面负责", () => {
  it("不依赖 slots.isLive（官方公开面没有它，真机会 TypeError）", () => {
    const h = harness();
    const restore = h.install();
    // 走到这里就说明整条路径没有访问过 isLive：假 slots 上根本没有这个方法。
    expect(h.ours()).toHaveLength(1);
    restore();
  });
});

