/**
 * api 域 —— 围栏、方法判定、查询语义与异常收口。
 *
 * 为什么逐条断言：这四条每一条失效都不会有报错，只会安静地少一道防线或回错东西——
 * 少了回环围栏，局域网里任何人能读你哪个会话指向哪个目录；少了 403 先于 405，
 * 探测者能靠状态码区分「方法不对」与「路径存在」；把 repoRoot 一起回出去，
 * 等于把主仓库位置送到浏览器。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import { afterEach, describe, expect, it } from "vitest";
import { ROUTES } from "../../src/shared/interface.ts";
import { installApi, releaseApi } from "../../src/server/api/interface.ts";

/** 捕获注册的路由，并按真实语义提供摘除器。 */
function capturingRegister() {
  const routes: WebRoute[] = [];
  return {
    routes,
    register(route: WebRoute): () => void {
      routes.push(route);
      return () => {
        const index = routes.indexOf(route);
        if (index >= 0) routes.splice(index, 1);
      };
    },
  };
}

/** 伪造请求：围栏只看 socket.remoteAddress 与 headers.host。 */
function fakeReq(overrides: Record<string, unknown> = {}): IncomingMessage {
  return {
    method: "GET",
    url: ROUTES.bindings,
    headers: { host: "127.0.0.1:3080" },
    socket: { remoteAddress: "127.0.0.1" },
    ...overrides,
  } as unknown as IncomingMessage;
}

/** 伪造响应：只记录状态码、头与 body。 */
function fakeRes() {
  const captured = { status: 0, headers: {} as Record<string, string>, body: "" };
  const res = {
    get headersSent() {
      return captured.status !== 0;
    },
    writeHead(status: number, headers: Record<string, string>) {
      captured.status = status;
      captured.headers = headers;
    },
    end(text?: string) {
      captured.body = text ?? "";
    },
  };
  return { captured, res: res as unknown as ServerResponse };
}

const warns: string[] = [];
const logger = { warn: (message: string) => warns.push(message) };

function install(
  overrides: Partial<{
    revision: () => number;
    effectiveWorktree: (id: string) => Promise<string | null>;
    takeoverState: () => "idle" | "waiting" | "live" | "abandoned";
    chainDiagnostics: () => {
      storedReads: number;
      storedFailures: number;
      lastFailure: string | undefined;
    };
  }> = {},
) {
  const reg = capturingRegister();
  // 两个事实来自两个域，故这里是两个互不搭界的窄端口（一个提供方一行）。
  const binding = { revision: overrides.revision ?? (() => 7) };
  const scope = {
    effectiveWorktree:
      overrides.effectiveWorktree ?? (async (id: string) => (id === "s1" ? "/wt" : null)),
    takeoverState: overrides.takeoverState ?? (() => "live" as const),
    chainDiagnostics:
      overrides.chainDiagnostics ??
      (() => ({ storedReads: 0, storedFailures: 0, lastFailure: undefined })),
  };
  installApi({ register: reg.register, logger, binding, scope });
  const route = (path: string): WebRoute => {
    const found = reg.routes.find((candidate) => candidate.path === path);
    if (found === undefined) throw new Error("未注册该路径：" + path);
    return found;
  };
  return { reg, route };
}

/** 调一次端点。注册的是**包装器**（含围栏与异常收口），所以这里也走包装器。 */
function jsonOf(captured: { body: string }): Record<string, unknown> {
  return JSON.parse(captured.body) as Record<string, unknown>;
}

/** 域是进程内单例：每个用例装一次、afterEach 统一释放——漏掉会让下一个用例撞「只能装配一次」。 */
afterEach(() => {
  releaseApi();
  warns.splice(0);
});

describe("围栏", () => {
  it("非回环来源一律 403", async () => {
    const { route } = install();
    const { captured, res } = fakeRes();
    route(ROUTES.bindings).handler(fakeReq({ socket: { remoteAddress: "10.0.0.5" } }), res);
    expect(captured.status).toBe(403);
  });

  it("回环来源但 Host 不是回环一律 403", async () => {
    const { route } = install();
    const { captured, res } = fakeRes();
    route(ROUTES.bindings).handler(fakeReq({ headers: { host: "evil.example.com" } }), res);
    expect(captured.status).toBe(403);
  });

  it("缺少 Host 头一律 403（fail-closed）", async () => {
    const { route } = install();
    const { captured, res } = fakeRes();
    route(ROUTES.bindings).handler(fakeReq({ headers: {} }), res);
    expect(captured.status).toBe(403);
  });

  it("方法不在白名单给 405", async () => {
    const { route } = install();
    const { captured, res } = fakeRes();
    route(ROUTES.bindings).handler(fakeReq({ method: "POST" }), res);
    expect(captured.status).toBe(405);
  });

  it("403 先于 405：非回环 + 方法错仍然只回 403（不泄露路径存在性）", async () => {
    const { route } = install();
    const { captured, res } = fakeRes();
    route(ROUTES.bindings).handler(
      fakeReq({ method: "POST", socket: { remoteAddress: "10.0.0.5" } }),
      res,
    );
    expect(captured.status).toBe(403);
  });

  it("拒绝体不带 referrer（共享层围栏的既定行为）", async () => {
    const { route } = install();
    const { captured, res } = fakeRes();
    route(ROUTES.bindings).handler(fakeReq({ headers: { host: "evil.example.com" } }), res);
    expect(captured.headers["referrer-policy"]).toBe("no-referrer");
  });
});

describe("绑定查询", () => {
  it("缺 session 参数判 400 而不是回空", async () => {
    const { route } = install();
    const { captured, res } = fakeRes();
    await route(ROUTES.bindings).handler(fakeReq({ url: ROUTES.bindings }), res);
    expect(captured.status).toBe(400);
  });

  it("空 session 参数同样判 400", async () => {
    const { route } = install();
    const { captured, res } = fakeRes();
    await route(ROUTES.bindings).handler(fakeReq({ url: ROUTES.bindings + "?session=" }), res);
    expect(captured.status).toBe(400);
  });

  it("命中绑定回 revision 与 worktreePath，且不回 repoRoot", async () => {
    const { route } = install();
    const { captured, res } = fakeRes();
    await route(ROUTES.bindings).handler(fakeReq({ url: ROUTES.bindings + "?session=s1" }), res);
    expect(captured.status).toBe(200);
    const body = jsonOf(captured);
    expect(body["revision"]).toBe(7);
    expect(body["worktreePath"]).toBe("/wt");
    expect(Object.keys(body).sort()).toEqual(["revision", "worktreePath"]);
  });

  it("未命中回 worktreePath: null", async () => {
    const { route } = install();
    const { captured, res } = fakeRes();
    await route(ROUTES.bindings).handler(fakeReq({ url: ROUTES.bindings + "?session=other" }), res);
    expect(jsonOf(captured)["worktreePath"]).toBeNull();
  });

  it("回的是**生效值**：失效绑定（生效值为 null）时路由也回 null，两端不分叉", async () => {
    const { route } = install({ effectiveWorktree: async () => null });
    const { captured, res } = fakeRes();
    await route(ROUTES.bindings).handler(fakeReq({ url: ROUTES.bindings + "?session=s1" }), res);
    expect(jsonOf(captured)["worktreePath"]).toBeNull();
  });

  it("revision 读的是活的现值而不是装配期快照", async () => {
    let revision = 1;
    const { route } = install({ revision: () => revision });
    revision = 42;
    const { captured, res } = fakeRes();
    await route(ROUTES.bindings).handler(fakeReq({ url: ROUTES.bindings + "?session=s1" }), res);
    expect(jsonOf(captured)["revision"]).toBe(42);
  });
});

describe("health", () => {
  it("回 ok、当前 revision、接管状态与会话链读数", async () => {
    const { route } = install();
    const { captured, res } = fakeRes();
    route(ROUTES.health).handler(fakeReq(), res);
    expect(captured.status).toBe(200);
    expect(jsonOf(captured)).toEqual({
      ok: true,
      revision: 7,
      scopeTakeover: "live",
      scopeChain: { storedReads: 0, storedFailures: 0 },
    });
  });

  it("会话链读数读的是活值：持久面坏过一次与坏过两次必须能分开", async () => {
    // 「继承悄悄退回 live-only」是无声降级，探针上的这个读数就是它唯一的落地痕迹。
    let failures = 0;
    const { route } = install({
      chainDiagnostics: () => ({
        storedReads: failures + 1,
        storedFailures: failures,
        lastFailure: failures === 0 ? undefined : "session store unreadable",
      }),
    });
    const first = fakeRes();
    route(ROUTES.health).handler(fakeReq(), first.res);
    expect(jsonOf(first.captured)["scopeChain"]).toEqual({ storedReads: 1, storedFailures: 0 });

    failures = 1;
    const second = fakeRes();
    route(ROUTES.health).handler(fakeReq(), second.res);
    expect(jsonOf(second.captured)["scopeChain"]).toEqual({
      storedReads: 2,
      storedFailures: 1,
      lastFailure: "session store unreadable",
    });
  });

  it("接管状态读的是活值：provider 还没出现时报 waiting", async () => {
    // 「文件根没换」的三种成因必须能从探针上分开，否则真机上只剩「不工作」一个结论。
    let state: "waiting" | "live" = "waiting";
    const { route } = install({ takeoverState: () => state });
    const { captured, res } = fakeRes();
    route(ROUTES.health).handler(fakeReq(), res);
    expect(jsonOf(captured)["scopeTakeover"]).toBe("waiting");

    state = "live";
    const second = fakeRes();
    route(ROUTES.health).handler(fakeReq(), second.res);
    expect(jsonOf(second.captured)["scopeTakeover"]).toBe("live");
  });
});

describe("两端路由一致性", () => {
  it("注册的路径就是 contract 里那两条（单一事实源）", () => {
    const { reg } = install();
    expect(reg.routes.map((r) => r.path).sort()).toEqual([ROUTES.bindings, ROUTES.health].sort());
  });
});

describe("异常收口与卸载", () => {
  it("异步处理器抛异常回 500 并出声，不把异常抛回宿主", async () => {
    const { route } = install({
      effectiveWorktree: async () => {
        throw new Error("boom");
      },
    });
    const { captured, res } = fakeRes();
    route(ROUTES.bindings).handler(fakeReq({ url: ROUTES.bindings + "?session=s1" }), res);
    await new Promise((resolve) => setImmediate(resolve));
    expect(captured.status).toBe(500);
    expect(warns.length).toBe(1);
    expect(warns[0]).toContain("boom");
  });

  it("同步处理器抛异常也回 500 并出声（异步 promise 之外的第二个入口）", () => {
    const { route } = install({
      revision: () => {
        throw new Error("sync boom");
      },
    });
    const { captured, res } = fakeRes();
    // health 的处理器是**同步**的：它抛在 handle(req, res) 那一行，只有同步 catch 接得住。
    route(ROUTES.health).handler(fakeReq(), res);
    expect(captured.status).toBe(500);
    expect(warns.some((warning) => warning.includes("sync boom"))).toBe(true);
  });

  it("注册中途失败：已挂的那条被摘回去再抛，域也不留在半装态", () => {
    const routes: WebRoute[] = [];
    let calls = 0;
    const register = (route: WebRoute): (() => void) => {
      calls += 1;
      // 第一条照常挂上，第二条才炸：这条判据要的正是「已挂的那条会不会被摘回去」。
      if (calls === 2) throw new Error("second register exploded");
      routes.push(route);
      return () => {
        const index = routes.indexOf(route);
        if (index >= 0) routes.splice(index, 1);
      };
    };
    expect(() =>
      installApi({
        register,
        logger,
        binding: { revision: () => 1 },
        scope: {
          effectiveWorktree: async () => null,
          takeoverState: () => "live" as const,
          chainDiagnostics: () => ({ storedReads: 0, storedFailures: 0, lastFailure: undefined }),
        },
      }),
    ).toThrow("second register exploded");
    // 半挂的出口比不挂更糟：它在册、会响应，而摘除器从未生成。
    expect(routes).toEqual([]);
    // 域也没被标成已装配——同一进程里再装一次必须成功（否则组合根的回滚路径就白写了）。
    expect(() => install()).not.toThrow();
  });

  it("release 摘掉全部路由且幂等", () => {
    const { reg } = install();
    expect(reg.routes.length).toBe(2);
    releaseApi();
    expect(reg.routes.length).toBe(0);
    releaseApi();
    expect(reg.routes.length).toBe(0);
  });
});

describe("装配守卫与 release 复位", () => {
  it("第二次装配当场抛错，不静默挂第二份路由", () => {
    const first = install();
    // 说清是哪个域拒绝的：`/只能装配一次/` 这种宽判据在「装配体被整段短路」时也会绿。
    expect(() => install()).toThrow("dsh-worktree-sidebar: api 域只能装配一次");
    expect(first.reg.routes.length).toBe(2);
  });

  it("release 之后再装配只注册一份路由（不叠加）", () => {
    const first = install();
    expect(first.reg.routes.length).toBe(2);
    releaseApi();
    expect(first.reg.routes.length).toBe(0);
    // 重新装配必须重新注册，而不是「反正已经挂过」——否则 release 之后页面就再也读不到数据。
    const second = install();
    expect(second.reg.routes.length).toBe(2);
  });
});

/**
 * git 域**服务层** —— 白盒用例：递手写 exec 面直接驱动门面（真子进程只出现在 integration/git-real）。
 *
 * 为什么这一层必须有判据：仓库判定在**安装期**要给每个新 agent 判一次，而官方 `agents.create()`
 * 的契约是「setup → publication → loop start complete 才返回」（`dsh-agent/lib/index.js:415`），
 * 子会话的**第一回合**正落在那次判定之后。所以「同一个 cwd 不重复起子进程」是功能判据而不是性能优化：
 * 它决定子会话第一回合看不看得见本插件的工具（第六轮第三臂实验：一次 git 子进程 = 103ms = 输；
 * 缓存命中 ≈ 微任务级 = 赢）。TTL 取值纪律与 `belongsTo` 同源，见 `impl/service` 的注释。
 *
 * 缓存只认**正结果**、归属判定回**三态**——这两条都是「一次读不出来不该变成一次永久摘除」的落地：
 * 前者管 `commonDir`（负结果下一刻就可能变真，比如用户在空目录里 `git init`），
 * 后者管 `belongsTo`（只有两侧都确实读到了公共 git 目录，才有资格说「换了仓库」）。
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import type { GitRunResult } from "../../src/server/git/deps.ts";
import * as gitApi from "../../src/server/git/interface.ts";

/** 记原始事实的 exec 面：跑了哪些 argv、跑了几次。 */
function fakeExec(answer: (args: readonly string[]) => GitRunResult) {
  const calls: string[][] = [];
  return {
    calls,
    port: {
      run: async (args: readonly string[]): Promise<GitRunResult> => {
        calls.push([...args]);
        return answer(args);
      },
    },
  };
}

const inRepo: GitRunResult = { ok: true, stdout: ".git\n", stderr: "", code: 0 };
/** git 跑完了并给出否定答案：这是一个**答案**。 */
const notRepo: GitRunResult = {
  ok: false,
  stdout: "",
  stderr: "fatal: not a git repository",
  code: 128,
};
/** 进程根本没起来（spawn ENOENT / 超时被杀）：这不是答案，是问不出来。 */
const execFailed: GitRunResult = { ok: false, stdout: "", stderr: "spawn git ENOENT", code: null };

describe("git 域：仓库判定的 TTL 缓存", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-09-14T00:00:00Z"));
  });

  afterEach(() => {
    gitApi.releaseGit();
    vi.useRealTimers();
  });

  it("同一个目录第二次判定不再起子进程（这就是子会话首回合的那个窗口）", async () => {
    const exec = fakeExec(() => inRepo);
    gitApi.installGit({ exec: exec.port });

    await gitApi.commonDir("/repo");
    await gitApi.commonDir("/repo");

    expect(exec.calls.length).toBe(1);
  });

  it("负结果不进缓存：空目录 git init 之后，下一次判定立刻看得到", async () => {
    // 缓存负结果会把一次「刚 git init 完」的合法调用挡在 30s 之外，而它换来的只是一次省不掉的
    // 子进程（非仓库目录的判定本来就不在热路径上：安装期每个 agent 判一次，工具调用更是稀疏）。
    let initialized = false;
    const exec = fakeExec(() => (initialized ? inRepo : notRepo));
    gitApi.installGit({ exec: exec.port });

    expect(await gitApi.commonDir("/plain")).toBeUndefined();
    initialized = true;
    expect(await gitApi.commonDir("/plain")).toBe("/plain/.git");

    expect(exec.calls.length).toBe(2);
  });

  it("TTL 之内命中、过期后重新问 git", async () => {
    const exec = fakeExec(() => inRepo);
    gitApi.installGit({ exec: exec.port });

    await gitApi.commonDir("/repo");
    vi.setSystemTime(new Date(Date.now() + 29_000));
    await gitApi.commonDir("/repo");
    expect(exec.calls.length).toBe(1);

    vi.setSystemTime(new Date(Date.now() + 2_000));
    await gitApi.commonDir("/repo");
    expect(exec.calls.length).toBe(2);
  });

  it("release 丢掉缓存：下一次装配必须重新判定", async () => {
    const exec = fakeExec(() => inRepo);
    gitApi.installGit({ exec: exec.port });
    await gitApi.commonDir("/repo");

    gitApi.releaseGit();
    gitApi.installGit({ exec: exec.port });
    await gitApi.commonDir("/repo");

    expect(exec.calls.length).toBe(2);
  });

  it("条目上限：写满即整表丢弃（加速缓存，不是需要保真的状态）", async () => {
    const exec = fakeExec(() => inRepo);
    gitApi.installGit({ exec: exec.port });

    for (let i = 0; i < 257; i += 1) await gitApi.commonDir("/repo-" + i);
    // 上限 256：写第 257 个时整表被丢弃，于是最早那个目录要重新判定。
    await gitApi.commonDir("/repo-0");

    expect(exec.calls.filter((args) => args[1] === "/repo-0").length).toBe(2);
  });
});

describe("git 域：归属判定是三态", () => {
  afterEach(() => gitApi.releaseGit());

  /** 每个目录一个公共 git 目录答案；缺席的目录一律答「不是仓库」。 */
  function byDir(answers: Record<string, GitRunResult>) {
    return fakeExec((args) => answers[args[1] ?? ""] ?? notRepo);
  }

  it("两侧读到同一个公共 git 目录 ⇒ same", async () => {
    // worktree 侧必须回**同一个绝对路径**：`--git-common-dir` 平时回相对的 `.git`，
    // 而相对路径要按各自的 dir 解析，所以夹具这里直接给绝对值（解析规则由 computeCommonDir 负责）。
    const exec = byDir({ "/repo": inRepo, "/repo-wt": { ...inRepo, stdout: "/repo/.git\n" } });
    gitApi.installGit({ exec: exec.port });
    expect(await gitApi.belongsTo("/repo-wt", "/repo")).toEqual({ kind: "same" });
  });

  it("两侧都读到了、值不同 ⇒ different（这才允许摘掉用户的登记）", async () => {
    const exec = byDir({ "/repo": inRepo, "/other": inRepo });
    gitApi.installGit({ exec: exec.port });
    const reading = await gitApi.belongsTo("/other", "/repo");
    expect(reading.kind).toBe("different");
  });

  it("worktree 侧 git 执行失败 ⇒ unknown，原因里带上 stderr", async () => {
    const exec = byDir({ "/repo": inRepo, "/gone": execFailed });
    gitApi.installGit({ exec: exec.port });
    const reading = await gitApi.belongsTo("/gone", "/repo");
    expect(reading.kind).toBe("unknown");
    if (reading.kind !== "unknown") throw new Error("unreachable");
    expect(reading.reason).toContain("spawn git ENOENT");
    // 「问不出来」不是「不是工作树」：写路径要据此给出不同的失败文案。
    expect(reading.notRepo).toBe(false);
  });

  it("worktree 侧是「不是仓库」也归 unknown（权限失败与目录被换掉在读数上同形）", async () => {
    // 这条判据是刻意的保守：`chmod 000` 的真实 git 也是退出码 128 的失败，与「真的不是仓库」
    // 在读数上分不开。分不开就不摘——摘错的代价是永久丢掉用户的登记，留下的代价只是一次告警。
    const exec = byDir({ "/repo": inRepo, "/gone": notRepo });
    gitApi.installGit({ exec: exec.port });
    const reading = await gitApi.belongsTo("/gone", "/repo");
    expect(reading.kind).toBe("unknown");
    if (reading.kind !== "unknown") throw new Error("unreachable");
    expect(reading.reason).toContain("/gone");
    expect(reading.notRepo).toBe(true);
  });

  it("主仓库侧读不出来 ⇒ unknown", async () => {
    const exec = byDir({ "/repo-wt": inRepo });
    gitApi.installGit({ exec: exec.port });
    expect((await gitApi.belongsTo("/repo-wt", "/repo")).kind).toBe("unknown");
  });

  it("结论进缓存：同一个键第二次判定不再起子进程", async () => {
    const exec = byDir({ "/repo": inRepo, "/other": inRepo });
    gitApi.installGit({ exec: exec.port });
    await gitApi.belongsTo("/other", "/repo");
    await gitApi.belongsTo("/other", "/repo");
    expect(exec.calls.length).toBe(2);
  });

  it("unknown 不进缓存：问不出来之后状态变了，下一次判定必须重新问（否则「稍后重试」是空话）", async () => {
    // 写路径对 unknown 是 fail-closed，并回给调用方一句「等目录可读后重试」。把那次 unknown 缓存 30s
    // 就把这句建议变成确定性失败——真实的重试场景正是「目录刚变成 worktree」或「权限刚修好」。
    let ready = false;
    const exec = fakeExec((args) =>
      (args[1] ?? "") === "/repo"
        ? inRepo
        : ready
          ? { ...inRepo, stdout: "/repo/.git\n" }
          : notRepo,
    );
    gitApi.installGit({ exec: exec.port });

    expect((await gitApi.belongsTo("/repo-wt", "/repo")).kind).toBe("unknown");
    ready = true;
    expect(await gitApi.belongsTo("/repo-wt", "/repo")).toEqual({ kind: "same" });
  });
});

describe("git 域：其余读数的失败形态", () => {
  afterEach(() => gitApi.releaseGit());

  it("listWorktrees 失败回空数组，不抛异常（它只是失败提示的附带信息）", async () => {
    const exec = fakeExec(() => notRepo);
    gitApi.installGit({ exec: exec.port });
    await expect(gitApi.listWorktrees("/repo")).resolves.toEqual([]);
  });

  it("headBranch 把 detached 的 HEAD 读成「没有分支名」", async () => {
    const exec = fakeExec(() => ({ ok: true, stdout: "HEAD\n", stderr: "", code: 0 }));
    gitApi.installGit({ exec: exec.port });
    expect(await gitApi.headBranch("/wt")).toBeUndefined();
  });

  it("headBranch 在 git 失败时回 undefined", async () => {
    const exec = fakeExec(() => notRepo);
    gitApi.installGit({ exec: exec.port });
    expect(await gitApi.headBranch("/wt")).toBeUndefined();
  });

  it("git 成功但没有输出 ⇒ 公共目录读不出来（failed，不是「不是仓库」）", async () => {
    const exec = fakeExec(() => ({ ok: true, stdout: "", stderr: "", code: 0 }));
    gitApi.installGit({ exec: exec.port });
    const reading = await gitApi.belongsTo("/wt", "/repo");
    expect(reading.kind).toBe("unknown");
  });
});

