/**
 * host/sessions 适配层 —— 会话链的**两个来源**怎么合成三态。
 *
 * 为什么这一层必须有判据：scope 域的用例递的全是**假端口**，真正把官方 live 面与持久面
 * 翻成 parent / root / not-live 的映射、以及「持久面按调用时刻取」这条时机纪律都住在这里。
 * 把 root 与 not-live 换一下，或把软取提到装配期，全仓没有一条判据会红——而这两种错法
 * 分别把「每个普通会话白加一次持久读取」与「晚挂的后端永久缺席」带进来。
 */
import { describe, expect, it } from "vitest";
import type { SessionsFace, StoredSessionsFace } from "../../src/server/host/sessions.ts";
import { bindSessions } from "../../src/server/host/sessions.ts";

/** 会话 header 的创建时间：身份核对的凭据。 */
const BIRTH = 1_700_000_000_000;

/** 官方 live 面：`header.parentSession` 有无都要能表达（无父 ≠ 不在册）。 */
function liveFace(table: Record<string, string | undefined>, birth: number = BIRTH) {
  const calls: string[] = [];
  const face: SessionsFace = {
    get: (id) => {
      const key = String(id);
      calls.push(key);
      if (!(key in table)) return undefined;
      const parent = table[key];
      return {
        header: { createdAt: birth, ...(parent === undefined ? {} : { parentSession: parent }) },
      };
    },
  };
  return { face, calls };
}

/** 官方持久面：单会话 header；查不到回 undefined（契约如此，不是抛错）。 */
function storedFace(table: Record<string, string>, birth: number = BIRTH) {
  const calls: string[] = [];
  const face: StoredSessionsFace = {
    stat: async (id) => {
      const key = String(id);
      calls.push(key);
      const parent = table[key];
      return parent === undefined
        ? undefined
        : { header: { createdAt: birth, parentSession: parent } };
    },
  };
  return { face, calls };
}

describe("bindSessions：三态映射", () => {
  it("活着的顶层会话回 root，且**不问持久面**（确定的到顶不该变成请求路径上的一次 IO）", () => {
    const live = liveFace({ s1: undefined });
    const stored = storedFace({ s1: "谁都不该问" });

    expect(bindSessions(live.face, () => stored.face).liveParentOf("s1")).toEqual({ kind: "root" });
    expect(stored.calls).toEqual([]);
    expect(live.calls).toEqual(["s1"]);
  });

  it("活会话有父时回 parent(id)", () => {
    const live = liveFace({ child: "parent" });
    expect(bindSessions(live.face, () => undefined).liveParentOf("child")).toEqual({
      kind: "parent",
      id: "parent",
    });
  });

  it("不在册回 not-live，只有这一态才回落持久面（父链按 header 原样给出）", async () => {
    const live = liveFace({});
    const stored = storedFace({ child: "parent" });
    const port = bindSessions(live.face, () => stored.face);

    expect(port.liveParentOf("child")).toEqual({ kind: "not-live" });
    expect(await port.storedParentOf("child")).toBe("parent");
    expect(stored.calls).toEqual(["child"]);
  });

  it("持久面里也没有这条会话（契约是回 undefined，不是抛）→ 到顶", async () => {
    const port = bindSessions(liveFace({}).face, () => storedFace({}).face);
    expect(await port.storedParentOf("ghost")).toBeUndefined();
  });

  it("持久面缺席（组合里没挂后端）＝如实回 undefined，不抛", async () => {
    const port = bindSessions(liveFace({}).face, () => undefined);
    expect(await port.storedParentOf("child")).toBeUndefined();
  });

  it("持久面按**调用时刻**取：后端晚挂之后那一次就必须读得到", async () => {
    const stored = storedFace({ child: "parent" });
    let backend: StoredSessionsFace | undefined = undefined;
    const port = bindSessions(liveFace({}).face, () => backend);

    expect(await port.storedParentOf("child")).toBeUndefined();
    backend = stored.face;
    expect(await port.storedParentOf("child")).toBe("parent");
  });
});

describe("bindSessions：会话身份", () => {
  it("活会话的身份来自活 header，且**不问持久面**（重启后复用 id 的核对不该变成常态 IO）", () => {
    const live = liveFace({ s1: undefined }, 4242);
    const stored = storedFace({ s1: "不该问" }, 999);

    const port = bindSessions(live.face, () => stored.face);
    expect(port.liveIdentityOf("s1")).toEqual({ createdAt: 4242 });
    expect(stored.calls).toEqual([]);
  });

  it("不在册时活身份缺席（undefined），由调用方决定要不要回落持久面", () => {
    const port = bindSessions(liveFace({}).face, () => storedFace({ s1: "parent" }).face);
    expect(port.liveIdentityOf("ghost")).toBeUndefined();
  });

  it("已结束会话的身份走持久面，读到的就是 header 的 createdAt", async () => {
    const stored = storedFace({ s1: "parent" }, 777);
    const port = bindSessions(liveFace({}).face, () => stored.face);
    expect(await port.storedIdentityOf("s1")).toEqual({ createdAt: 777 });
    expect(stored.calls).toEqual(["s1"]);
  });

  it("持久面里没有这条会话、或后端缺席 ⇒ undefined（不抛，调用方因此保住登记）", async () => {
    const missing = bindSessions(liveFace({}).face, () => storedFace({}).face);
    expect(await missing.storedIdentityOf("ghost")).toBeUndefined();
    const absent = bindSessions(liveFace({}).face, () => undefined);
    expect(await absent.storedIdentityOf("ghost")).toBeUndefined();
  });

  it("畸形 header：createdAt 不是有限数 ⇒ 按「读不出来」回 undefined，不冒充另一个会话", async () => {
    // scope 域把「凭据与登记不同」当**正面证据**并据此摘掉用户的绑定，所以畸形 header 必须被读成
    // 「读不出来」（保留登记），而不是读成一个不同的值（摘掉登记）。两个来源都要拦。
    const nan = { get: () => ({ header: { createdAt: Number.NaN } }) };
    expect(bindSessions(nan, () => undefined).liveIdentityOf("s1")).toBeUndefined();

    const infinite = { get: () => ({ header: { createdAt: Number.POSITIVE_INFINITY } }) };
    expect(bindSessions(infinite, () => undefined).liveIdentityOf("s1")).toBeUndefined();

    const stored: StoredSessionsFace = {
      stat: async () => ({ header: { createdAt: Number.NaN } }),
    };
    expect(
      await bindSessions({ get: () => undefined }, () => stored).storedIdentityOf("s1"),
    ).toBeUndefined();
  });

  it("持久面抛错时**照原样抛回**：收口与记账都在 scope 域，适配层不替它决定", async () => {
    const broken: StoredSessionsFace = {
      stat: async () => {
        throw new Error("session store offline");
      },
    };
    const port = bindSessions(liveFace({}).face, () => broken);
    await expect(port.storedIdentityOf("s1")).rejects.toThrow("session store offline");
  });
});

/**
 * 宿主 agent 适配器（src/server/host/agents.ts）—— 白盒用例：递手写窄端口直接驱动 `bindAgents`。
 *
 * 为什么必须白盒：适配器的输入是宿主 `ctx`，而 `publish` 的未知 id 分支在真机上不可达
 * （tools 域只会拿 list/subscribe 刚递出去的 face 回来）。把它拆成窄端口之后，这条分支
 * 才第一次有了判据——「未装配的占位要抛错」，而不是静默回一个空释放器。
 *
 * 假件只记原始事实（装了什么、拆了什么、回调了几次），不替适配器做任何判断。
 */
import { describe, expect, it } from "vitest";
import type { ToolDefinition } from "@deepseek-ai/dsh-tools";
import { bindAgents } from "../../src/server/host/agents.ts";
import type { AgentHostPort, HostAgentLike } from "../../src/server/host/agents.ts";
import type { AgentFace } from "../../src/server/tools/deps.ts";

/** 一个 agent 作用域的最小假件：适配器只读 id 与 session.header.cwd。 */
function makeAgent(id: string, cwd: string | undefined) {
  const registered: ToolDefinition[] = [];
  const disposed: ToolDefinition[] = [];
  const agent: HostAgentLike = {
    id,
    session: { header: { cwd } },
    ctx: {
      tools: {
        register: (definition) => {
          registered.push(definition);
          return () => {
            disposed.push(definition);
          };
        },
      },
      // 官方 effect 的语义：效应体立即执行并交出它的 disposer，effect 的释放器触发那个 disposer。
      effect: (execute) => {
        const disposeEffect = execute();
        return () => {
          disposeEffect();
        };
      },
    },
  };
  return { agent, registered, disposed };
}

/** 宿主面假件：agent 枚举由用例给定，事件经 `emit` 手工派发，`remove` 模拟退场。 */
function fakeHost(initial: readonly HostAgentLike[]) {
  const events: string[] = [];
  const handlers: Array<(payload: { agent: HostAgentLike }) => void> = [];
  const agents = [...initial];
  const port: AgentHostPort = {
    on: (event, handler) => {
      events.push(event);
      handlers.push(handler);
      return () => undefined;
    },
    all: () => agents,
  };
  return {
    port,
    events,
    emit: (agent: HostAgentLike) => {
      for (const handler of handlers) handler({ agent });
    },
    remove: (agent: HostAgentLike) => {
      const index = agents.indexOf(agent);
      if (index >= 0) agents.splice(index, 1);
    },
  };
}

/** 两个占位工具定义：适配器只把它们转手给 `ctx.tools.register`，不读任何字段。 */
const DEFINITIONS = [
  { name: "ws_worktree_register" },
  { name: "ws_worktree_remove" },
] as unknown as readonly ToolDefinition[];

describe("agent 注册面", () => {
  it("list() 枚举过的 agent 能 publish，返回的释放器摘掉它装进去的工具", () => {
    const a1 = makeAgent("a1", "/repo");
    const { port } = fakeHost([a1.agent]);
    const agents = bindAgents(port);

    const faces = agents.list();
    expect(faces).toEqual([{ id: "a1", cwd: "/repo" }]);
    const dispose = agents.publish(faces[0], DEFINITIONS);
    expect(a1.registered).toEqual([...DEFINITIONS]);

    dispose();
    expect(a1.disposed).toEqual([...DEFINITIONS]);
  });

  it("subscribe 收到 agent 后同样能 publish", () => {
    // 事件到达时这个 agent 已在枚举里——真机上 agent/created 就是它入册的那一刻。
    const a2 = makeAgent("a2", "/repo");
    const host = fakeHost([a2.agent]);
    const agents = bindAgents(host.port);
    const seen: AgentFace[] = [];
    agents.subscribe((face) => {
      seen.push(face);
    });

    host.emit(a2.agent);
    expect(host.events).toEqual(["agent/created"]);
    expect(seen).toEqual([{ id: "a2", cwd: "/repo" }]);

    agents.publish(seen[0], DEFINITIONS);
    expect(a2.registered).toEqual([...DEFINITIONS]);
  });

  it("publish 一个从没注册过的 id 当场抛错，不静默回空释放器", () => {
    const { port } = fakeHost([]);
    const agents = bindAgents(port);

    expect(() => agents.publish({ id: "ghost", cwd: "/repo" }, DEFINITIONS)).toThrow(
      "dsh-worktree-sidebar: agent ghost 未注册，拒绝把工具装进未知作用域",
    );
  });

  it("子代理同样被回调并装得上：判定不再按顶层枚举过滤", () => {
    const parent = makeAgent("p1", "/repo");
    const child = makeAgent("c1", "/repo");
    const host = fakeHost([parent.agent, child.agent]);
    const agents = bindAgents(host.port);
    const seen: AgentFace[] = [];
    agents.subscribe((face) => {
      seen.push(face);
    });

    host.emit(child.agent);
    host.emit(parent.agent);
    expect(seen).toEqual([
      { id: "c1", cwd: "/repo" },
      { id: "p1", cwd: "/repo" },
    ]);

    for (const face of seen) agents.publish(face, DEFINITIONS);
    expect(child.registered).toEqual([...DEFINITIONS]);
    expect(parent.registered).toEqual([...DEFINITIONS]);
  });

  it("退场后的 agent 不再能 publish：按 id 现查，不留永不释放的 agent 缓存", () => {
    const a1 = makeAgent("a1", "/repo");
    const host = fakeHost([a1.agent]);
    const agents = bindAgents(host.port);
    const faces = agents.list();
    // 递出 face 之后、publish 之前该 agent 退场：必须抛错，而不是往一个已释放的作用域里注册。
    // 这条判据同时钉住「不留缓存」——缓存过 agent 对象就永远不会走到这里。
    host.remove(a1.agent);
    expect(() => agents.publish(faces[0], DEFINITIONS)).toThrow(
      "dsh-worktree-sidebar: agent a1 未注册，拒绝把工具装进未知作用域",
    );
  });

  it("list() 枚举子代理：快照里没有顶层与子之分", () => {
    const parent = makeAgent("p1", "/repo");
    const child = makeAgent("c1", "/repo/sub");
    const { port } = fakeHost([parent.agent, child.agent]);
    const agents = bindAgents(port);

    expect(agents.list()).toEqual([
      { id: "p1", cwd: "/repo" },
      { id: "c1", cwd: "/repo/sub" },
    ]);
  });
});

/**
 * binding 域纯逻辑 —— 形状校验与 revision 规则。
 *
 * 为什么值得逐条断言：这三条规则每一条失效都对应一种「静默挂错目录」——
 * 损坏文件不回落空表、版本更高也照读、摘不存在的会话也涨 revision（客户端白刷）。
 * 它们都不抛异常，只让文件树指向错的地方。
 */
import { describe, expect, it } from "vitest";
import { BINDINGS_VERSION } from "../../src/server/binding/interface.ts";
import {
  dropBinding,
  emptyTable,
  parseTable,
  putBinding,
  serializeTable,
  validateRecord,
} from "../../src/server/binding/impl/model/index.ts";

const record = {
  repoRoot: "/repo",
  worktreeRoot: "/repo-wt",
  branch: "feature",
  createdAt: "2026-09-14T00:00:00.000Z",
  sessionCreatedAt: 1_700_000_000_000,
};

describe("emptyTable", () => {
  it("用当前契约版本，revision 从 0 起", () => {
    expect(emptyTable()).toEqual({ version: BINDINGS_VERSION, revision: 0, bindings: {} });
  });
});

describe("parseTable 的损坏回落", () => {
  it("非 JSON 回落空表", () => {
    expect(parseTable("{ not json")).toEqual(emptyTable());
  });

  it("JSON 但不是对象回落空表", () => {
    expect(parseTable("42")).toEqual(emptyTable());
    expect(parseTable("null")).toEqual(emptyTable());
    expect(parseTable('"x"')).toEqual(emptyTable());
  });

  it("版本号更高回落空表而不是猜着读", () => {
    const text = JSON.stringify({ version: BINDINGS_VERSION + 1, revision: 3, bindings: {} });
    expect(parseTable(text)).toEqual(emptyTable());
  });

  it("revision 缺失、负数或非有限值回落空表", () => {
    for (const bad of [undefined, -1, "3", null]) {
      const text = JSON.stringify({ version: BINDINGS_VERSION, revision: bad, bindings: {} });
      expect(parseTable(text)).toEqual(emptyTable());
    }
  });

  it("bindings 不是对象回落空表", () => {
    const text = JSON.stringify({ version: BINDINGS_VERSION, revision: 0, bindings: [] });
    expect(parseTable(text)).toEqual(emptyTable());
  });
});

describe("parseTable 的逐条校验", () => {
  it("丢弃形状不合格的记录但保留合格的", () => {
    const text = JSON.stringify({
      version: BINDINGS_VERSION,
      revision: 7,
      bindings: {
        good: record,
        missingRoot: { worktreeRoot: "/w", branch: "b", createdAt: "t" },
        emptyWorktree: { repoRoot: "/r", worktreeRoot: "", branch: "b", createdAt: "t" },
        wrongType: { repoRoot: "/r", worktreeRoot: "/w", branch: 5, createdAt: "t" },
        nope: null,
      },
    });
    const table = parseTable(text);
    expect(Object.keys(table.bindings)).toEqual(["good"]);
    expect(table.revision).toBe(7);
  });

  it("丢掉空 sessionId 的条目", () => {
    const text = JSON.stringify({
      version: BINDINGS_VERSION,
      revision: 1,
      bindings: { "": record, ok: record },
    });
    expect(Object.keys(parseTable(text).bindings)).toEqual(["ok"]);
  });
});

describe("validateRecord", () => {
  it("接受完整记录并原样返回字段", () => {
    expect(validateRecord(record)).toEqual(record);
  });

  it("拒绝空串路径", () => {
    expect(validateRecord({ ...record, repoRoot: "" })).toBeUndefined();
    expect(validateRecord({ ...record, worktreeRoot: "" })).toBeUndefined();
  });

  it("拒绝非字符串字段", () => {
    expect(validateRecord({ ...record, branch: undefined })).toBeUndefined();
    expect(validateRecord({ ...record, createdAt: 0 })).toBeUndefined();
  });

  it("拒绝没有会话身份凭据的记录（缺席、非数字、非有限值）", () => {
    // 这条是「会话 id 会被复用」的第一道闸门：凭据缺席的记录留着，就等于留着
    // 「重启后一个新会话继承了上一进程的登记」这条静默看错地方的路径。
    const { sessionCreatedAt: _omitted, ...withoutFingerprint } = record;
    expect(validateRecord(withoutFingerprint)).toBeUndefined();
    expect(validateRecord({ ...record, sessionCreatedAt: "1700000000000" })).toBeUndefined();
    expect(validateRecord({ ...record, sessionCreatedAt: Number.NaN })).toBeUndefined();
  });
});

describe("putBinding", () => {
  it("写入并递增 revision，且不改动入参", () => {
    const base = emptyTable();
    const next = putBinding(base, "s1", record);
    expect(next.revision).toBe(1);
    expect(next.bindings["s1"]).toEqual(record);
    expect(base.revision).toBe(0);
    expect(base.bindings).toEqual({});
  });

  it("覆盖同一会话仍递增 revision", () => {
    const once = putBinding(emptyTable(), "s1", record);
    const twice = putBinding(once, "s1", { ...record, branch: "other" });
    expect(twice.revision).toBe(2);
    expect(twice.bindings["s1"]?.branch).toBe("other");
  });
});

describe("dropBinding", () => {
  it("目标不存在时原样返回同一对象（不涨 revision）", () => {
    const base = putBinding(emptyTable(), "s1", record);
    expect(dropBinding(base, "absent")).toBe(base);
  });

  it("目标存在时摘掉并递增 revision", () => {
    const base = putBinding(emptyTable(), "s1", record);
    const next = dropBinding(base, "s1");
    expect(next.revision).toBe(2);
    expect(next.bindings["s1"]).toBeUndefined();
    expect(base.bindings["s1"]).toEqual(record);
  });
});

describe("serializeTable", () => {
  it("序列化后再解析回等价内容", () => {
    const base = putBinding(emptyTable(), "s1", record);
    expect(parseTable(serializeTable(base))).toEqual(base);
  });

  it("以换行结尾", () => {
    expect(serializeTable(emptyTable()).endsWith("\n")).toBe(true);
  });
});

/**
 * git 域 argv 构造与输出解析 —— 纯函数逐字断言。
 *
 * 为什么逐字断言 argv：`--` 的位置与 `-b` / `--detach` 的次序是**安全属性**而不是风格。
 * 少了 `--`，一个名为 `--force` 的路径就会被 git 当成标志；省略分支时不显式 `--detach`，
 * 路径 basename 会被 git 当成新分支名二次解析（含空格即 fatal，以 `-` 开头即被当开关）；
 * 分支名校验少一步，一个含换行的分支名就能改写 git 的其它参数。这些失效都不报错，只做错事。
 */
import { describe, expect, it } from "vitest";
import {
  addWorktreeArgs,
  checkRefFormatArgs,
  commonDirArgs,
  headBranchArgs,
  parseSingleLine,
  parseWorktreeList,
  removeWorktreeArgs,
  revParseCommitArgs,
  worktreeListArgs,
} from "../../src/server/git/impl/inspect/index.ts";

describe("argv 构造", () => {
  it("查询类一律用 -C 指定目录，不依赖进程 cwd", () => {
    expect(commonDirArgs("/repo")).toEqual(["-C", "/repo", "rev-parse", "--git-common-dir"]);
    expect(worktreeListArgs("/repo")).toEqual(["-C", "/repo", "worktree", "list", "--porcelain"]);
    expect(headBranchArgs("/repo")).toEqual(["-C", "/repo", "rev-parse", "--abbrev-ref", "HEAD"]);
  });

  it("分支名交给 git 自己校验", () => {
    expect(checkRefFormatArgs("feature/x")).toEqual(["check-ref-format", "--branch", "feature/x"]);
  });

  it("新建 worktree：有分支时 -b 在 -- 之前，路径在 -- 之后", () => {
    expect(addWorktreeArgs("/repo", "/wt", "feature", undefined)).toEqual([
      "-C",
      "/repo",
      "worktree",
      "add",
      "-b",
      "feature",
      "--",
      "/wt",
    ]);
  });

  it("新建 worktree：不给分支时补 --detach，而不是没有标志", () => {
    // 省略 branch 时 git 的默认行为是「新建一个以目录 basename 命名的分支」：basename 含空格
    // （macOS 家目录常见）会 fatal，以 `-` 开头会被当成开关——`--` 挡不住这条二次解析链路。
    expect(addWorktreeArgs("/repo", "/wt", undefined, undefined)).toEqual([
      "-C",
      "/repo",
      "worktree",
      "add",
      "--detach",
      "--",
      "/wt",
    ]);
    // 对含空格与以 - 开头的 basename 也一视同仁：argv 里没有把它们当分支名的那条路径。
    expect(addWorktreeArgs("/repo", "/wt space", undefined, undefined)).toContain("--detach");
    expect(addWorktreeArgs("/repo", "/-dash", undefined, undefined)).toContain("--detach");
  });

  it("删除 worktree：--force 在 -- 之前", () => {
    expect(removeWorktreeArgs("/repo", "/wt", true)).toEqual([
      "-C",
      "/repo",
      "worktree",
      "remove",
      "--force",
      "--",
      "/wt",
    ]);
    expect(removeWorktreeArgs("/repo", "/wt", false)).toEqual([
      "-C",
      "/repo",
      "worktree",
      "remove",
      "--",
      "/wt",
    ]);
  });

  it("形如选项的路径落在 -- 之后（参数注入的挡板）", () => {
    const args = addWorktreeArgs("/repo", "--force", undefined, undefined);
    expect(args.indexOf("--")).toBeLessThan(args.indexOf("--force"));
    const removal = removeWorktreeArgs("/repo", "--force", false);
    expect(removal.indexOf("--")).toBeLessThan(removal.indexOf("--force"));
  });
});

describe("起点与 rev-parse 的 argv", () => {
  it("起点落在 -- 与 path 之后，且递进来的必须是归一化过的 SHA", () => {
    expect(addWorktreeArgs("/repo", "/wt", "feature", "abc123")).toEqual([
      "-C",
      "/repo",
      "worktree",
      "add",
      "-b",
      "feature",
      "--",
      "/wt",
      "abc123",
    ]);
    expect(addWorktreeArgs("/repo", "/wt", undefined, "abc123")).toEqual([
      "-C",
      "/repo",
      "worktree",
      "add",
      "--detach",
      "--",
      "/wt",
      "abc123",
    ]);
  });

  it("不给起点时不追加位置参数（缺省由 git 取仓库 HEAD）", () => {
    expect(addWorktreeArgs("/repo", "/wt", "feature", undefined)).toEqual([
      "-C",
      "/repo",
      "worktree",
      "add",
      "-b",
      "feature",
      "--",
      "/wt",
    ]);
  });

  it("起点解析：^{commit} 让 tag 也落到提交，--quiet 让失败走退出码", () => {
    expect(revParseCommitArgs("/repo", "origin/main")).toEqual([
      "-C",
      "/repo",
      "rev-parse",
      "--verify",
      "--quiet",
      "origin/main^{commit}",
    ]);
  });
});

describe("parseSingleLine", () => {
  it("取首行并去掉首尾空白", () => {
    expect(parseSingleLine("  /repo/.git  \n")).toBe("/repo/.git");
  });

  it("空输出返回 undefined 而不是空串", () => {
    expect(parseSingleLine("")).toBeUndefined();
    expect(parseSingleLine("   \n  ")).toBeUndefined();
  });
});

describe("parseWorktreeList", () => {
  it("解析多块、分支与 detached", () => {
    const stdout = [
      "worktree /repo",
      "HEAD abc",
      "branch refs/heads/main",
      "",
      "worktree /wt",
      "HEAD def",
      "branch refs/heads/feature",
      "",
      "worktree /wt2",
      "HEAD 123",
      "detached",
      "",
    ].join("\n");
    expect(parseWorktreeList(stdout)).toEqual([
      { path: "/repo", branch: "refs/heads/main", detached: false },
      { path: "/wt", branch: "refs/heads/feature", detached: false },
      { path: "/wt2", branch: undefined, detached: true },
    ]);
  });

  it("忽略没有 worktree 行的块", () => {
    expect(parseWorktreeList("HEAD abc\n\n")).toEqual([]);
  });

  it("空输入返回空数组", () => {
    expect(parseWorktreeList("")).toEqual([]);
  });
});

/**
 * 会话快照的改写源 —— 引用稳定性、最小改写、未绑定即透明。
 *
 * 三条都是「失效了也不报错」的类型：引用不稳定只会让右栏持续重渲染，
 * 改多了字段会让预览与命令面板看到被我们改过的世界，未绑定不透明则等于插件在没绑定时也改变行为。
 */
import { describe, expect, it } from "vitest";
import { createSessionsSource } from "../../src/client/source.ts";

function realOf(byId: Record<string, unknown>) {
  const listeners = new Set<() => void>();
  let snapshot: { byId: Record<string, unknown> } = { byId };
  return {
    source: {
      getSnapshot: () => snapshot,
      subscribe: (listener: () => void) => {
        listeners.add(listener);
        return () => listeners.delete(listener);
      },
    },
    replace(next: Record<string, unknown>) {
      snapshot = { byId: next };
      for (const listener of [...listeners]) listener();
    },
    listenerCount: () => listeners.size,
  };
}

describe("未绑定时完全透明", () => {
  it("原样返回真实快照（同一个对象引用）", () => {
    const real = realOf({ s1: { cwd: "/repo" } });
    const source = createSessionsSource(real.source, "s1", () => null);
    expect(source.getSnapshot()).toBe(real.source.getSnapshot());
  });
});

describe("绑定后只改写一个字段", () => {
  it("该会话的 cwd 换成 worktree，其余字段与其它会话保持原引用", () => {
    const entry = { cwd: "/repo", title: "t", other: { deep: true } };
    const other = { cwd: "/elsewhere" };
    const real = realOf({ s1: entry, s2: other });
    const source = createSessionsSource(real.source, "s1", () => "/wt");
    const snapshot = source.getSnapshot() as { byId: Record<string, Record<string, unknown>> };
    expect(snapshot.byId["s1"]?.["cwd"]).toBe("/wt");
    expect(snapshot.byId["s1"]?.["title"]).toBe("t");
    expect(snapshot.byId["s1"]?.["other"]).toBe(entry.other);
    expect(snapshot.byId["s2"]).toBe(other);
  });

  it("byId 缺失或没有该会话时原样返回（不凭空造会话）", () => {
    const empty = { getSnapshot: () => ({}), subscribe: () => () => undefined };
    expect(createSessionsSource(empty, "s1", () => "/wt").getSnapshot()).toEqual({});

    const real = realOf({ s2: { cwd: "/x" } });
    const source = createSessionsSource(real.source, "s1", () => "/wt");
    expect(source.getSnapshot()).toBe(real.source.getSnapshot());
  });
});

describe("引用稳定性", () => {
  it("同一真实快照 + 同一路径回同一个对象", () => {
    const real = realOf({ s1: { cwd: "/repo" } });
    const source = createSessionsSource(real.source, "s1", () => "/wt");
    expect(source.getSnapshot()).toBe(source.getSnapshot());
  });

  it("真实快照换了就重算", () => {
    const real = realOf({ s1: { cwd: "/repo" } });
    const source = createSessionsSource(real.source, "s1", () => "/wt");
    const before = source.getSnapshot();
    real.replace({ s1: { cwd: "/repo" } });
    expect(source.getSnapshot()).not.toBe(before);
  });

  it("路径换了就重算", () => {
    const real = realOf({ s1: { cwd: "/repo" } });
    let path: string | null = "/wt-a";
    const source = createSessionsSource(real.source, "s1", () => path);
    const before = source.getSnapshot();
    path = "/wt-b";
    expect(source.getSnapshot()).not.toBe(before);
  });

  it("从绑定回到未绑定时回真实快照本身", () => {
    const real = realOf({ s1: { cwd: "/repo" } });
    let path: string | null = "/wt";
    const source = createSessionsSource(real.source, "s1", () => path);
    expect(source.getSnapshot()).not.toBe(real.source.getSnapshot());
    path = null;
    expect(source.getSnapshot()).toBe(real.source.getSnapshot());
  });
});

describe("订阅", () => {
  it("真实源与本地 notify 都会通知订阅者", () => {
    const real = realOf({ s1: { cwd: "/repo" } });
    const source = createSessionsSource(real.source, "s1", () => "/wt");
    let calls = 0;
    const unsubscribe = source.subscribe(() => {
      calls += 1;
    });
    real.replace({ s1: { cwd: "/repo" } });
    expect(calls).toBe(1);
    source.notify();
    expect(calls).toBe(2);
    unsubscribe();
    source.notify();
    expect(calls).toBe(2);
  });

  it("退订同时摘掉真实源的订阅（不留悬挂监听）", () => {
    const real = realOf({ s1: { cwd: "/repo" } });
    const source = createSessionsSource(real.source, "s1", () => "/wt");
    const unsubscribe = source.subscribe(() => undefined);
    expect(real.listenerCount()).toBe(1);
    unsubscribe();
    expect(real.listenerCount()).toBe(0);
  });

  it("notify 遍历副本：回调里退订不打断本轮其余订阅者", () => {
    const real = realOf({ s1: { cwd: "/repo" } });
    const source = createSessionsSource(real.source, "s1", () => "/wt");
    const seen: string[] = [];
    const first = source.subscribe(() => {
      seen.push("first");
      first();
    });
    source.subscribe(() => seen.push("second"));
    source.notify();
    expect(seen).toEqual(["first", "second"]);
  });
});

